---
import BaseLayout from '../ui/layouts/BaseLayout.astro';
const recoveryHref = Astro.locals.user ? '/dashboard' : '/login';
const recoveryLabel = Astro.locals.user ? 'Go to dashboard' : 'Go to sign in';
---
<BaseLayout title="Page not found"><main class="error-page"><p class="eyebrow">Page not found</p><h1>We could not find that page</h1><p>The address may be outdated, or you may not have access to the requested record.</p><div><a href={recoveryHref}>{recoveryLabel}</a></div></main></BaseLayout>
<style>.error-page{min-height:70vh;display:grid;place-content:center;gap:12px;width:min(560px,calc(100% - 32px));margin:auto}.eyebrow{color:var(--color-accent-primary);font:600 11px var(--font-mono)}h1{margin:0;color:var(--text-primary);font-size:clamp(28px,5vw,46px)}p{margin:0;color:var(--text-secondary);line-height:1.6}.error-page div{display:flex;gap:16px;margin-top:12px}.error-page a{color:var(--color-accent-primary-hover);font-size:13px}</style>

---
import BaseLayout from '../ui/layouts/BaseLayout.astro';
const requestId = Astro.locals.requestContext?.requestId;
const hasSession = Boolean(Astro.locals.actor);
const returnTo = encodeURIComponent(`${Astro.url.pathname}${Astro.url.search}`);
const recoveryHref = hasSession ? '/dashboard' : `/login?returnTo=${returnTo}`;
const recoveryLabel = hasSession ? 'Back to dashboard' : 'Sign in to continue';
const sessionEnded = Astro.locals.sessionRecovery === 'SESSION_ENDED';
---
<BaseLayout title="Service unavailable"><main class="error-page"><p class="eyebrow">Request could not be completed</p><h1>Something interrupted this request</h1><p>{sessionEnded ? 'Your session ended while this request was being processed. Sign in again, then review the affected record and its history before deciding whether to retry.' : 'The request result could not be confirmed. Review the affected record and its history before deciding whether to try again. Contact support if the result remains unclear.'}</p>{requestId && <p class="reference">Reference: <code>{requestId}</code></p>}<div><a href={recoveryHref}>{recoveryLabel}</a><a href="/help">Get help</a></div></main></BaseLayout>
<style>
  .error-page { min-height: 70vh; display: grid; align-content: center; gap: var(--space-3); width: min(560px, calc(100% - 2 * var(--space-4))); margin-inline: auto; }
  .eyebrow { margin: 0; color: var(--status-danger); font-size: var(--font-size-sm); font-weight: 700; }
  h1 { margin: 0; color: var(--text-primary); font-size: clamp(1.75rem, 5vw, 2.875rem); }
  .error-page p { margin: 0; color: var(--text-secondary); line-height: var(--line-height-relaxed); }
  .reference { font-size: var(--font-size-sm); }
  .reference code { color: var(--text-primary); font-family: var(--font-mono); overflow-wrap: anywhere; }
  .error-page div { display: flex; flex-wrap: wrap; gap: var(--space-3); margin-block-start: var(--space-2); }
  .error-page a { display: inline-flex; align-items: center; min-block-size: var(--control-height); color: var(--color-accent-primary-hover); font-weight: 600; }
  .error-page a:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 3px; }
</style>

---
import { actions } from 'astro:actions';
import AppLayout from '../ui/layouts/AppLayout.astro';
import { GetAccountUseCase } from '../modules/identity/application/get-account.js';
import { identityDependencies } from '../modules/identity/application/identity-dependencies.js';
import { stateLabel } from '../shared/copy/ux-vocabulary.js';
const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
const account = await new GetAccountUseCase(identityDependencies().users).execute(actor);
const actionResult = Astro.getActionResult(actions.account.changePassword);
if (actionResult?.data?.ok) return Astro.redirect(actionResult.data.redirectTo, 303);
const changeError = actionResult?.data && !actionResult.data.ok ? actionResult.data : undefined;
const currentPasswordError = changeError?.fieldErrors?.currentPassword?.[0];
const newPasswordError = changeError?.fieldErrors?.newPassword?.[0];
---
<AppLayout title="Account · QC Operations" locale="en" direction="ltr">
  <section class="page-head">
    <div>
      <p class="eyebrow">Your account</p>
      <h1>Account</h1>
      <p class="lede">
        Your identity, password, and active session. Role and scope changes are audited and made by
        an administrator.
      </p>
    </div>
  </section>
  {
    account && (
      <>
        <section class="panel" aria-labelledby="account-info">
          <h2 id="account-info">Account information</h2>
          <dl class="summary">
            <div>
              <dt>Login identity</dt>
              <dd>{account.loginIdentity}</dd>
            </div>
            <div>
              <dt>Display name</dt>
              <dd>{account.displayName}</dd>
            </div>
            <div>
              <dt>Email</dt>
              <dd>{account.email ?? 'Not provided'}</dd>
            </div>
            <div>
              <dt>State</dt>
              <dd>{stateLabel(account.accountState)}</dd>
            </div>
          </dl>
          <p class="muted">
            Role and scope grants are visible to administrators in the member register.
          </p>
          <p class="muted">
            If your login identity, display name, or email is wrong, ask an administrator to correct it in the member register. Profile changes are controlled and audited; this page does not delete account history.
          </p>
        </section>
        <section class="panel" aria-labelledby="security">
          <h2 id="security">Password and security</h2>
          <form class="form" method="POST" action={actions.account.changePassword}>
            {changeError?.formError && <p role="alert" id="password-form-error" tabindex="-1">{changeError.formError === 'missing' ? 'This account is no longer available for password changes. Sign in again or contact an administrator.' : changeError.formError === 'denied' ? 'You no longer have permission to change this password. Contact an administrator.' : changeError.formError === 'stale' ? 'Account security details changed before this request completed. Reload the page before trying again.' : changeError.formError === 'provider' ? 'The password service is temporarily unavailable. Your request was not confirmed. Try again later.' : 'We could not confirm whether the password change completed. Do not submit it again yet. Contact an administrator for help.'}</p>}
            <div class="field">
              <label for="currentPassword">Current password</label>
              <div class="password-field">
                <input
                  id="currentPassword"
                  name="currentPassword"
                  type="password"
                  autocomplete="current-password"
                  required
                  aria-invalid={currentPasswordError ? 'true' : undefined}
                  aria-describedby={currentPasswordError ? 'currentPassword-error' : 'password-change-hint'}
                />
                <button
                  type="button"
                  data-password-toggle
                  aria-pressed="false"
                  aria-controls="currentPassword"
                  aria-label="Show password"
                >
                  Show
                </button>
              </div>
              {currentPasswordError && <p class="field-error" id="currentPassword-error" tabindex="-1" aria-live="assertive">The current password is incorrect. Check it and try again.</p>}
            </div>
            <div class="field">
              <label for="newPassword">New password</label>
              <div class="password-field">
                <input
                  id="newPassword"
                  name="newPassword"
                  type="password"
                  autocomplete="new-password"
                  required
                  aria-invalid={newPasswordError ? 'true' : undefined}
                  aria-describedby={newPasswordError ? 'newPassword-error' : undefined}
                />
                <button
                  type="button"
                  data-password-toggle-new
                  aria-pressed="false"
                  aria-controls="newPassword"
                  aria-label="Show password"
                >
                  Show
                </button>
              </div>
              {newPasswordError && <p class="field-error" id="newPassword-error">Enter a new password.</p>}
            </div>
            <p class="hint" id="password-change-hint">Changing your password ends all active sessions, including this one. You will need to sign in again.</p>
            <div class="actions">
              <button type="submit" data-submit>Change password</button>
            </div>
            <p role="status" aria-live="polite" data-result tabindex="-1" class="status"></p>
          </form>
        </section>
        <section class="panel" aria-labelledby="session">
          <h2 id="session">Session</h2>
          <p class="muted">
            Signing out ends this browser session. Sessions revoked by an administrator end
            immediately on their next request.
          </p>
          <form method="POST" action={actions.logout}>
            <button type="submit" class="secondary">Sign out</button>
          </form>
        </section>
      </>
    )
  }
</AppLayout>
<script>
  const wire = (selector: string, inputId: string) => {
    const toggle = document.querySelector<HTMLButtonElement>(selector);
    const input = document.getElementById(inputId) as HTMLInputElement | null;
    toggle?.addEventListener('click', () => {
      if (!input || !toggle) return;
      const show = input.type === 'password';
      input.type = show ? 'text' : 'password';
      toggle.setAttribute('aria-pressed', String(show));
      toggle.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
      toggle.textContent = show ? 'Hide' : 'Show';
    });
  };
  wire('[data-password-toggle]', 'currentPassword');
  wire('[data-password-toggle-new]', 'newPassword');
  document.querySelector<HTMLElement>('#password-form-error, .field-error')?.focus();
  const form = document.querySelector<HTMLFormElement>('form[action*="changePassword"]');
  form?.addEventListener('submit', (event: Event) => {
    if (form.getAttribute('aria-busy') === 'true') {
      event.preventDefault();
      return;
    }
    const submit = form.querySelector<HTMLButtonElement>('[data-submit]');
    const output = form.querySelector<HTMLElement>('[data-result]');
    form.setAttribute('aria-busy', 'true');
    if (submit) submit.disabled = true;
    if (output) output.textContent = 'Changing password…';
  });
</script>
<style>
  .page-head{margin-bottom:var(--space-6)}h1{margin:.25rem 0 .4rem}.eyebrow{margin:0;color:var(--text-muted);font-size:.75rem;letter-spacing:.12em;font-weight:700}.lede,.muted,.hint{color:var(--text-muted);font-size:.85rem}.panel{padding:var(--space-5);margin-bottom:var(--space-5);background:var(--surface-panel);border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg);max-width:640px}.panel h2{margin-top:0;font-size:1rem}.summary{display:grid;grid-template-columns:minmax(140px,auto) minmax(0,1fr);gap:.5rem 1rem;margin:0 0 var(--space-3)}.summary div{display:contents}.summary dt{color:var(--text-muted);font-size:.8rem}.summary dd{margin:0;font-size:.85rem}.form{display:grid;gap:var(--space-4)}.field{display:grid;gap:.35rem}label{font-size:.85rem;font-weight:600}.password-field{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:.5rem;align-items:center}input{min-height:44px;padding-inline:.75rem;background:var(--surface-raised);border:1px solid var(--border-default);border-radius:var(--radius-sm);color:var(--text-primary);font:inherit;min-width:0}button{min-height:44px;padding-inline:1rem;border:1px solid var(--color-accent-primary);border-radius:var(--radius-sm);background:var(--color-accent-primary);color:var(--color-text-inverse);font-weight:700}button.secondary{background:var(--surface-raised);border-color:var(--border-default);color:var(--text-primary)}.actions{display:flex;gap:var(--space-3);flex-wrap:wrap}.status{margin:0;font-size:.85rem;color:var(--text-muted)}.field-error,#password-form-error{margin:0;color:var(--status-danger)}input[aria-invalid="true"]{border-color:var(--status-danger)}@media(max-width:520px){.summary{grid-template-columns:1fr}.summary dt{margin-top:var(--space-2)}}
</style>

---
import AppLayout from '../../ui/layouts/AppLayout.astro';
import { canAccessAdminRoute, hasAdminGrant } from '../../shared/authorization/admin-workspace.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
const canCreateUser = canAccessAdminRoute(actor, 'usersNew');
const canAudit = actor ? hasAdminGrant(actor, 'PERM-ADM-AUDIT-VIEW') : false;
---

<AppLayout title="Administration · QC Operations" locale="en" direction="ltr">
  <section class="page-head">
    <div>
      <p class="eyebrow">Administration</p>
      <h1>Administration</h1>
      <p class="lede">
        Member, role, permission, and scope administration. Every change requires explicit
        permission, scope, version, and audit — the Admin role alone is never authority.
      </p>
    </div>
  </section>
  <div class="grid">
        <section class="panel">
          <p class="eyebrow">UI-ADM-USR-001</p>
          <h2>Users</h2>
          <p>Create, inspect, update, disable, and reset member accounts within your authority.</p>
          <div class="links">
            <a class="button" href="/admin/users">Open users</a>
            {canCreateUser && <a class="button secondary" href="/admin/users/new">Create user</a>}
          </div>
        </section>
        <section class="panel">
          <p class="eyebrow">UI-ADM-ROLE-001</p>
          <h2>Roles</h2>
          <p>Inspect roles and manage their canonical permission grants with version checks.</p>
          <div class="links"><a class="button" href="/admin/roles">Open roles</a></div>
        </section>
        <section class="panel">
          <p class="eyebrow">UI-ADM-PERM-001</p>
          <h2>Permissions</h2>
          <p>Read-only catalog of canonical permissions. Grants change only through roles.</p>
          <div class="links"><a class="button" href="/admin/permissions">Open permissions</a></div>
        </section>
        <section class="panel">
          <p class="eyebrow">UI-ADM-SCOPE-001</p>
          <h2>Scopes</h2>
          <p>
            Manage member authorization scopes. Self-grants are always blocked and audited.
          </p>
          <div class="links"><a class="button" href="/admin/scopes">Open scopes</a></div>
        </section>
        {canAudit && (
          <section class="panel">
            <p class="eyebrow">AUDIT</p>
            <h2>Audit history</h2>
            <p>Administration changes are recorded as audit events and survive record changes.</p>
            <div class="links">
              <a class="button secondary" href="/audit">
                Open audit
              </a>
            </div>
          </section>
        )}
  </div>
</AppLayout>
<style>
  .page-head {
    margin-bottom: var(--space-6);
  }
  h1 {
    margin: 0.25rem 0;
  }
  .eyebrow {
    margin: 0;
    color: var(--text-muted);
    font-size: var(--font-size-xs);
    letter-spacing: 0.12em;
    font-weight: 700;
  }
  .lede,
  .empty {
    color: var(--text-muted);
    font-size: 0.86rem;
  }
  .grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 17.5rem), 1fr));
    gap: var(--space-5);
  }
  .panel,
  .denied {
    padding: var(--space-5);
    background: var(--surface-panel);
    border: 1px solid var(--color-border-subtle);
    border-radius: var(--radius-lg);
  }
  .denied {
    border-inline-start: 3px solid var(--status-warning);
  }
  .denied p {
    color: var(--text-muted);
    font-size: 0.84rem;
  }
  h2 {
    margin: 0.25rem 0 0;
    font-size: 1rem;
  }
  .panel p {
    color: var(--text-muted);
    font-size: 0.84rem;
  }
  .links {
    display: flex;
    gap: var(--space-3);
    flex-wrap: wrap;
    margin-top: var(--space-4);
  }
  .button {
    border: 1px solid var(--color-accent-primary);
    background: var(--color-accent-primary);
    color: #fff;
    padding: 0.65rem 1rem;
    border-radius: var(--radius-md);
    text-decoration: none;
    font-weight: 700;
  }
  .button.secondary {
    background: transparent;
    color: var(--color-accent-primary-hover);
  }
</style>

---
import AppLayout from '../../../ui/layouts/AppLayout.astro';
import { administrationDependencies } from '../../../modules/administration/application/dependencies.js';
import { AppError } from '../../../shared/errors/app-error.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);

type PermissionList = Awaited<ReturnType<ReturnType<typeof administrationDependencies>['listPermissions']['execute']>>;
let permissions: PermissionList | undefined;
let denied = false;
try {
  permissions = await administrationDependencies().listPermissions.execute({ actor });
} catch (error) {
  denied = error instanceof AppError && error.category === 'AUTHORIZATION';
  if (!denied) throw error;
}
---

<AppLayout title="Permissions · Administration" locale="en" direction="ltr">
  <section class="page-head">
    <div>
      <p class="eyebrow">Permissions</p>
      <h1>Permissions</h1>
      <p class="lede">
        Read-only catalog of active canonical permissions. Grants change only through roles —
        there is no direct permission mutation here.
      </p>
    </div>
    <a href="/admin">Back to administration</a>
  </section>
  {
    denied || !permissions ? (
      <section class="denied" role="alert">
        <h2>Permission catalog is not available</h2>
        <p>
          Reading permissions requires an explicit permission-view grant. Role membership alone
          does not authorize this view.
        </p>
      </section>
    ) : permissions.length ? (
      <div class="table-wrap">
        <table>
          <caption>Active canonical permissions</caption>
          <thead>
            <tr>
              <th scope="col">Code</th>
              <th scope="col">Domain</th>
              <th scope="col">Action</th>
            </tr>
          </thead>
          <tbody>
            {permissions.map((permission) => (
              <tr>
                <th scope="row">
                  <code>{permission.code}</code>
                </th>
                <td>{permission.domain}</td>
                <td>{permission.action}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    ) : (
      <p class="empty">No active permissions are cataloged.</p>
    )
  }
</AppLayout>
<style>
  .page-head {
    display: flex;
    justify-content: space-between;
    gap: var(--space-5);
    align-items: start;
    margin-bottom: var(--space-6);
  }
  h1 {
    margin: 0.25rem 0;
  }
  .eyebrow {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    font-weight: 700;
  }
  .lede,
  .empty {
    color: var(--text-muted);
    font-size: 0.86rem;
  }
  .denied {
    padding: var(--space-5);
    background: var(--surface-panel);
    border: 1px solid var(--color-border-subtle);
    border-inline-start: 3px solid var(--status-warning);
    border-radius: var(--radius-lg);
  }
  .denied p {
    color: var(--text-muted);
    font-size: 0.84rem;
  }
  .table-wrap {
    overflow-x: auto;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    background: var(--surface-panel);
  }
  caption {
    text-align: start;
    padding: var(--space-4);
    color: var(--text-muted);
  }
  th,
  td {
    padding: 0.75rem;
    text-align: start;
    border-top: 1px solid var(--color-border-subtle);
  }
  th {
    font-weight: 700;
  }
  code {
    font-size: 0.78rem;
  }
  a {
    color: var(--color-accent-primary-hover);
  }
  @media (max-width: 600px) {
    .page-head {
      display: grid;
    }
  }
</style>

---
import AppLayout from '../../../ui/layouts/AppLayout.astro';
import { administrationDependencies } from '../../../modules/administration/application/dependencies.js';
import { canAccessAdminRoute } from '../../../shared/authorization/admin-workspace.js';
import { AppError } from '../../../shared/errors/app-error.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
const roleId = Astro.params.roleId ?? '';

type RoleView = Awaited<ReturnType<ReturnType<typeof administrationDependencies>['getRole']['execute']>>;
type GrantList = Awaited<ReturnType<ReturnType<typeof administrationDependencies>['listRolePermissions']['execute']>>;
type PermissionList = Awaited<ReturnType<ReturnType<typeof administrationDependencies>['listPermissions']['execute']>>;

let role: RoleView | undefined;
let grants: GrantList | undefined;
let catalog: PermissionList | undefined;
let catalogRestricted = false;
let denied = false;
try {
  role = await administrationDependencies().getRole.execute({ actor, roleId });
} catch (error) {
  if (error instanceof AppError && error.code === 'RESOURCE_NOT_FOUND') {
    return Astro.redirect('/404');
  }
  denied = error instanceof AppError && error.category === 'AUTHORIZATION';
  if (!denied) throw error;
}
if (role) {
  try {
    grants = await administrationDependencies().listRolePermissions.execute({ actor, roleId });
  } catch (error) {
    catalogRestricted = error instanceof AppError && error.category === 'AUTHORIZATION';
    if (!catalogRestricted) throw error;
  }
  try {
    catalog = await administrationDependencies().listPermissions.execute({ actor });
  } catch (error) {
    catalogRestricted = catalogRestricted || (error instanceof AppError && error.category === 'AUTHORIZATION');
    if (!(error instanceof AppError && error.category === 'AUTHORIZATION')) throw error;
  }
}

const granted = new Set((grants ?? []).map(String));
const canAssign = canAccessAdminRoute(actor, 'roleDetail') && (role?.active ?? false);
const version = role?.version.toString() ?? '0';
---

<AppLayout title="Role detail · Administration" locale="en" direction="ltr">
  <section class="page-head">
    <div>
      <p class="eyebrow">Role</p>
      <h1>{role?.name ?? 'Role detail'}</h1>
      <p class="lede">
        {role ? `${role.code} · ${role.active ? 'Active' : 'Inactive'} · Version ${version}` : ''}
      </p>
    </div>
    <a href="/admin/roles">Back to roles</a>
  </section>
  {
    denied || !role ? (
      <section class="denied" role="alert">
        <h2>Role detail is not available</h2>
        <p>
          Reading this role requires an explicit role-administration permission grant. Role
          membership alone does not authorize this view.
        </p>
      </section>
    ) : (
      <div class="grid">
        <section class="panel">
          <p class="eyebrow">ROLE</p>
          <h2>Configuration</h2>
          <dl>
            <div>
              <dt>Code</dt>
              <dd>{role.code}</dd>
            </div>
            <div>
              <dt>System role</dt>
              <dd>{role.isSystemRole ? 'YES' : 'NO'}</dd>
            </div>
            <div>
              <dt>Description</dt>
              <dd>{role.description ?? '—'}</dd>
            </div>
          </dl>
          {!role.active && (
            <p class="note">
              This role is inactive. Permission grants cannot change until it is reactivated
              through the approved workflow.
            </p>
          )}
        </section>
        <section class="panel">
          <p class="eyebrow">PERMISSION GRANTS</p>
          <h2>Canonical grants</h2>
          {catalogRestricted || !catalog ? (
            <p class="note">
              The permission catalog requires the explicit permission-view grant. Your current
              grants do not include it.
            </p>
          ) : canAssign ? (
            <form class="form" data-admin-role-permissions data-role={role.id} data-version={version}>
              <p class="note">
                Replacing grants is a high-risk, audited mutation. The current version is
                required; stale versions are rejected without overwriting.
              </p>
              <div class="grants">
                {catalog.map((permission) => (
                  <label class="check">
                    <input
                      type="checkbox"
                      name="permission"
                      value={permission.code}
                      checked={granted.has(permission.code)}
                    />
                    <span>
                      <strong>{permission.code}</strong>
                      <small>
                        {permission.domain} · {permission.action} · {permission.riskLevel}
                      </small>
                    </span>
                  </label>
                ))}
              </div>
              <div class="actions">
                <button type="submit">Replace grants</button>
              </div>
              <p role="status" data-result tabindex="-1" />
            </form>
          ) : (
            <div>
              {grants?.length ? (
                <ul class="grants-read">
                  {grants.map((code) => (
                    <li>
                      <code>{code}</code>
                    </li>
                  ))}
                </ul>
              ) : (
                <p class="note">No active grants on this role.</p>
              )}
              <p class="note">
                Changing grants requires the explicit permission-assignment grant on an active
                role.
              </p>
            </div>
          )}
        </section>
      </div>
    )
  }
</AppLayout>
<script>
  import { actions } from 'astro:actions';
  import { classifyActionResult } from '../../../ui/forms/mutation-interaction.js';
  const form = document.querySelector<HTMLFormElement>('[data-role-grants]');
  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (!form || form.getAttribute('aria-busy') === 'true') return;
    const submit = form.querySelector<HTMLButtonElement>('[data-submit]');
    let output = form.querySelector<HTMLElement>('[data-result]');
    if (!output) { output = document.createElement('p'); output.setAttribute('data-result',''); output.setAttribute('role','status'); output.setAttribute('tabindex','-1'); form.appendChild(output); }
    form.setAttribute('aria-busy', 'true');
    if (submit) submit.disabled = true;
    output.textContent = 'Replacing grants…';
    try {
      const permissionCodes = [...form.querySelectorAll<HTMLInputElement>('input[name="permission"]')].filter((input) => input.checked).map((input) => String(input.value));
      const result = await actions.admin.updateRolePermissions({ roleId: form.dataset.role ?? '', permissionCodes, expectedVersion: BigInt(form.dataset.version ?? '0') });
      const outcome = classifyActionResult(result as unknown as { data?: { id?: string }; error?: unknown });
      // updateRolePermissions returns grants (no id): SUCCESS means reload.
      if (!result.error) { location.reload(); return; }
      const copy: Record<string,string> = {
        VALIDATION_ERROR: 'Grants were not replaced. Review the selected permissions and try again.',
        CONFLICT_STALE: 'The role changed while you were editing it. Refresh the role detail and try again if still permitted.',
        AUTHORIZATION_CHANGED: 'Your authorization changed. Replacing grants needs the explicit role-administration permission.',
        DEPENDENCY_UNAVAILABLE: 'The role or permission catalog is no longer available. Refresh before trying again.',
        UNKNOWN_SAFE_ERROR: 'Unable to replace grants. Refresh and try again if authorized.',
      };
      output.textContent = copy[outcome.state] ?? copy.UNKNOWN_SAFE_ERROR;
      output.focus?.();
    } catch {
      output.textContent = 'The service did not confirm the result. Refresh the role and its history before deciding whether to try again.';
      output.focus?.();
    } finally { form.removeAttribute('aria-busy'); if (submit) submit.disabled = false; }
  });
</script>
