            <div class="scope-row">
              <label class="check">
                <input type="checkbox" name="scopeKind" value={kind} />
                {uxVocabulary.scopeKindLabels[kind] ?? kind}
              </label>
              {scopeRequiresValue(kind) ? (
                <input
                  name={`scopeValue-${kind}`}
                  maxlength="200"
                  placeholder={`${uxVocabulary.scopeKindLabels[kind] ?? kind} value`}
                  aria-label={`${uxVocabulary.scopeKindLabels[kind] ?? kind} scope value`}
                />
