<AppLayout title="AI Advisory · QC Operations" locale="en" direction="ltr">
  <section class="page-head"><div><p class="eyebrow">AI advisory</p><h1>AI Advisory</h1><p class="lede">Suggestions and analysis only — not an approval authority.</p></div></section>
  {pageAccess === 'ALLOWED' && canUse ? (
    <>
      <section class="notice" role="note"><strong>Advisory boundary</strong><span>{copy.boundaries.aiNotAuthority} Response actions are limited to copying text or editing it locally.</span></section>
      <section class="notice" role="note" aria-label="Human review path"><strong>Human review path</strong><span>AI output is not entered into a QC record. Verify every statement against the cited controlled source, then take uncertainty, missing sources, or suspected incorrect citations to your Supervisor or QCM (Manager) through the normal authorized review workflow.</span></section>
      <section class="notice privacy-notice" role="note" aria-label="AI data use">
        <strong>About your request</strong>
        <dl>
          <dt>Provider selection defaults</dt><dd>{aiAvailability.primaryProvider} primary / {aiAvailability.fallbackProvider} fallback. These are routing preferences only.</dd>
          <dt>Credential presence</dt><dd>{aiAvailability.credentialProviders || 'No complete provider credentials/model settings detected'}{aiAvailability.missingCredentials.length > 0 && `; missing: ${aiAvailability.missingCredentials.join(', ')}`}</dd>
          <dt>Owner approval and policy</dt><dd>{aiAvailability.approvalFlagGranted ? 'Technical approval flag is true' : 'Owner approval is not granted'}; {aiAvailability.policyValid ? 'complete valid policy is configured' : aiAvailability.policyConfigured ? 'policy source is invalid or incomplete' : 'policy source is missing'}. This flag is not itself owner approval.</dd>
          <dt>Provider availability</dt><dd>{configuredProviders ? 'Not checked until all policy gates and per-request consent pass.' : 'No policy-authorized provider is configured; no provider request can be sent.'}</dd>
          <dt>Per-request consent</dt><dd>Required for every request after the processing policy is approved; changing the question or excerpt clears consent.</dd>
          <dt>Database schema</dt><dd>Checked separately on <a href="/system/health">System health</a>; schema readiness does not enable AI processing.</dd>
        </dl>
        {aiAvailability.invalidConfiguration ? (
          <span>AI configuration is invalid ({aiAvailability.invalidFields.join(', ')}). External sending is disabled. Ask the service owner to correct the named settings; no values or credentials are shown here.</span>
        ) : !aiAvailability.approvalFlagGranted ? (
          <span>External processing is disabled pending the authorized owner's processing decision. Provider defaults and credentials do not grant approval. Your question and excerpt will not be sent.</span>
        ) : !aiAvailability.policyValid ? (
          <span>The approval flag is present, but a complete valid policy artifact is missing. External sending is disabled until the owner approves provider, data classes, processing location, retention, deletion terms, and consent terms.</span>
        ) : aiAvailability.missingCredentials.length > 0 && !configuredProviders ? (
          <span>Provider credentials or model configuration are missing for this policy: {aiAvailability.missingCredentials.join(', ')}. Provider selection defaults do not count as credentials. No request content will be sent. Contact the service owner to configure approved settings.</span>
        ) : configuredProviders && processingPolicy ? (
          <>
            <span>Provider: {configuredProviders}. Processing location: {processingPolicy.processingLocation}. Retention limit in the approved policy: {processingPolicy.retentionDays} days. Deletion terms: {processingPolicy.deletionTerms}. Policy: {processingPolicy.policyId} v{processingPolicy.version} ({processingPolicy.sourceReference}). Provider training is prohibited by the configured policy.</span>
            {aiAvailability.missingCredentials.length > 0 && <span>Optional policy-listed provider settings are incomplete: {aiAvailability.missingCredentials.join(', ')}. Configured provider(s) available: {configuredProviders}.</span>}
            <span>Permitted content classes: {processingPolicy.permittedDataClasses.join(', ')}. Never submit personal data, credentials, confidential QC information, actual controlled QC records, or content you are not authorized to share. The system checks common sensitive patterns but cannot classify every excerpt.</span>
          </>
        ) : (
          <span>No policy-authorized provider is configured. External sending is disabled; the request will not be sent.</span>
        )}
      </section>
      <section class="panel">
        <h2>Request advisory</h2>
        <form class="form" method="post" data-advisory-request data-can-send-externally={canSendExternally ? 'true' : 'false'}>
          <label>Output type
            <select name="mode">
              {canSummarize && <option value="SUMMARIZE">Summarize</option>}
              {canSuggest && <option value="SUGGEST">Suggest questions</option>}
              {canDraft && <option value="DRAFT">Draft text</option>}
            </select>
          </label>
          <label>Question for analysis<textarea name="question" required maxlength="4000" placeholder="What should the advisory review?"></textarea></label>
          <fieldset class="context"><legend>Optional context (minimized)</legend>
            <p class="muted">Only text you enter here is submitted after consent. Do not enter actual controlled QC records. Source identity/citation is user supplied and not authenticated here. Missing or unverified sources make the advisory abstain.</p>
            <label>Source label<input name="contextLabel" maxlength="120" placeholder="e.g. synthetic process summary" /></label>
            <label>Source identity<input name="sourceId" maxlength="200" placeholder="e.g. WI-001 v3" /></label>
            <label>Source type<input name="sourceType" maxlength="120" placeholder="e.g. CONTROLLED_DOCUMENT" /></label>
            <label>Citation<input name="citation" maxlength="500" placeholder="e.g. WI-001 §4" /></label>
            <label>Excerpt<textarea name="contextContent" maxlength="4000"></textarea></label>
          </fieldset>
          {configuredProviders && processingPolicy && (
            <>
              <label>Content class in approved policy
                <select name="dataClass" required>
                  <option value="">Select content class</option>
                  {processingPolicy.permittedDataClasses.includes('PUBLIC') && <option value="PUBLIC">Public</option>}
                  {processingPolicy.permittedDataClasses.includes('SYNTHETIC') && <option value="SYNTHETIC">Synthetic</option>}
                  {processingPolicy.permittedDataClasses.includes('AUTHORIZED_NONCONFIDENTIAL_EXCERPT') && <option value="AUTHORIZED_NONCONFIDENTIAL_EXCERPT">Authorized non-confidential excerpt</option>}
                </select>
              </label>
              <label class="consent"><input type="checkbox" name="consentToExternalProcessing" value="true" required /> I consent (version {processingPolicy.consentVersion}) to send this question and any excerpt to {configuredProviders} under policy {processingPolicy.policyId} v{processingPolicy.version}, processed in {processingPolicy.processingLocation} and retained for up to {processingPolicy.retentionDays} days.</label>
            </>
          )}
          <div class="actions"><button type="submit" data-request-button disabled>Request advisory</button></div>
          {!canSendExternally && <p class="muted">Requests are unavailable until configuration and owner-approved policy are complete. Per-request consent is still required after that.</p>}
          <p role="status" data-result aria-live="polite" aria-atomic="true"></p>
        </form>
      </section>
      <section class="panel response-panel" data-response-panel hidden>
        <h2>AI response</h2>
        <p class="advisory-label" data-advisory-label>AI-generated advisory content — suggestions and analysis only, not an approval authority.</p>
        <p class="status" data-status role="status" aria-live="polite" aria-atomic="true"></p>
        <div class="advisory-text" data-advisory-text></div>
        <p class="muted" data-source-context hidden></p>
        <p class="muted" data-source-references hidden></p>
        <p class="muted" data-review-guidance hidden></p>
        <p class="muted" data-provenance hidden></p>
        <label class="correction-label">Correction or concern (kept in this page only)<textarea data-correction maxlength="4000" placeholder="Describe what is incorrect or missing. Do not include personal data or credentials."></textarea></label>
        <button type="button" data-prepare-correction disabled>Prepare correction for human review</button>
        <div class="actions">
          <button type="button" data-copy disabled>Copy</button>
          <button type="button" data-edit-locally disabled>Edit locally</button>
        </div>
        <p class="muted" data-response-feedback role="status" aria-live="polite" aria-atomic="true"></p>
        <p class="muted">No controlled action can be triggered from an AI response. Any official decision must go through the normal authorized workflow.</p>
      </section>
    </>
  ) : (
    <p class="empty">You are not authorized to use AI advisory.</p>
  )}
</AppLayout>
{/* Page enhancement script. It is intentionally a single top-level hoisted
    script (never nested in a conditional expression): Astro only bundles and
    externalises top-level scripts, and the production CSP forbids inline
    script. Every element below is optional, so the script is inert for an
    account without the advisory permission. */}
<script>
  import { actions } from 'astro:actions';
  const form = document.querySelector<HTMLFormElement>('[data-advisory-request]');
  const panel = document.querySelector<HTMLElement>('[data-response-panel]');
  const statusEl = document.querySelector<HTMLElement>('[data-status]');
  const responseFeedbackEl = document.querySelector<HTMLElement>('[data-response-feedback]');
  const textEl = document.querySelector<HTMLElement>('[data-advisory-text]');
  const labelEl = document.querySelector<HTMLElement>('[data-advisory-label]');
  const resultEl = document.querySelector<HTMLElement>('[data-result]');
  const requestButton = form?.querySelector<HTMLButtonElement>('[data-request-button]');
  const copyButton = document.querySelector<HTMLButtonElement>('[data-copy]');
  const editLocallyButton = document.querySelector<HTMLButtonElement>('[data-edit-locally]');
  const sourceReferencesEl = document.querySelector<HTMLElement>('[data-source-references]');
  const sourceContextEl = document.querySelector<HTMLElement>('[data-source-context]');
  const reviewGuidanceEl = document.querySelector<HTMLElement>('[data-review-guidance]');
  const provenanceEl = document.querySelector<HTMLElement>('[data-provenance]');
  const correctionEl = document.querySelector<HTMLTextAreaElement>('[data-correction]');
  const correctionButton = document.querySelector<HTMLButtonElement>('[data-prepare-correction]');
  const consentCheckbox = form?.querySelector<HTMLInputElement>('input[name="consentToExternalProcessing"]');
  const externalRequestAllowed = form?.dataset.canSendExternally === 'true';
  let advisoryText = '';
  let requestOutcomeUnknown = false;
  const resetButtons = () => {
    if (copyButton) copyButton.disabled = true;
    if (editLocallyButton) editLocallyButton.disabled = true;
  };
  if (requestButton) requestButton.disabled = !externalRequestAllowed;
  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (!form || !resultEl || !externalRequestAllowed || requestButton?.disabled) return;
    requestButton.disabled = true;
    form.setAttribute('aria-busy', 'true');
    form.dataset.submitting = 'true';
    resultEl.textContent = 'Requesting advisory…';
    resetButtons();
    advisoryText = '';
    const data = new FormData(form);
    const contextLabel = String(data.get('contextLabel') || '').trim();
    const contextContent = String(data.get('contextContent') || '').trim();
    const selectedDataClass = String(data.get('dataClass') || '');
    const slowRequestNotice = window.setTimeout(() => {
      resultEl.textContent = 'Still waiting for the advisory service. Keep this page open; another request is blocked until this one returns.';
    }, 10_000);
    try {
      const response = await actions.aiAdvisory.requestAdvisory({
        mode: String(data.get('mode')) as 'SUMMARIZE' | 'SUGGEST' | 'DRAFT',
        question: String(data.get('question') || ''),
        context:
          contextLabel && contextContent
            ? [{
                label: contextLabel,
                content: contextContent,
                ...(String(data.get('sourceId') || '').trim() ? { sourceId: String(data.get('sourceId')).trim() } : {}),
                ...(String(data.get('sourceType') || '').trim() ? { sourceType: String(data.get('sourceType')).trim() } : {}),
                ...(String(data.get('citation') || '').trim() ? { citation: String(data.get('citation')).trim() } : {}),
              }]
            : [],
        consentToExternalProcessing: (form.querySelector<HTMLInputElement>('input[name="consentToExternalProcessing"]')?.checked ?? false),
        ...(selectedDataClass
          ? { dataClass: selectedDataClass as 'PUBLIC' | 'SYNTHETIC' | 'AUTHORIZED_NONCONFIDENTIAL_EXCERPT' }
          : {}),
      });
      if (panel) panel.hidden = false;
      if (statusEl && textEl && labelEl) {
        if (response.error) {
          requestOutcomeUnknown = true;
          statusEl.textContent = 'The request could not be completed. The outcome is unknown; edit the request before starting another one.';
        textEl.textContent = '';
        labelEl.textContent = 'AI advisory is optional: core QC workflows are unaffected.';
        if (sourceContextEl) {
          sourceContextEl.textContent = contextLabel
            ? `Your source reference remains on this page: ${contextLabel}${String(data.get('sourceId') || '').trim() ? ` · ${String(data.get('sourceId')).trim()}` : ''}${String(data.get('citation') || '').trim() ? ` · ${String(data.get('citation')).trim()}` : ''}. The request result is unknown; do not assume it was processed.`
            : 'Your entries remain on this page. The request result is unknown; do not assume it was processed.';
          sourceContextEl.hidden = false;
        }
        if (reviewGuidanceEl) {
          reviewGuidanceEl.textContent = 'If the source is missing or uncertainty remains, take the original controlled record to your Supervisor or QCM (Manager) through the normal authorized review workflow.';
          reviewGuidanceEl.hidden = false;
        }
        if (provenanceEl) { provenanceEl.textContent = ''; provenanceEl.hidden = true; }
        resetButtons();
        } else if (response.data) {
          statusEl.textContent = response.data.message;
        advisoryText = response.data.advisory?.text ?? '';
        textEl.textContent = advisoryText;
        if (sourceContextEl) {
          const sourceLabel = String(data.get('contextLabel') || '').trim();
          const sourceIdentity = String(data.get('sourceId') || '').trim();
          const sourceCitation = String(data.get('citation') || '').trim();
          sourceContextEl.textContent = sourceLabel
            ? `User-supplied source provenance: ${sourceLabel}${sourceIdentity ? ` · ${sourceIdentity}` : ''}${sourceCitation ? ` · ${sourceCitation}` : ''}. The form does not verify source authenticity or currency.`
            : 'No source context was supplied. Verify claims against a controlled source before relying on them.';
          sourceContextEl.hidden = false;
        }
        if (sourceReferencesEl) {
          const references = response.data.advisory?.sourceReferences ?? [];
          sourceReferencesEl.textContent = references.length
            ? `Sources preserved: ${references.map((reference) => reference.citation || reference.label || reference.sourceId).join(' · ')}`
            : '';
          sourceReferencesEl.hidden = references.length === 0;
        }
        if (reviewGuidanceEl) {
          reviewGuidanceEl.textContent = response.data.status === 'REFUSED'
            ? 'Reason for abstention: the request lacked a usable controlled source, contained sensitive material, or the answer included an unsafe claim or citation. Verify the source and ask your Supervisor or QCM (Manager) to review through the normal authorized workflow.'
            : response.data.status === 'UNAVAILABLE'
              ? 'The provider timed out or was unavailable. No advisory was produced. Retry later or continue with the normal human review workflow.'
              : 'Review before use: compare the response and its source details with the controlled record. Ask your Supervisor or QCM (Manager) when uncertain.';
          reviewGuidanceEl.hidden = false;
        }
        if (provenanceEl) {
          const provenance = response.data.advisory?.provenance;
          const provider = response.data.advisory?.providerMetadata;
          provenanceEl.textContent = provenance
            ? `Generated: ${provenance.generatedAt}. Provider/model: ${provider ? `${provider.provider}/${provider.model}` : 'not supplied'}. Prompt: ${provenance.promptVersion}. Confidence: not calibrated. Boundary: advisory only; verify every claim against the controlled source.`
            : 'Provenance is unavailable; verify every claim against the controlled source.';
          provenanceEl.hidden = false;
        }
        if (correctionButton) correctionButton.disabled = !advisoryText;
        labelEl.textContent = response.data.advisoryNotice;
        if (advisoryText) {
          if (copyButton) copyButton.disabled = false;
          if (editLocallyButton) editLocallyButton.disabled = false;
        }
        }
        resultEl.textContent = '';
      } else {
        if (panel) panel.hidden = false;
        if (statusEl) statusEl.textContent = 'No advisory was returned. Your entries are still here; continue with the normal human review workflow.';
      }
    } catch {
      requestOutcomeUnknown = true;
      if (panel) panel.hidden = false;
      if (statusEl) statusEl.textContent = 'The connection ended before a result was confirmed. The outcome is unknown; edit the request before starting another one.';
      if (textEl) textEl.textContent = '';
      if (labelEl) labelEl.textContent = 'AI advisory is optional: core QC workflows are unaffected.';
      if (sourceContextEl) {
        sourceContextEl.textContent = contextLabel
          ? `Your source reference remains on this page: ${contextLabel}${String(data.get('sourceId') || '').trim() ? ` · ${String(data.get('sourceId')).trim()}` : ''}${String(data.get('citation') || '').trim() ? ` · ${String(data.get('citation')).trim()}` : ''}. The request result is unknown; do not assume it was processed.`
          : 'Your entries remain on this page. The request result is unknown; do not assume it was processed.';
        sourceContextEl.hidden = false;
      }
      if (reviewGuidanceEl) {
        reviewGuidanceEl.textContent = 'Check your connection and continue with the normal human review workflow. Retry only when you are ready to make a new advisory request.';
        reviewGuidanceEl.hidden = false;
      }
      resetButtons();
    } finally {
      window.clearTimeout(slowRequestNotice);
      form.removeAttribute('aria-busy');
      delete form.dataset.submitting;
      if (requestButton) requestButton.disabled = !externalRequestAllowed || requestOutcomeUnknown;
    }
  });
  form?.querySelectorAll<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>('input:not([name="consentToExternalProcessing"]), textarea, select[name="dataClass"]').forEach((field) => {
    const invalidateConsent = () => {
      if (consentCheckbox) consentCheckbox.checked = false;
      if (requestOutcomeUnknown) {
        requestOutcomeUnknown = false;
        if (requestButton) requestButton.disabled = !externalRequestAllowed;
      }
      if (resultEl && panel && !panel.hidden) resultEl.textContent = 'Request details changed. Consent is cleared; submit a new request only after reviewing the updated terms.';
    };
    field.addEventListener('input', invalidateConsent);
    field.addEventListener('change', invalidateConsent);
  });
  copyButton?.addEventListener('click', async () => {
    if (!advisoryText || !responseFeedbackEl) return;
    try {
      await navigator.clipboard.writeText(advisoryText);
      responseFeedbackEl.textContent = 'Advisory copied.';
    } catch {
      const fallback = document.createElement('textarea');
      let copied = false;
      try {
        fallback.value = advisoryText;
        fallback.setAttribute('readonly', '');
        fallback.style.position = 'fixed';
        fallback.style.opacity = '0';
        document.body.append(fallback);
        fallback.select();
        copied = document.execCommand('copy');
      } catch {
        copied = false;
      } finally {
        fallback.remove();
      }
      responseFeedbackEl.textContent = copied
        ? 'Advisory copied.'
        : 'Copy was not available. Select the advisory text below and copy it manually.';
    }
  });
  editLocallyButton?.addEventListener('click', () => {
    const questionField = form?.querySelector<HTMLTextAreaElement>('textarea[name="question"]');
    if (!questionField || !advisoryText || !responseFeedbackEl) return;
    questionField.value = advisoryText;
    if (consentCheckbox) consentCheckbox.checked = false;
    questionField.focus();
    responseFeedbackEl.textContent = 'Advisory text placed in Question for local editing only. Review it against a controlled source before using it.';
  });
  correctionButton?.addEventListener('click', () => {
    const questionField = form?.querySelector<HTMLTextAreaElement>('textarea[name="question"]');
    if (!questionField || !advisoryText || !correctionEl?.value.trim()) return;
    questionField.value = `Human correction for review (not an approved QC decision):\n${correctionEl.value.trim()}\n\nOriginal AI advisory for comparison:\n${advisoryText}`;
    if (consentCheckbox) consentCheckbox.checked = false;
    questionField.focus();
    if (responseFeedbackEl) responseFeedbackEl.textContent = 'Correction prepared locally. Route it through the normal authorized human review workflow; it has not been saved or sent.';
  });
</script>
<style>
.page-head{margin-bottom:var(--space-6)}.eyebrow{margin:0;color:var(--text-muted);font-size:.7rem;letter-spacing:.12em;font-weight:700}h1{margin:.25rem 0}.lede,.muted,.empty{color:var(--text-muted)}
.notice,.panel{padding:var(--space-5);margin-bottom:var(--space-5);border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg);background:var(--surface-panel)}
.notice{display:grid;gap:.35rem;border-inline-start:3px solid var(--color-accent-primary)}
.notice span{color:var(--text-muted);font-size:.85rem}
.panel h2{margin-top:0;font-size:1rem}
.form{display:grid;gap:var(--space-4);max-width:720px}
.form label{display:grid;gap:.4rem;font-size:.85rem}
.form input,.form select,.form textarea{font:inherit;padding:.7rem;background:var(--surface-page);color:inherit;border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm)}
.form textarea{min-height:6rem}
.consent{display:flex!important;grid-template-columns:auto 1fr;align-items:start;gap:.65rem!important}
.consent input{margin-top:.15rem}
.correction-label{display:grid;gap:.4rem;color:var(--text-muted);font-size:.85rem}
fieldset.context{border:1px solid var(--color-border-subtle);border-radius:var(--radius-md);padding:var(--space-4);display:grid;gap:var(--space-3);margin:0}
fieldset.context legend{font-size:.8rem;font-weight:700;padding:0 .4rem}
.actions{display:flex;gap:var(--space-3);align-items:center;flex-wrap:wrap}
button{border:0;padding:.7rem 1rem;background:var(--color-accent-primary);color:#fff;border-radius:var(--radius-md);font-weight:700}
button:disabled{opacity:.5}
.advisory-label{font-size:.75rem;font-weight:700;letter-spacing:.06em;color:var(--status-warning);border:1px solid var(--status-warning);border-radius:var(--radius-sm);padding:.45rem .6rem;display:inline-block}
.status{color:var(--text-muted);font-size:.85rem}
.advisory-text{white-space:pre-wrap;font-size:.88rem;line-height:1.6;border:1px dashed var(--color-border-strong);border-radius:var(--radius-md);padding:var(--space-4)}
</style>

---
import AppLayout from '../../ui/layouts/AppLayout.astro';
import StatusBadge from '../../ui/components/StatusBadge.astro';
import LoadingState from '../../ui/components/feedback/LoadingState.astro';
import StaleVersionState from '../../ui/components/feedback/StaleVersionState.astro';
import JourneyContextPanel from '../../ui/components/workflow/JourneyContextPanel.astro';
import HandoffTimeline from '../../ui/components/workflow/HandoffTimeline.astro';
import { isUuid } from '../../shared/id/uuid.js';
import { approvalsReadDependencies } from '../../modules/approvals/application/dependencies.js';
const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
import { classifyReadFailure, providerUnavailableResponse } from '../../shared/errors/read-failure.js';
let approval: Awaited<ReturnType<ReturnType<typeof approvalsReadDependencies>['get']['execute']>> | undefined;
try {
  approval = await approvalsReadDependencies().get.execute({ actor, approvalId: Astro.params.approvalId ?? '' });
} catch (error) {
  if (classifyReadFailure(error) === 'UNAVAILABLE') {
    return providerUnavailableResponse('Approval details are temporarily unavailable', Astro.url.pathname + Astro.url.search);
  }
}
if (!approval) return Astro.redirect('/404');
const context = approval.subject.reviewContext;
const subjectLabel = String(context['documentNo'] ?? context['inspectionNo'] ?? context['labTestNo'] ?? context['calibrationNo'] ?? approval.approvalCase.subjectType);
const humanSubjectType: Record<string, string> = {
  DOCUMENT_VERSION: 'Controlled document version',
  INSPECTION_REPORT: 'Inspection report',
  LAB_TEST: 'Laboratory test',
  CHANGE_REQUEST: 'Change request',
};
const humanize = (key: string): string =>
  key
    .replaceAll(/([a-z])([A-Z])/g, '$1 $2')
    .replaceAll(/[_-]+/g, ' ')
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
const contextLabel = (key: string): string => humanize(key);
const contextUuid = (key: string): string | undefined => typeof context[key] === 'string' && isUuid(context[key]) ? context[key] : undefined;
const subjectHref = contextUuid('documentId') ? `/documents/${contextUuid('documentId')}` : contextUuid('inspectionId') ? `/quarantine/inspections/${contextUuid('inspectionId')}` : contextUuid('labTestId') ? `/laboratory/tests/${contextUuid('labTestId')}` : contextUuid('calibrationId') ? `/assets/calibrations/${contextUuid('calibrationId')}` : undefined;
const approvalActionable = approval.workItem.state === 'PENDING' || approval.workItem.state === 'IN_PROGRESS';
const approvalNextAction = approvalActionable ? 'Submit controlled decision' : 'No approval action is available';
const approvalNextOwner = approvalActionable ? (approval.workItem.assignedRoleRequirement ?? 'Assigned approver') : 'Owning domain';
const approvalEvents = [
  { label: 'Approval requested', detail: approval.approvalCase.requestedAt.toLocaleString('en-SA', { timeZone: 'Asia/Riyadh' }), kind: 'business' as const },
  ...(approval.workItem.assignedAt ? [{ label: 'Approval work item assigned', detail: approval.workItem.assignedAt.toLocaleString('en-SA', { timeZone: 'Asia/Riyadh' }), kind: 'approval' as const }] : []),
  ...(approval.workItem.startedAt ? [{ label: 'Review started', detail: approval.workItem.startedAt.toLocaleString('en-SA', { timeZone: 'Asia/Riyadh' }), kind: 'approval' as const }] : []),
  { label: 'Source transition', detail: 'The owning domain applies the business transition after approval verification.', kind: 'business' as const },
];
---
<AppLayout title={`Approval · ${subjectLabel}`} locale="en" direction="ltr">
  <div class="evidence-record">
  <nav class="crumb"><a href="/approvals">My Approvals</a><span>/</span><span>{subjectLabel}</span></nav>
  <section class="head workspace-header"><div><p class="eyebrow">Approval review</p><h1>{subjectLabel}</h1><p>{humanSubjectType[approval.approvalCase.subjectType] ?? 'Controlled record'} · Current version {approval.subject.version.toString()}</p></div><StatusBadge status="REVIEW" label={approval.workItem.state} /></section>
  <JourneyContextPanel ownerDomain={approval.subject.domain ?? 'Reviews & Approvals'} currentState={`${approval.approvalCase.state} · Work item ${approval.workItem.state}`} nextAction={approvalNextAction} nextActionHref={subjectHref} nextOwner={approvalNextOwner} whyUnavailable={!approvalActionable ? 'state: this approval work item is no longer actionable' : undefined} waitingOn={approvalActionable ? approvalNextOwner : 'Owning domain transition'} expectedEvent={approvalActionable ? 'Controlled decision' : 'Source-domain transition or audit trace'} controlledContext={`${humanSubjectType[approval.approvalCase.subjectType] ?? approval.approvalCase.subjectType} · version ${approval.subject.version.toString()}`} evidenceSummary={approval.subject.snapshotHash ? 'Controlled snapshot hash available' : 'Snapshot hash not available from owning domain'} auditHref={`/audit?subjectType=${encodeURIComponent(approval.approvalCase.subjectType)}&subjectId=${encodeURIComponent(approval.approvalCase.subjectId)}`} relatedLinks={subjectHref ? [{ label: subjectLabel, href: subjectHref, detail: 'Open owning-domain record' }] : [{ label: 'My approvals', href: '/approvals', detail: 'Approval queue' }]} />
