  <section class="head">
    <div>
      <p class="eyebrow">Calibrations</p>
      <h1>Calibration records</h1>
      <p>
        Historical calibration records linked to equipment. Dates are source-provided; no interval
        is inferred.
      </p>
    </div>
    {canCreate && <a class="button" href="/assets/calibrations/new">Add calibration record</a>}
  </section>
  <FilterBar clearHref={hasFilters ? '/assets/calibrations' : undefined}>
    <label for="q">Search<input id="q" name="q" value={search ?? ''} maxlength="200" /></label>
    <label for="state">State<select id="state" name="state">
        <option value="">All states</option>
        {
          states.map((value) => (
            <option value={value} selected={state === value}>
              {stateLabel(value)}
            </option>
          ))
        }
      </select></label>
    {equipmentId && <input type="hidden" name="equipmentId" value={equipmentId} />}
  </FilterBar>
  <AppliedFilters
    filters={appliedFilters}
    clearHref={hasFilters ? '/assets/calibrations' : undefined}
    note="Showing every calibration record in your authorized scope."
  />
  {
    providerUnavailable ? (
      <ProviderUnavailableState
        title="Calibration data is unavailable"
        description="The calibration read provider did not return a confirmed result, so the register is not treated as empty."
        retryHref="/assets/calibrations"
      />
    ) : records.length ? (
      <div class="table-wrap">
        <table>
          <caption>
            {records.length} authorized calibration record{records.length === 1 ? '' : 's'}
            {hasFilters ? ' matching the current filters' : ''}
          </caption>
          <thead>
            <tr>
              <th scope="col">Calibration number</th>
              <th scope="col">Equipment</th>
              <th scope="col">State</th>
              <th scope="col">Calibration date</th>
              <th scope="col">Due date</th>
              <th scope="col">Certificate</th>
            </tr>
          </thead>
          <tbody>
            {records.map((record) => (
              <tr>
                <th scope="row">
                  <a href={`/assets/calibrations/${record.id}`}>{record.calibrationNo}</a>
                </th>
                <td>
                  <a href={`/assets/equipment/${record.equipmentId}`}>{record.equipmentId}</a>
                </td>
                <td>
                  <span class="state">{stateLabel(record.state)}</span>
                </td>
                <td>{formatDate(record.calibrationDate)}</td>
                <td>{record.dueDate ? formatDate(record.dueDate) : 'Not supplied'}</td>
                <td>{record.certificateNo ?? 'Not supplied'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    ) : hasFilters ? (
      <EmptyTableState
        title="No calibration records match these filters"
        description="Nothing in your authorized scope matches the selected filters."
        clearHref="/assets/calibrations"
      />
    ) : (
      <EmptyTableState
        title="No calibration records yet"
        description="No calibration record exists in your authorized scope. Create the first draft to start the calibration history."
        actionLabel={canCreate ? 'Add calibration record' : undefined}
        actionHref={canCreate ? '/assets/calibrations/new' : undefined}
      />
    )
  }
</AppLayout>
<style>
  .head{display:flex;justify-content:space-between;gap:var(--space-5);align-items:flex-start;margin-bottom:var(--space-6)}h1{margin:.25rem 0 .4rem}.eyebrow{margin:0;color:var(--text-muted);font-size:var(--font-size-xs);letter-spacing:.12em;font-weight:700}.head p:not(.eyebrow){color:var(--text-muted);font-size:var(--font-size-sm)}.button{display:inline-flex;align-items:center;justify-content:center;min-height:var(--control-height);padding-inline:1rem;border:1px solid var(--color-accent-primary);border-radius:var(--radius-sm);background:var(--color-accent-primary);color:var(--color-text-inverse);text-decoration:none;font-weight:var(--font-weight-bold)}.table-wrap{overflow-x:auto;border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg)}table{width:100%;min-width:900px;border-collapse:collapse;background:var(--surface-panel)}caption{text-align:start;padding:var(--space-4);color:var(--text-muted);font-size:var(--font-size-xs)}th,td{padding:.85rem;border-top:1px solid var(--color-border-subtle);text-align:start;font-size:var(--font-size-sm)}th{font-weight:var(--font-weight-semibold)}a{color:var(--color-accent-primary-hover)}.state{display:inline-flex;padding:.28rem .5rem;border:1px solid var(--color-border-subtle);border-radius:999px;font-size:var(--font-size-xs);font-weight:var(--font-weight-semibold)}@media(max-width:650px){.head{display:grid}.button{width:max-content}}</style>

---
import AppLayout from '../../../ui/layouts/AppLayout.astro';
import FormErrorSummary from '../../../ui/components/FormErrorSummary.astro';
import { actions } from 'astro:actions';
import {
  detailHref,
  extractDetailId,
  field,
  optionalField,
  toFormFailure,
  type FormFailure,
} from '../../../ui/forms/mutation-post.js';
import {
  resolvePreselectedId,
  safeListHref,
} from '../../../ui/forms/entity-select.js';
import { equipmentEligibilityOptionLabel } from '../../../ui/forms/equipment-eligibility.js';
import { assetsReadDependencies } from '../../../modules/assets/application/dependencies.js';

const actor=Astro.locals.actor; if(!actor)return Astro.redirect('/login?returnTo=%2Fassets%2Fcalibrations%2Fnew'); const canCreate=actor.permissions.some((permission)=>permission.code==='PERM-CAL-CREATE');

const LIST_HREF = '/assets/calibrations';
// Safe list return context (F-09): Cancel/back preserve a benign list filter
// when the operator arrived with one; anything else falls back to the list.
const returnHref = safeListHref(Astro.url.searchParams.get('returnTo'), LIST_HREF);
const REQUIRED_FIELDS = [
  { name: 'calibrationNo', label: 'Calibration ID' },
  { name: 'equipmentId', label: 'Equipment' },
  { name: 'calibrationDate', label: 'Calibration date' },
] as const;

// Authorized selector source (F-06): equipment in the operator's authorized
// scope, loaded server-side through the application use case (which requires
// PERM-EQP-VIEW). The UUID travels only as the selected option value; the
// operator always sees the human-readable equipment number + name.
let equipmentOptions: { value: string; label: string }[] = [];
let equipmentError = false;
if (canCreate) {
  try {
    const readAssets = assetsReadDependencies();
    const equipment = await readAssets.equipment.list.execute({ actor });
    equipmentOptions = await Promise.all(equipment.map(async (item) => ({
      value: item.id,
      label: equipmentEligibilityOptionLabel(
        `${item.equipmentNo} · ${item.name}`,
        await readAssets.equipment.assessEligibility.assess(actor, item.id),
      ),
    })));
  } catch {
    // Fail closed into an error state below: the form stays submittable so
    // entries are preserved, and the server still validates the equipment
    // reference on submit. No unauthorized equipment detail is disclosed.
    equipmentError = true;
  }
}

// Contextual preselection (e.g. `?equipmentId=…` from an equipment
// workspace): honored only when still authorized, otherwise surfaced as a
// stale-selection warning that requires an explicit operator choice.
const preselected = resolvePreselectedId(
  Astro.url.searchParams.get('equipmentId'),
  equipmentOptions,
);

let values = { calibrationNo: '', equipmentId: preselected.id, calibrationDate: '', dueDate: '', provider: '', certificateNo: '', result: '' };
let failure: FormFailure | null = null;
let staleSelection = preselected.stale;

// POST baseline (F-05): without JavaScript the form performs a real POST to
// this page. The same Astro Action — with the same server-side
// reauthorization — runs via Astro.callAction. No business payload enters
// the URL: input travels in the POST body, success redirects (303) to the
// new record only.
if (Astro.request.method === 'POST' && canCreate) {
  const formData = await Astro.request.formData();
  const calibrationRaw = field(formData, 'calibrationDate');
  const dueRaw = field(formData, 'dueDate');
  values = {
    calibrationNo: field(formData, 'calibrationNo'),
    equipmentId: field(formData, 'equipmentId'),
    calibrationDate: calibrationRaw,
    dueDate: dueRaw,
    provider: field(formData, 'provider'),
    certificateNo: field(formData, 'certificateNo'),
    result: field(formData, 'result'),
  };
  // A posted id outside the authorized selector list is never trusted: the
  // server still validates the equipment reference, and the operator gets a
  // dependency recovery pointing back at the authorized list.
  staleSelection = values.equipmentId
    ? !equipmentOptions.some((option) => option.value === values.equipmentId)
    : false;
  try {
    const data = await Astro.callAction(actions.assets.createCalibration, {
      calibrationNo: values.calibrationNo,
      equipmentId: values.equipmentId,
      // Always a Date instance for the required field: blank or malformed
      // text becomes Invalid Date, which the Action input schema rejects
      // as a validation failure (highlighted on the field).
      calibrationDate: new Date(calibrationRaw),
      ...(dueRaw ? { dueDate: new Date(dueRaw) } : {}),
      provider: optionalField(formData, 'provider'),
      certificateNo: optionalField(formData, 'certificateNo'),
      result: optionalField(formData, 'result'),
    });
    const id = extractDetailId(data);
    if (id) return Astro.redirect(detailHref(LIST_HREF, id), 303);
    failure = {
      kind: 'unknown',
      summary: 'The calibration record was received but no record reference came back.',
      recovery: 'Check the calibration register before trying again to avoid a duplicate.',
      fieldErrors: {},
      firstInvalidField: null,
    };
  } catch (error) {
    failure = toFormFailure(error, {
      entity: 'Calibration record',
      requiredFields: REQUIRED_FIELDS,
      values,
      listHref: LIST_HREF,
      listLabel: 'calibrations',
    });
  }
}
const describedBy = (name: keyof typeof values): string | undefined =>
  failure?.fieldErrors[name] ? `${name}-error` : undefined;
const invalid = (name: keyof typeof values): 'true' | undefined =>
  failure?.fieldErrors[name] ? 'true' : undefined;
---
<AppLayout title="New calibration · Assets" locale="en" direction="ltr"><section class="head"><div><p class="eyebrow">New calibration</p><h1>New calibration record</h1><p>Calibration is always linked to an equipment record. Due date is entered only when supplied by an approved source.</p></div><a href={returnHref}>Back to calibrations</a></section>{canCreate?<form class="form" method="post" data-action="assets.createCalibration">{failure && <FormErrorSummary summary={failure.summary} recovery={failure.recovery} errors={Object.entries(failure.fieldErrors).map(([fieldId, message]) => ({ fieldId, message }))} listHref={returnHref} listLabel="calibrations" />}<fieldset><legend>Calibration identity</legend><div class="fields"><div><label for="calibrationNo">Calibration ID<span class="hint" id="calibrationNo-help">Use the calibration number from your approved source. Reference numbers are assigned automatically.</span><input id="calibrationNo" name="calibrationNo" required value={values.calibrationNo} aria-invalid={invalid('calibrationNo')} aria-describedby={failure?.fieldErrors.calibrationNo ? 'calibrationNo-error calibrationNo-help' : 'calibrationNo-help'} /></label>{failure?.fieldErrors.calibrationNo && <p class="field-error" id="calibrationNo-error">{failure.fieldErrors.calibrationNo}</p>}</div><div><label for="equipmentId">Equipment<span class="hint" id="equipmentId-help">Choose from equipment in your authorized scope. The technical identifier is kept automatically after selection. <a href="/assets/equipment/new">Create equipment</a></span><select id="equipmentId" name="equipmentId" required aria-invalid={invalid('equipmentId')} aria-describedby={failure?.fieldErrors.equipmentId ? 'equipmentId-error equipmentId-help' : 'equipmentId-help'}><option value="">Select equipment…</option>{equipmentOptions.map((option)=><option value={option.value} selected={option.value===values.equipmentId}>{option.label}</option>)}</select></label>{staleSelection && <p class="field-warning" role="status">The previously linked equipment is no longer available in your authorized scope. Choose the equipment explicitly.</p>}{equipmentError && <p class="field-warning" role="status">The authorized equipment list is temporarily unavailable. Your entries are kept — you can try again, or return to the list.</p>}{!equipmentError && equipmentOptions.length===0 && <p class="field-warning" role="status">No equipment is available in your authorized scope. <a href="/assets/equipment/new">Create the equipment first</a>, then return here.</p>}{failure?.fieldErrors.equipmentId && <p class="field-error" id="equipmentId-error">{failure.fieldErrors.equipmentId}</p>}</div><div><label for="calibrationDate">Calibration date<input id="calibrationDate" name="calibrationDate" type="date" required value={values.calibrationDate} aria-invalid={invalid('calibrationDate')} aria-describedby={describedBy('calibrationDate')} /></label>{failure?.fieldErrors.calibrationDate && <p class="field-error" id="calibrationDate-error">{failure.fieldErrors.calibrationDate}</p>}</div><div><label for="dueDate">Due date (source-provided)<input id="dueDate" name="dueDate" type="date" value={values.dueDate} /></label></div><div><label for="provider">Provider<input id="provider" name="provider" value={values.provider} /></label></div><div><label for="certificateNo">Certificate number<input id="certificateNo" name="certificateNo" value={values.certificateNo} /></label></div><div class="wide"><label for="result">Result / source note<textarea id="result" name="result">{values.result}</textarea></label></div></div></fieldset><div class="actions"><a class="secondary" href={returnHref}>Cancel</a><button type="submit" data-submit>Create draft</button></div><p role="status" data-result></p></form>:<section class="denied" role="alert"><h2>Creation is not available</h2><p>Your account does not have the explicit Calibration create permission.</p></section>}</AppLayout>
<script>
import{actions}from'astro:actions';
import{enhanceClassifiedForm}from'../../../ui/forms/enhance-with-classification';
import{guardUnsavedChanges}from'../../../ui/forms/unsaved-changes';
const form=document.querySelector<HTMLFormElement>('[data-action="assets.createCalibration"]');
if(form){enhanceClassifiedForm(form,{
  invoke:(payload)=>actions.assets.createCalibration(payload as Parameters<typeof actions.assets.createCalibration>[0]),
  payload:(data)=>{const calibrationRaw=String(data.get('calibrationDate'));const due=String(data.get('dueDate')||'');return{calibrationNo:String(data.get('calibrationNo')),equipmentId:String(data.get('equipmentId')),calibrationDate:new Date(`${calibrationRaw}T00:00:00.000Z`),dueDate:due?new Date(`${due}T00:00:00.000Z`):undefined,provider:String(data.get('provider')||'')||undefined,certificateNo:String(data.get('certificateNo')||'')||undefined,result:String(data.get('result')||'')||undefined};},
  progressText:'Saving…',
  detailBaseHref:'/assets/calibrations',
});guardUnsavedChanges(form);}</script>
<style>.head{display:flex;justify-content:space-between;gap:var(--space-5);align-items:flex-start;margin-bottom:var(--space-6)}h1{margin:.25rem 0 .4rem}.eyebrow{margin:0;color:var(--text-muted);font-size:.7rem;letter-spacing:.12em;font-weight:700}.head p:not(.eyebrow),.denied p{color:var(--text-muted);font-size:.85rem}.head a{color:var(--color-accent-primary-hover)}.form{max-width:900px;display:grid;gap:var(--space-5)}fieldset{padding:var(--space-5);border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg);background:var(--surface-panel)}legend{padding-inline:.5rem;font-weight:700}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-4)}label{display:grid;gap:.4rem;color:var(--text-secondary);font-size:.82rem}.hint{color:var(--text-muted);font-size:.78rem}.hint a{color:var(--color-accent-primary-hover)}.wide{grid-column:1/-1}input,select,textarea{min-height:var(--control-height);padding:.65rem;background:var(--surface-raised);border:1px solid var(--border-default);border-radius:var(--radius-sm);color:inherit;font:inherit}input[aria-invalid="true"],select[aria-invalid="true"]{border-color:var(--status-danger)}.field-error{margin:.25rem 0 0;color:var(--status-danger);font-size:.8rem}.field-warning{margin:.25rem 0 0;padding:.6rem;border-inline-start:3px solid var(--status-warning);background:var(--surface-panel);font-size:.8rem}.field-warning a{color:var(--color-accent-primary-hover)}textarea{min-height:6rem}.actions{display:flex;justify-content:flex-end;gap:var(--space-3)}button,.secondary{min-height:var(--control-height);padding:.65rem 1rem;border:1px solid var(--color-accent-primary);border-radius:var(--radius-sm);background:var(--color-accent-primary);color:#fff;font:inherit;font-weight:700}.secondary{border-color:var(--border-default);background:var(--surface-raised);color:var(--text-primary);text-decoration:none}button[disabled]{opacity:.6}.denied{padding:var(--space-6);border-inline-start:3px solid var(--status-warning);background:var(--surface-panel)}@media(max-width:650px){.head{display:grid}.fields{grid-template-columns:1fr}.wide{grid-column:auto}.actions{display:grid}}
</style>

---
import AppLayout from '../../../ui/layouts/AppLayout.astro';
import { assetsReadDependencies } from '../../../modules/assets/application/dependencies.js';
import { stateLabel } from '../../../shared/copy/ux-vocabulary.js';
import { classifyReadFailure } from '../../../shared/errors/read-failure.js';
import ProviderUnavailableState from '../../../ui/components/feedback/ProviderUnavailableState.astro';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);

const equipmentId = Astro.params.equipmentId ?? '';
const read = assetsReadDependencies();
let equipment: Awaited<ReturnType<typeof read.equipment.get.execute>> | undefined;
let equipmentUnavailable = false;
try {
  equipment = await read.equipment.get.execute({ actor, equipmentId });
} catch (error) {
  equipmentUnavailable = classifyReadFailure(error) === 'UNAVAILABLE';
}
// Missing and denied records share the same outward response to preserve existence secrecy.
if (!equipment && !equipmentUnavailable) return Astro.redirect('/404');
if (equipmentUnavailable) Astro.response.status = 503;

let calibrations: readonly import('../../../modules/assets/calibration/domain/calibration.js').CalibrationRecord[] = [];
let maintenance: readonly import('../../../modules/assets/maintenance/domain/maintenance.js').MaintenanceRecord[] = [];
let statusHistory: readonly import('../../../modules/assets/equipment/ports/repository.js').EquipmentStatusHistory[] = [];
let calibrationReadFailed = false;
let calibrationDenied = false;
let maintenanceReadFailed = false;
let maintenanceDenied = false;
let historyReadFailed = false;
let historyDenied = false;
if (equipment) {
  const [calibrationResult, maintenanceResult, historyResult] = await Promise.allSettled([
    read.calibration.list.execute({ actor, filter: { equipmentId } }),
    read.maintenance.list.execute({ actor, filter: { equipmentId } }),
    read.equipment.history.execute({ actor, equipmentId }),
  ]);
  if (calibrationResult.status === 'fulfilled') calibrations = calibrationResult.value;
  else if (classifyReadFailure(calibrationResult.reason) === 'UNAVAILABLE') calibrationReadFailed = true;
  else calibrationDenied = true;
  if (maintenanceResult.status === 'fulfilled') maintenance = maintenanceResult.value;
  else if (classifyReadFailure(maintenanceResult.reason) === 'UNAVAILABLE') maintenanceReadFailed = true;
  else maintenanceDenied = true;
  if (historyResult.status === 'fulfilled') statusHistory = historyResult.value;
  else if (classifyReadFailure(historyResult.reason) === 'UNAVAILABLE') historyReadFailed = true;
  else historyDenied = true;
}

const item = equipment;
---
<AppLayout title={`${item?.equipmentNo ?? 'Equipment'} · Assets`} locale="en" direction="ltr">
  {equipmentUnavailable ? <ProviderUnavailableState title="Equipment details are temporarily unavailable" description="The equipment source did not confirm this read. No missing-record conclusion or equipment details are shown." retryHref={Astro.url.pathname + Astro.url.search} /> : item && <>
    <div class="crumb"><a href="/assets">Assets</a><span>/</span><a href="/assets/equipment">Equipment</a><span>/</span><span>{item.equipmentNo}</span></div>
    <section class="head"><div><p class="eyebrow">Equipment</p><h1>{item.name}</h1><p>{item.equipmentNo} · Version {item.version.toString()}</p></div><span class="state">{stateLabel(item.state)}</span></section>
    <section class="facts" aria-label="Equipment identity"><div><span>Manufacturer</span><strong>{item.manufacturer ?? 'Not supplied'}</strong></div><div><span>Model</span><strong>{item.model ?? 'Not supplied'}</strong></div><div><span>Serial number</span><strong>{item.serialNo ?? 'Not supplied'}</strong></div><div><span>Location</span><strong>{item.location ?? 'Not supplied'}</strong></div><div><span>Calibration required</span><strong>{item.calibrationRequired === undefined ? 'Not specified' : item.calibrationRequired ? 'Yes' : 'No'}</strong></div><div><span>Maintenance required</span><strong>{item.maintenanceRequired === undefined ? 'Not specified' : item.maintenanceRequired ? 'Yes' : 'No'}</strong></div></section>
    <div class="grid">
      <section class="panel"><div class="panel-head"><h2>Calibration history</h2><span class="panel-links"><a href={`/assets/calibrations/new?equipmentId=${item.id}`}>Record calibration</a><a href={`/assets/calibrations?equipmentId=${item.id}`}>View all</a></span></div>{calibrationReadFailed ? <ProviderUnavailableState title="Calibration history is unavailable" description="The equipment record is shown, but its calibration history could not be confirmed." retryHref={Astro.url.pathname + Astro.url.search} /> : calibrations.length ? <table><caption>Authorized calibration records</caption><thead><tr><th scope="col">Calibration number</th><th scope="col">State</th><th scope="col">Date</th><th scope="col">Due date</th></tr></thead><tbody>{calibrations.map((record)=><tr><th scope="row"><a href={`/assets/calibrations/${record.id}`}>{record.calibrationNo}</a></th><td>{stateLabel(record.state)}</td><td>{record.calibrationDate.toLocaleDateString('en-SA',{timeZone:'Asia/Riyadh'})}</td><td>{record.dueDate?.toLocaleDateString('en-SA',{timeZone:'Asia/Riyadh'}) ?? 'Not supplied'}</td></tr>)}</tbody></table> : <p class="muted">No calibration records are available in your authorized scope.</p>}</section>
      <section class="panel"><div class="panel-head"><h2>Maintenance history</h2><span class="panel-links"><a href={`/assets/maintenance/new?equipmentId=${item.id}`}>Record maintenance</a><a href={`/assets/maintenance?equipmentId=${item.id}`}>View all</a></span></div>{maintenanceReadFailed ? <ProviderUnavailableState title="Maintenance history is unavailable" description="The equipment record is shown, but its maintenance history could not be confirmed." retryHref={Astro.url.pathname + Astro.url.search} /> : maintenance.length ? <table><caption>Authorized maintenance records</caption><thead><tr><th scope="col">Maintenance number</th><th scope="col">State</th><th scope="col">Planned</th></tr></thead><tbody>{maintenance.map((record)=><tr><th scope="row"><a href={`/assets/maintenance/${record.id}`}>{record.maintenanceNo}</a></th><td>{stateLabel(record.state)}</td><td>{record.plannedAt?.toLocaleDateString('en-SA',{timeZone:'Asia/Riyadh'}) ?? 'Not scheduled'}</td></tr>)}</tbody></table> : <p class="muted">No maintenance records are available in your authorized scope.</p>}</section>
    </div>
    <section class="panel history"><h2>Status history</h2>{historyReadFailed ? <ProviderUnavailableState title="Status history is unavailable" description="The equipment record is shown, but its status history could not be confirmed." retryHref={Astro.url.pathname + Astro.url.search} /> : statusHistory.length ? <table><caption>Append-only equipment status history</caption><thead><tr><th scope="col">Action</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Changed</th></tr></thead><tbody>{statusHistory.map((record)=><tr><th scope="row">{record.action}</th><td>{record.fromState ? stateLabel(record.fromState) : '—'}</td><td>{stateLabel(record.toState)}</td><td>{record.changedAt.toLocaleString('en-SA',{timeZone:'Asia/Riyadh'})}</td></tr>)}</tbody></table> : <p class="muted">No status history is available in your authorized scope.</p>}<p>Equipment identity changes only through the controlled workflow. Laboratory records created earlier keep the equipment context they were executed with.</p><dl><div><dt>Created by</dt><dd>{item.createdBy}</dd></div><div><dt>Updated</dt><dd>{item.updatedAt.toLocaleString('en-SA',{timeZone:'Asia/Riyadh'})}</dd></div></dl></section>
  </>}
</AppLayout>
