 type="checkbox" name="calibrationRequired" value="true" checked={values.calibrationRequired} />Calibration required</label><label class="check"><input type="checkbox" name="maintenanceRequired" value="true" checked={values.maintenanceRequired} />Maintenance required</label></div></fieldset><div class="actions"><a class="secondary" href="/assets/equipment">Cancel</a><button type="submit" data-submit>Create draft</button></div><p role="status" data-result></p></form> : <section class="denied" role="alert"><h2>Creation is not available</h2><p>Your account does not have the explicit Equipment create permission.</p></section>}</AppLayout>
