import AppLayout from '../../../ui/layouts/AppLayout.astro';
import JourneyContextPanel from '../../../ui/components/workflow/JourneyContextPanel.astro';
import HandoffTimeline from '../../../ui/components/workflow/HandoffTimeline.astro';
import { changeRequestsReadDependencies } from '../../../modules/change-requests/application/dependencies.js';
import { classifyReadFailure, providerUnavailableResponse } from '../../../shared/errors/read-failure.js';
import { isUuid } from '../../../shared/id/uuid.js';
import { stateLabel, transitionLabel, targetTypeLabel } from '../../../shared/copy/ux-vocabulary.js';
import { formatDateTime } from '../../../shared/copy/format.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
const id = Astro.params.changeRequestId ?? '';
if (!isUuid(id)) return Astro.redirect('/404');
let aggregate;
try { aggregate = await changeRequestsReadDependencies().get.execute({ actor, id }); } catch (error) { if (classifyReadFailure(error) === 'UNAVAILABLE') return providerUnavailableResponse('Change request details are temporarily unavailable', Astro.url.pathname + Astro.url.search); return Astro.redirect('/404'); }
if (!aggregate) return Astro.redirect('/404');
const { changeRequest, changes, history, applicationAttempts } = aggregate;
const canReview = actor.permissions.some((permission) => permission.active !== false && ['PERM-CHG-REVIEW', 'PERM-CHG-RETURN', 'PERM-CHG-APPROVE', 'PERM-CHG-REJECT'].includes(permission.code));
const stringify = (value: unknown) => { try { return JSON.stringify(value, (_, item) => typeof item === 'bigint' ? item.toString() : item, 2); } catch { return '[unavailable]'; } };
const nextAction = changeRequest.state === 'SUBMITTED' || changeRequest.state === 'UNDER_REVIEW' ? canReview ? 'Open review' : 'Awaiting change reviewer' : changeRequest.state === 'APPROVED' ? 'Awaiting owning-domain application' : changeRequest.state === 'APPLICATION_FAILED' ? 'Application failed — inspect the recorded attempt' : changeRequest.state === 'DRAFT' ? 'Submit change request' : undefined;
const nextOwner = changeRequest.state === 'APPROVED' || changeRequest.state === 'APPLYING' ? 'Owning domain' : changeRequest.state === 'APPLICATION_FAILED' ? 'Owning domain / change operator' : changeRequest.state === 'SUBMITTED' || changeRequest.state === 'UNDER_REVIEW' ? 'Change reviewer' : undefined;
const timelineEvents = [
  ...history.map((event) => ({ label: event.action, detail: `${transitionLabel(event.oldState, event.newState)} · ${formatDateTime(event.occurredAt)}`, kind: 'audit' as const })),
  ...applicationAttempts.map((attempt) => ({ label: `Application attempt ${attempt.attemptNo}`, detail: `${attempt.result}${attempt.errorCode ? ` · ${attempt.errorCode}` : ''}`, kind: 'evidence' as const })),
];
---
<AppLayout title={`${changeRequest.changeNo} · Change Request`} locale="en" direction="ltr">
  <section class="page-head"><div><p class="eyebrow">Change request</p><h1>{changeRequest.changeNo}</h1><p class="lede">Target: {targetTypeLabel(changeRequest.targetType)} · {changeRequest.targetId}</p></div><div class="head-actions"><span class="state">{stateLabel(changeRequest.state)}</span>{canReview && (changeRequest.state === 'SUBMITTED' || changeRequest.state === 'UNDER_REVIEW') && <a class="button" href={`/change-requests/${changeRequest.id}/review`}>Open review</a>}<a href="/change-requests">All requests</a></div></section>
  <JourneyContextPanel ownerDomain="Change Requests" currentState={stateLabel(changeRequest.state)} nextAction={nextAction} nextActionHref={changeRequest.state === 'SUBMITTED' || changeRequest.state === 'UNDER_REVIEW' ? canReview ? `/change-requests/${changeRequest.id}/review` : undefined : '/change-requests'} nextOwner={nextOwner} whyUnavailable={changeRequest.state === 'APPLICATION_FAILED' ? 'dependency: owning-domain application failed; approval evidence remains preserved' : changeRequest.state === 'APPROVED' ? 'dependency: approval does not guarantee application success' : changeRequest.state === 'APPLIED' ? 'state: change has already been applied' : undefined} waitingOn={changeRequest.state === 'SUBMITTED' || changeRequest.state === 'UNDER_REVIEW' ? 'Change reviewer' : changeRequest.state === 'APPROVED' || changeRequest.state === 'APPLYING' ? 'Owning domain application' : undefined} expectedEvent={changeRequest.state === 'APPROVED' ? 'Start/apply owning-domain change' : changeRequest.state === 'APPLYING' ? 'Application result' : changeRequest.state === 'APPLICATION_FAILED' ? 'Safe retry or correction decision' : undefined} controlledContext={`${targetTypeLabel(changeRequest.targetType)} · target version ${changeRequest.targetVersion.toString()}`} evidenceSummary={`Target snapshot hash ${changeRequest.targetSnapshotHash ?? 'not supplied'} · ${changes.length} proposed field change(s)`} auditHref={`/audit?subjectType=CHANGE_REQUEST&subjectId=${encodeURIComponent(changeRequest.id)}`} relatedLinks={[{ label: 'Change request register', href: '/change-requests', detail: 'Controlled change lifecycle' }]} />
  <div class="grid"><section class="panel"><h2>Control context</h2><dl><div><dt>Request version</dt><dd>{changeRequest.version.toString()}</dd></div><div><dt>Target version at request</dt><dd>{changeRequest.targetVersion.toString()}</dd></div><div><dt>Requested by</dt><dd>{changeRequest.requestedBy}</dd></div><div><dt>Reason</dt><dd>{changeRequest.reason}</dd></div></dl></section><section class="panel"><h2>Captured target snapshot</h2><p class="muted">This snapshot is review evidence; it is not a live target read and does not authorize a rewrite.</p><pre>{stringify(changeRequest.targetSnapshot)}</pre></section></div>
  <section class="panel"><h2>Proposed changes</h2><div class="table-wrap"><table><caption>Field-level proposed changes</caption><thead><tr><th scope="col">Field path</th><th scope="col">Current</th><th scope="col">Proposed</th><th scope="col">Data type</th></tr></thead><tbody>{changes.map((change) => <tr><th scope="row">{change.fieldPath}</th><td><code>{stringify(change.currentValue)}</code></td><td><code>{stringify(change.proposedValue)}</code></td><td>{change.dataType}</td></tr>)}</tbody></table></div></section>
  <section class="panel"><h2>Audit history</h2>{history.length ? <ol class="timeline">{history.map((event) => <li><strong>{event.action}</strong><span>{transitionLabel(event.oldState, event.newState)} · {formatDateTime(event.occurredAt)}</span><small>Request: {event.requestId}{event.reason ? ` · ${event.reason}` : ''}</small></li>)}</ol> : <p class="muted">No audit events are available for this record.</p>}</section>
  <HandoffTimeline events={timelineEvents} notificationStatus="Notification delivery is not exposed by this record view; business transition and audit history remain independent." />
  {applicationAttempts.length > 0 && <section class="panel"><h2>Application attempts</h2><p class="muted">Application is an internal controlled operation after approval. It is never triggered by this GET page.</p><ul>{applicationAttempts.map((attempt) => <li>Attempt {attempt.attemptNo}: {attempt.result}{attempt.errorCode ? ` · ${attempt.errorCode}` : ''}</li>)}</ul></section>}
</AppLayout>
