import AppLayout from '../../../ui/layouts/AppLayout.astro';
import { changeRequestsReadDependencies } from '../../../modules/change-requests/application/dependencies.js';
import { classifyReadFailure, providerUnavailableResponse } from '../../../shared/errors/read-failure.js';
import { isUuid } from '../../../shared/id/uuid.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
const id = Astro.params.changeRequestId ?? '';
if (!isUuid(id)) return Astro.redirect('/404');
let aggregate;
try { aggregate = await changeRequestsReadDependencies().get.execute({ actor, id }); } catch (error) { if (classifyReadFailure(error) === 'UNAVAILABLE') return providerUnavailableResponse('Change request details are temporarily unavailable', Astro.url.pathname + Astro.url.search); return Astro.redirect('/404'); }
if (!aggregate) return Astro.redirect('/404');
const { changeRequest, changes } = aggregate;
const permission = (code: string) => actor.permissions.some((item) => item.active !== false && item.code === code);
const canStartReview = changeRequest.state === 'SUBMITTED' && permission('PERM-CHG-REVIEW') && permission('PERM-APR-REVIEW');
const canDecide = changeRequest.state === 'UNDER_REVIEW' && permission('PERM-CHG-APPROVE') && permission('PERM-APR-APPROVE');
const canReturn = changeRequest.state === 'UNDER_REVIEW' && permission('PERM-CHG-RETURN') && permission('PERM-APR-RETURN');
const canReject = changeRequest.state === 'UNDER_REVIEW' && permission('PERM-CHG-REJECT') && permission('PERM-APR-REJECT');
const stringify = (value: unknown) => { try { return JSON.stringify(value, (_, item) => typeof item === 'bigint' ? item.toString() : item); } catch { return '[unavailable]'; } };
---
<AppLayout title={`Review ${changeRequest.changeNo} · QC Operations`} locale="en" direction="ltr">
  <section class="page-head"><div><p class="eyebrow">Change request review</p><h1>Review {changeRequest.changeNo}</h1><p class="lede">Version {changeRequest.version.toString()} · target version {changeRequest.targetVersion.toString()}</p></div><a href={`/change-requests/${changeRequest.id}`}>Back to record</a></section>
  <section class="notice" role="note"><strong>Controlled decision boundary</strong><span>Approval records a decision against this request version. It does not silently edit the target record or mean RELEASED.</span></section>
  <section class="panel"><h2>Proposed changes</h2><p>{changeRequest.reason}</p><ul>{changes.map((change) => <li><strong>{change.fieldPath}</strong>: <code>{stringify(change.currentValue)}</code> to <code>{stringify(change.proposedValue)}</code></li>)}</ul></section>
  {canStartReview && <form class="decision" data-action="start-review" data-change-request-id={changeRequest.id} data-change-request-version={changeRequest.version.toString()}><input type="hidden" name="action" value="START_REVIEW" /><button type="submit" data-submit>Start review</button><p class="action-status" data-result role="status" tabindex="-1"></p></form>}
  {(canDecide || canReturn || canReject) && <form class="decision" data-action="decision" data-change-request-id={changeRequest.id} data-change-request-version={changeRequest.version.toString()}><label for="reason">Decision reason (required for return/reject)<textarea id="reason" name="reason" rows="3"></textarea></label><div class="actions">{canReturn && <button type="submit" data-action-value="RETURN">Return</button>}{canReject && <button type="submit" data-action-value="REJECT">Reject</button>}{canDecide && <button type="submit" data-action-value="APPROVE">Approve change request</button>}</div><p class="muted">The server re-checks permission, scope, SoD, state, and version; these controls are only a presentation hint.</p><p class="action-status" data-result role="status" tabindex="-1"></p></form>}
  {!canStartReview && !canDecide && !canReturn && !canReject && <section class="denied" role="alert"><h2>Review unavailable</h2><p>Your account lacks the explicit capability and matching generic approval permission for this state, or the request is no longer actionable.</p></section>}
</AppLayout>
<script>
  import { actions } from 'astro:actions';
  const validTransitions = ['SUBMIT', 'START_REVIEW', 'RETURN', 'RESUME', 'APPROVE', 'REJECT', 'CANCEL'] as const;
  type ChangeRequestTransition = (typeof validTransitions)[number];
  const isTransition = (value: string): value is ChangeRequestTransition => (validTransitions as readonly string[]).includes(value);
  const transition = async (form: HTMLFormElement, action: ChangeRequestTransition, reason: string) => {
    if (form.getAttribute('aria-busy') === 'true') return;
    // Per-form status region: this page has two decision forms, and an operator
    // must hear the progress/failure of the one they submitted.
    const output = form.querySelector<HTMLElement>('[data-result]');
    const submit = form.querySelector<HTMLButtonElement>('[data-submit], button[type="submit"]');
    form.setAttribute('aria-busy', 'true');
    if (submit) submit.disabled = true;
    if (output) output.textContent = 'Applying the controlled decision…';
    try {
      const result = await actions.changeRequests.transition({ id: String(form.dataset.changeRequestId), action, expectedVersion: BigInt(form.dataset.changeRequestVersion ?? '0'), reason: reason || undefined });
      if (result.data) { window.location.href = `/change-requests/${result.data.changeRequest.id}`; return; }
      if (output) { output.textContent = 'The decision was not applied. The request may have changed or authorization may have changed — refresh and try again if permitted.'; output.focus?.(); }
    } catch {
      if (output) { output.textContent = 'The service did not confirm the result. Your reason is kept. Refresh the record and its history before deciding whether to try again.'; output.focus?.(); }
    } finally { form.removeAttribute('aria-busy'); if (submit) submit.disabled = false; }
  };
  const startForm = document.querySelector<HTMLFormElement>('[data-action="start-review"]');
  const decisionForm = document.querySelector<HTMLFormElement>('[data-action="decision"]');
  const run = async (form: HTMLFormElement, action: string) => { if (!isTransition(action)) return; await transition(form, action, String(new FormData(form).get('reason') ?? '')); };
  if (startForm) { if (!startForm.querySelector('[data-submit]')) startForm.querySelector('button[type="submit"]')?.setAttribute('data-submit',''); startForm.setAttribute('method','post'); startForm.addEventListener('submit', (event) => { event.preventDefault(); void run(startForm, 'START_REVIEW'); }); }
  if (decisionForm) { decisionForm.setAttribute('method','post'); decisionForm.addEventListener('submit', (event) => { event.preventDefault(); const submitter = (event as SubmitEvent).submitter as HTMLButtonElement | null; void run(decisionForm, submitter?.dataset.actionValue ?? ''); }); }
</script>
