import AppLayout from '../../ui/layouts/AppLayout.astro';
import StatusBadge from '../../ui/components/StatusBadge.astro';
import ProviderUnavailableState from '../../ui/components/feedback/ProviderUnavailableState.astro';
import { changeRequestsReadDependencies } from '../../modules/change-requests/application/dependencies.js';
import { formatDate } from '../../shared/copy/format.js';
import { stateLabel, targetTypeLabel } from '../../shared/copy/ux-vocabulary.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Fchange-requests');
const validStates = ['DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'RETURNED', 'APPROVED', 'REJECTED', 'APPLYING', 'APPLIED', 'APPLICATION_FAILED', 'CANCELLED'] as const;
const requestedState = Astro.url.searchParams.get('state');
const state = validStates.find((value) => value === requestedState);
const targetType = Astro.url.searchParams.get('targetType')?.trim().slice(0, 100) || undefined;
// A dependency outage is UNAVAILABLE, never an empty register and never zero.
let providerUnavailable = false;
let requests: Awaited<
  ReturnType<ReturnType<typeof changeRequestsReadDependencies>['list']['execute']>
> = [];
try {
  requests = await changeRequestsReadDependencies().list.execute({
    actor,
    filter: { ...(state ? { state } : {}), ...(targetType ? { targetType } : {}) },
  });
} catch {
  providerUnavailable = true;
}
const canCreate = actor.permissions.some((permission) => permission.active !== false && permission.code === 'PERM-CHG-CREATE');
const hasFilters = Boolean(state || targetType);
---
<AppLayout title="Change Requests · QC Operations" locale="en" direction="ltr">
  <section class="page-head">
    <div><p class="eyebrow">Change requests</p><h1>Change Requests</h1><p class="lede">Proposed changes are versioned, reviewed, and audited. Approval does not rewrite the target record automatically.</p></div>
    {canCreate && <a class="button" href="/change-requests/new">New change request</a>}
  </section>
  <form class="filters" method="get" aria-label="Change request filters">
    <label for="targetType">Target type<input id="targetType" name="targetType" value={targetType ?? ''} maxlength="100" /></label>
    <label for="state">State<select id="state" name="state"><option value="">All states</option>{validStates.map((value) => <option value={value} selected={state === value}>{stateLabel(value)}</option>)}</select></label>
    <button type="submit">Filter</button>
  </form>
  {providerUnavailable ? <ProviderUnavailableState title="Change requests are temporarily unavailable" description="The change-request read did not return a confirmed result, so this register is not treated as empty." retryHref="/change-requests" /> : requests.length ? <div class="table-wrap"><table><caption>Change requests in your authorized scope</caption><thead><tr><th scope="col">Change no.</th><th scope="col">Target</th><th scope="col">State</th><th scope="col">Target version</th><th scope="col">Request version</th><th scope="col">Updated</th></tr></thead><tbody>{requests.map(({ changeRequest }) => <tr><th scope="row"><a href={`/change-requests/${changeRequest.id}`}>{changeRequest.changeNo}</a></th><td>{targetTypeLabel(changeRequest.targetType)}<small>{changeRequest.targetId}</small></td><td><StatusBadge status={changeRequest.state === 'UNDER_REVIEW' || changeRequest.state === 'SUBMITTED' ? 'REVIEW' : changeRequest.state === 'REJECTED' || changeRequest.state === 'CANCELLED' ? 'REJECTED' : changeRequest.state === 'APPROVED' || changeRequest.state === 'APPLIED' ? 'APPROVED' : 'DRAFT'} label={stateLabel(changeRequest.state)} /></td><td>{changeRequest.targetVersion.toString()}</td><td>{changeRequest.version.toString()}</td><td>{formatDate(changeRequest.updatedAt)}</td></tr>)}</tbody></table></div> : <section class="empty"><h2>{hasFilters ? 'No change requests match these filters' : 'No change requests found'}</h2><p>Requests outside your authorized scope are intentionally excluded.</p>{hasFilters && <a href="/change-requests">Clear all filters</a>}</section>}
</AppLayout>
<style>.page-head{display:flex;justify-content:space-between;gap:var(--space-5);align-items:start;margin-bottom:var(--space-6)}h1{margin:.25rem 0}.eyebrow{margin:0;color:var(--text-muted);font-size:var(--font-size-xs);letter-spacing:.12em;font-weight:700}.lede,.empty p{color:var(--text-muted);font-size:.86rem}.button,button{border:1px solid var(--color-accent-primary);background:var(--color-accent-primary);color:var(--color-text-inverse);padding:.65rem 1rem;border-radius:var(--radius-md);text-decoration:none;font-weight:700}.filters{display:flex;gap:var(--space-4);align-items:end;margin-bottom:var(--space-5)}label{display:grid;gap:.35rem;font-size:.8rem;color:var(--text-secondary)}input,select{min-height:2.5rem;padding:.5rem;background:var(--surface-panel);color:inherit;border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm)}.table-wrap{overflow-x:auto;border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg)}table{width:100%;min-width:920px;border-collapse:collapse;background:var(--surface-panel)}caption{text-align:start;padding:var(--space-4);color:var(--text-muted)}th,td{padding:.75rem;text-align:start;border-top:1px solid var(--color-border-subtle);font-size:.8rem}th{font-weight:700}a{color:var(--color-accent-primary-hover)}small{display:block;margin-top:.25rem;color:var(--text-muted);font-weight:400;font-size:var(--font-size-xs)}.empty{padding:var(--space-8);text-align:center;background:var(--surface-panel);border:1px dashed var(--color-border-strong);border-radius:var(--radius-lg)}@media(max-width:650px){.page-head,.filters{display:grid}.filters button{width:max-content}}</style>

---
import AppLayout from '../../ui/layouts/AppLayout.astro';
import FormErrorSummary from '../../ui/components/FormErrorSummary.astro';
import { actions } from 'astro:actions';
import {
  detailHref,
  extractDetailId,
  field,
  parseBigintField,
  toFormFailure,
  type FormFailure,
} from '../../ui/forms/mutation-post.js';
import {
  resolvePreselectedId,
  safeListHref,
  toSelectOptions,
} from '../../ui/forms/entity-select.js';
import { changeRequestTargetDependencies } from '../../modules/change-requests/application/dependencies.js';
import {
  DOCUMENT_VERSION_CHANGE_FIELDS,
  DOCUMENT_VERSION_CHANGE_LABELS,
} from '../../modules/change-requests/application/document-version-change-fields.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Fchange-requests%2Fnew');
const canCreate = actor.permissions.some((permission) => permission.active !== false && permission.code === 'PERM-CHG-CREATE');

const LIST_HREF = '/change-requests';
// Safe list return context (F-09): Cancel/back preserve a benign list filter
// when the operator arrived with one; anything else falls back to the list.
const returnHref = safeListHref(Astro.url.searchParams.get('returnTo'), LIST_HREF);
const REQUIRED_FIELDS = [
  { name: 'changeNo', label: 'Change number' },
  { name: 'documentVersionId', label: 'Controlled document version' },
  { name: 'changeField', label: 'Change field' },
  { name: 'proposedValue', label: 'Proposed value' },
  { name: 'reason', label: 'Reason' },
] as const;

// Authorized selector source: controlled document versions the actor may view
// (PERM-DOC-VIEW, resolved on the server from records available to the account).
// The operator always sees human labels (document number · title · revision
// · state); the technical version identifier travels only as the selected
// option value and every authoritative field (target id/version, snapshot,
// current value, data type) is re-resolved server-side on submit.
let targetOptions: { value: string; label: string }[] = [];
let targetVersions: Record<string, string> = {};
let targetPreview: Record<string, { document: string; revision: string; state: string; changeSummary: string; contentHash: string }> = {};
let selectorError = false;
if (canCreate) {
  try {
    const targets = await changeRequestTargetDependencies().targets.listChangeTargets({ actor });
    targetOptions = toSelectOptions(
      targets.map((item) => ({
        id: item.id,
        label: `${item.documentNo} · ${item.title} · ${item.revision} (${item.state})`,
      })),
    );
    for (const item of targets) {
      targetVersions[item.id] = item.version.toString();
      targetPreview[item.id] = {
        document: `${item.documentNo} · ${item.title}`,
        revision: item.revision,
        state: item.state,
        changeSummary: item.changeSummary ?? '—',
        contentHash: item.contentHash ?? '—',
      };
    }
  } catch {
    // Fail closed into an error state below: the form stays submittable so
    // entries are preserved, and the server still verifies the target on
    // submit. No unauthorized target detail is disclosed.
    selectorError = true;
  }
}

// Contextual preselection (e.g. `?documentVersionId=…` from the document
// workspace): honored only when still authorized, otherwise surfaced as a
// stale-selection warning that requires an explicit operator choice.
const preselected = resolvePreselectedId(
  Astro.url.searchParams.get('documentVersionId'),
  targetOptions,
);

let values = {
  changeNo: '',
  documentVersionId: preselected.id,
  expectedDocumentVersion: preselected.id ? (targetVersions[preselected.id] ?? '') : '',
  changeField: '',
  proposedValue: '',
  reason: '',
};
let failure: FormFailure | null = null;
let staleSelection = preselected.stale;

// POST baseline (F-05): without JavaScript the form performs a real POST to
// this page. The same contextual Astro Action — with the same server-side
// reauthorization and server-side resolution of target id/version, snapshot,
// current value, and data type — runs via Astro.callAction. Flat operator
// fields are shaped into the Action's input here (transport shaping only; all
// business validation stays in the use case). No business payload enters
// the URL: input travels in the POST body, success redirects (303) to the
// new record only.
if (Astro.request.method === 'POST' && canCreate) {
  const formData = await Astro.request.formData();
  values = {
    changeNo: field(formData, 'changeNo'),
    documentVersionId: field(formData, 'documentVersionId'),
    expectedDocumentVersion: field(formData, 'expectedDocumentVersion'),
    changeField: field(formData, 'changeField'),
    proposedValue: String(formData.get('proposedValue') ?? ''),
    reason: field(formData, 'reason'),
  };
  // A posted id outside the authorized selector list is never trusted: the
  // server re-verifies the target, and the operator gets a dependency
  // recovery pointing back at the authorized list.
  staleSelection = values.documentVersionId
    ? !targetOptions.some((option) => option.value === values.documentVersionId)
    : false;
  const fail = (error: unknown): void => {
    failure = toFormFailure(error, {
      entity: 'Change request',
      requiredFields: REQUIRED_FIELDS,
      values,
      listHref: LIST_HREF,
      listLabel: 'register',
    });
  };
  try {
    const data = await Astro.callAction(actions.changeRequests.createForDocumentVersion, {
      changeNo: values.changeNo,
      reason: values.reason,
      documentVersionId: values.documentVersionId,
      expectedDocumentVersion: parseBigintField(values.expectedDocumentVersion, 'documentVersionId'),
      changeField: values.changeField as 'revision' | 'changeSummary' | 'contentHash',
      proposedValue: values.proposedValue,
    });
    const id = extractDetailId(data);
    if (id) return Astro.redirect(detailHref(LIST_HREF, id), 303);
    failure = {
      kind: 'unknown',
      summary: 'The change request was received but no record reference came back.',
      recovery: 'Check the register before trying again to avoid a duplicate.',
      fieldErrors: {},
      firstInvalidField: null,
    };
  } catch (error) {
    fail(error);
  }
}

const preview = values.documentVersionId ? targetPreview[values.documentVersionId] : undefined;
const describedBy = (name: string): string | undefined =>
  failure?.fieldErrors[name] ? `${name}-error` : undefined;
const invalid = (name: string): 'true' | undefined =>
  failure?.fieldErrors[name] ? 'true' : undefined;
const fieldError = (name: string): string | null =>
  failure?.fieldErrors[name] ?? null;
---
<AppLayout title="New change request · QC Operations" locale="en" direction="ltr">
  <section class="head"><div><p class="eyebrow">New change request</p><h1>New change request</h1><p>This records a proposed change against a controlled document version. It does not apply, approve, or release the target.</p></div><a href={returnHref}>Back to register</a></section>
  {canCreate ? <form class="form" method="post" data-action="change-requests.createForDocumentVersion">{failure && <FormErrorSummary summary={failure.summary} recovery={failure.recovery} errors={Object.entries(failure.fieldErrors).map(([fieldId, message]) => ({ fieldId, message }))} listHref={returnHref} listLabel="register" />}<fieldset><legend>Request context</legend><div class="fields"><div><label for="changeNo">Change number<span class="hint" id="changeNo-help">Use the change number from your approved source. Reference numbers are assigned automatically.</span><input id="changeNo" name="changeNo" required value={values.changeNo} aria-invalid={invalid('changeNo')} aria-describedby={failure?.fieldErrors.changeNo ? 'changeNo-error changeNo-help' : 'changeNo-help'} /></label>{fieldError('changeNo') && <p class="field-error" id="changeNo-error">{fieldError('changeNo')}</p>}</div><div class="wide"><label for="reason">Reason<span class="hint" id="reason-help">Why this change is needed. Required for every change request.</span><textarea id="reason" name="reason" rows="3" required aria-invalid={invalid('reason')} aria-describedby={failure?.fieldErrors.reason ? 'reason-error reason-help' : 'reason-help'}>{values.reason}</textarea></label>{fieldError('reason') && <p class="field-error" id="reason-error">{fieldError('reason')}</p>}</div></div></fieldset><fieldset><legend>Controlled target</legend><p class="target-kind">Controlled document version <span class="hint">(the only supported change target in this baseline)</span></p><div class="fields"><div class="wide"><label for="documentVersionId">Controlled document version<span class="hint" id="documentVersionId-help">Choose from controlled document versions in your authorized scope. The target reference, version, snapshot, and current values are captured server-side after selection.</span><select id="documentVersionId" name="documentVersionId" required aria-invalid={invalid('documentVersionId')} aria-describedby={failure?.fieldErrors.documentVersionId ? 'documentVersionId-error documentVersionId-help' : 'documentVersionId-help'}><option value="">Select a controlled version…</option>{targetOptions.map((option)=><option value={option.value} selected={option.value===values.documentVersionId}>{option.label}</option>)}</select></label>{fieldError('documentVersionId') && <p class="field-error" id="documentVersionId-error">{fieldError('documentVersionId')}</p>}</div></div>{staleSelection && <p class="field-warning" role="status">The previously linked version is no longer available in your authorized scope. Choose a controlled version explicitly.</p>}{selectorError && <p class="field-warning" role="status">The controlled version list is temporarily unavailable. Your entries are kept — you can try again, or return to the register.</p>}{!selectorError && targetOptions.length===0 && <p class="field-warning" role="status">No controlled versions are available in your authorized scope. A new change request cannot be started until a version you may view exists.</p>}{preview && <dl class="preview" aria-label="Selected version current values"><div><dt>Document</dt><dd>{preview.document}</dd></div><div><dt>Revision</dt><dd>{preview.revision}</dd></div><div><dt>State</dt><dd>{preview.state}</dd></div><div><dt>Change summary</dt><dd>{preview.changeSummary}</dd></div><div><dt>Controlled content hash</dt><dd>{preview.contentHash}</dd></div></dl>}<input type="hidden" name="expectedDocumentVersion" value={values.documentVersionId ? (targetVersions[values.documentVersionId] ?? values.expectedDocumentVersion) : values.expectedDocumentVersion} /></fieldset><fieldset><legend>Proposed change</legend><div class="fields"><div><label for="changeField">Change field<span class="hint" id="changeField-help">Only the allowlisted document version fields can be proposed.</span><select id="changeField" name="changeField" required aria-invalid={invalid('changeField')} aria-describedby={failure?.fieldErrors.changeField ? 'changeField-error changeField-help' : 'changeField-help'}><option value="">Select a field…</option>{DOCUMENT_VERSION_CHANGE_FIELDS.map((option)=><option value={option} selected={option===values.changeField}>{DOCUMENT_VERSION_CHANGE_LABELS[option]}</option>)}</select></label>{fieldError('changeField') && <p class="field-error" id="changeField-error">{fieldError('changeField')}</p>}</div><div class="wide"><label for="proposedValue">Proposed value<span class="hint" id="proposedValue-help">The new value for the selected field. The current value is shown above and stored server-side.</span><textarea id="proposedValue" name="proposedValue" rows="3" required aria-invalid={invalid('proposedValue')} aria-describedby={failure?.fieldErrors.proposedValue ? 'proposedValue-error proposedValue-help' : 'proposedValue-help'}>{values.proposedValue}</textarea></label>{fieldError('proposedValue') && <p class="field-error" id="proposedValue-error">{fieldError('proposedValue')}</p>}</div></div></fieldset><p role="status" data-result></p><div class="actions"><a href={returnHref}>Cancel</a><button type="submit" data-submit>Create draft</button></div></form> : <section class="denied" role="alert"><h2>Creation is not available</h2><p>Your account does not have the explicit Change Request create permission.</p></section>}
</AppLayout>
<script>
import { actions } from 'astro:actions';
import { enhanceClassifiedForm } from '../../ui/forms/enhance-with-classification';
import { guardUnsavedChanges } from '../../ui/forms/unsaved-changes';
const form = document.querySelector<HTMLFormElement>('[data-action="change-requests.createForDocumentVersion"]');
let createdRecordId = '';
if (form) {enhanceClassifiedForm(form,{
  invoke: async (payload) => { const result = await actions.changeRequests.createForDocumentVersion(payload as Parameters<typeof actions.changeRequests.createForDocumentVersion>[0]); const record = result?.data as { changeRequest?: { id?: unknown } } | undefined; if (typeof record?.changeRequest?.id === 'string') createdRecordId = record.changeRequest.id; return result; },
  payload: (data) => ({ changeNo: String(data.get('changeNo')), reason: String(data.get('reason')), documentVersionId: String(data.get('documentVersionId')), expectedDocumentVersion: BigInt(String(data.get('expectedDocumentVersion'))), changeField: String(data.get('changeField')) as 'revision' | 'changeSummary' | 'contentHash', proposedValue: String(data.get('proposedValue')) }),
  progressText: 'Saving…',
  detailBaseHref: '/change-requests',
  onSuccess: () => { if (createdRecordId) window.location.href = `/change-requests/${createdRecordId}`; else window.location.reload(); },
}); guardUnsavedChanges(form);}
</script>
