<AppLayout title={`Edit draft · ${document.documentNo}`} locale="en" direction="ltr"><section class="head"><div><p class="eyebrow">Edit draft</p><h1>Edit draft revision {version.revision}</h1><p>{document.documentNo} · Record version {version.version.toString()}</p></div><a href={`/documents/${document.id}/versions/${version.id}`}>Back to version</a></section>{canEdit ? <form class="form" method="post" data-action="documents.updateDraft" data-document-id={document.id} data-version-id={version.id} data-expected-version={version.version.toString()}><label for="revision">Revision reference<input id="revision" name="revision" value={version.revision} required /></label><label for="changeSummary">Change summary<textarea id="changeSummary" name="changeSummary">{version.changeSummary ?? ''}</textarea></label><label for="contentHash">Controlled content hash<input id="contentHash" name="contentHash" value={version.contentHash ?? ''} /></label><p class="hint">Only draft versions are editable. Approved and historical versions remain immutable.</p><button type="submit">Save draft</button></form> : <section class="denied" role="alert"><h2>Draft editing unavailable</h2><p>This version is controlled or your account lacks the explicit edit permission.</p></section>}</AppLayout>
<script>
  import { actions } from 'astro:actions';
  const form=document.querySelector<HTMLFormElement>('[data-action="documents.updateDraft"]');
  if (form) {
    if (!form.querySelector('[data-result]')) {
      const status=document.createElement('p');
      status.setAttribute('data-result','');
      status.setAttribute('role','status');
      status.setAttribute('tabindex','-1');
      status.className='hint';
      form.appendChild(status);
    }
    const submit=form.querySelector<HTMLButtonElement>('button[type="submit"]');
    if (submit && !submit.hasAttribute('data-submit')) submit.setAttribute('data-submit','');
    form.addEventListener('submit',async(event)=>{
      event.preventDefault();
      if(form.getAttribute('aria-busy')==='true')return;
      const output=form.querySelector<HTMLElement>('[data-result]');
      form.setAttribute('aria-busy','true');
      if(submit)submit.disabled=true;
      if(output)output.textContent='Saving draft…';
      try{
        const data=new FormData(form);
        const result=await actions.documents.updateDraft({versionId:form.dataset.versionId!,expectedVersion:BigInt(form.dataset.expectedVersion!),revision:String(data.get('revision')),changeSummary:String(data.get('changeSummary')||'')||undefined,contentHash:String(data.get('contentHash')||'')||undefined});
        if(result.data){window.location.href=`/documents/${form.dataset.documentId}/versions/${form.dataset.versionId}`;return;}
        if(output){output.textContent='The draft was not saved. Refresh the version and review the current state before trying again.';output.focus?.();}
      }catch{
        if(output){output.textContent='The service did not confirm the result. Your entries are preserved. Refresh the record and its history before deciding whether to try again.';output.focus?.();}
      }finally{form.removeAttribute('aria-busy');if(submit)submit.disabled=false;}
    });
  }
</script>
