<AppLayout title={`Review · ${document.documentNo} Rev ${version.revision}`} locale="en" direction="ltr"><nav class="crumb"><a href="/documents">Controlled Documents</a><span>/</span><a href={`/documents/${document.id}`}>{document.documentNo}</a><span>/</span><span>Review</span></nav><section class="head"><div><p class="eyebrow">Document review</p><h1>Review revision {version.revision}</h1><p>{document.title} · {document.documentNo} · Record version {version.version.toString()}</p></div><StatusBadge status="REVIEW" label={stateLabel(version.state)} /></section><section class="compare"><div><span>Proposed revision</span><strong>{version.revision}</strong><small>{version.contentHash ?? 'Content hash missing'}</small></div><div><span>Previous controlled context</span><strong>{document.versions.find((item) => item.state === 'EFFECTIVE')?.revision ?? 'No effective version'}</strong><small>Existing history remains unchanged.</small></div></section><section class="panel"><h2>Review checklist</h2><ul><li>Confirm the exact version and content hash under review.</li><li>Review the change summary and linked Files capability records.</li><li>Approval is a separate controlled action and is never granted by opening this page.</li></ul><p class="muted">Scientific, effective-date, and approval authority policies remain server-controlled.</p></section><section class="actions">{canReview && version.state === 'IN_REVIEW' && <button class="button controlled" data-review-version={version.id} data-expected-version={version.version.toString()}>Record review</button>}{canApprove && version.state === 'IN_REVIEW' && <button class="button" data-approve-version={version.id} data-expected-version={version.version.toString()}>Approve revision</button>}<a href={`/documents/${document.id}/versions/${version.id}`}>Back to version</a></section></AppLayout>
<script>
  import { actions } from 'astro:actions';
  const section = document.querySelector<HTMLElement>('.actions');
  const status = document.createElement('p');
  status.setAttribute('data-result',''); status.setAttribute('role','status'); status.setAttribute('tabindex','-1');
  section?.appendChild(status);
  const guard = (b: HTMLButtonElement): boolean => b.disabled || !!b.closest('[aria-busy="true"]');
  const run = async (b: HTMLButtonElement, call: () => Promise<{ error?: unknown; data?: unknown }>, label: string) => {
    if (guard(b)) return;
    b.disabled = true; section?.setAttribute('aria-busy','true');
    status.textContent = label;
    try {
      const result = await call();
      if (result.data) { window.location.reload(); return; }
      status.textContent = 'The action was not applied. The version may have changed or authorization may have changed — refresh and try again if permitted.';
      status.focus?.();
    } catch { status.textContent = 'The service did not confirm the result. Refresh this version and its history before deciding whether to try again.'; status.focus?.(); }
    finally { b.disabled = false; section?.removeAttribute('aria-busy'); }
  };
  const review=document.querySelector<HTMLButtonElement>('[data-review-version]');
  review?.addEventListener('click',()=>void run(review,()=>actions.documents.review({versionId:review.dataset.reviewVersion!,expectedVersion:BigInt(review.dataset.expectedVersion!)}),'Recording review…'));
  const approve=document.querySelector<HTMLButtonElement>('[data-approve-version]');
  approve?.addEventListener('click',()=>void run(approve,()=>actions.documents.approve({versionId:approve.dataset.approveVersion!,expectedVersion:BigInt(approve.dataset.expectedVersion!)}),'Applying approval…'));
</script>
