---
<AppLayout title={`${test.labTestNo} · Laboratory`}><h1>{test.labTestNo}</h1><p>State: <strong>{stateLabel(test.state)}</strong> · Official result: <strong>{test.scientificResult??'Not determined'}</strong> · Version {test.version.toString()}</p>{sourceReceivingUnavailable && <ProviderUnavailableState title="Source receiving link unavailable" description="The test remains visible, but its source receiving relationship could not be confirmed." retryHref={Astro.url.pathname} />}<JourneyContextPanel ownerDomain="Laboratory" recordReference={`${test.labTestNo} · version ${test.version.toString()}`} currentState={`${stateLabel(test.state)} · Result ${test.scientificResult ?? stateLabel('NOT_DETERMINED')}`} nextAction={canExecute ? 'Open execution workspace' : canReview ? 'Open review workspace' : 'No laboratory action is available'} nextActionHref={canExecute ? `/laboratory/tests/${test.id}/execute` : canReview ? `/laboratory/tests/${test.id}/review` : undefined} nextOwner={test.state === 'DRAFT' ? 'Laboratory executor' : ['SUBMITTED', 'UNDER_REVIEW'].includes(test.state) ? 'Laboratory reviewer' : undefined} whyUnavailable={!canExecute && test.state === 'DRAFT' ? 'permission: draft editing is not available to this account' : !canReview && ['SUBMITTED', 'UNDER_REVIEW'].includes(test.state) ? 'permission/state: review is unavailable for this account or current state' : undefined} waitingOn={test.state === 'SUBMITTED' ? 'Laboratory reviewer' : test.state === 'UNDER_REVIEW' ? 'Approval decision' : undefined} expectedEvent={test.state === 'DRAFT' ? 'Submit test for review' : test.state === 'SUBMITTED' ? 'Begin review' : test.state === 'UNDER_REVIEW' ? 'Approve or return' : undefined} controlledContext={`${test.context.methodReference} · template ${test.context.versionNo} · source ${test.context.sourceReference}`} evidenceSummary={`${test.measurements.length} measurements · controlled equipment/calibration context preserved`} auditHref={`/audit?subjectType=LAB_TEST&subjectId=${encodeURIComponent(test.id)}`} relatedLinks={relatedLinks} /><section><h2>Controlled context</h2><dl><dt>Method</dt><dd>{test.context.methodReference}</dd><dt>Template version</dt><dd>{test.context.versionNo}</dd><dt>Source</dt><dd>{test.context.sourceReference}</dd></dl></section><section class="next"><h2>Next workspace</h2>{canExecute ? <a href={`/laboratory/tests/${test.id}/execute`}>Open execution workspace</a> : <p>Execution is read-only: the current state or your account does not allow draft editing.</p>}{canReview ? <a href={`/laboratory/tests/${test.id}/review`}>Open review workspace</a> : <p>Review is unavailable for the current state or account. Page visibility does not grant review authority.</p>}{test.originalTestId ? <p>Retest of an original laboratory test — sequence and authority follow the approved P-05 policy; the original test remains unchanged.</p> : canRetest ? <p>Retest authorization follows the approved P-05 policy: a retest may only be created by the approved authority, with its own record version and reason. The original test remains unchanged.</p> : <p>Retest requires the approved retest authority; this account does not hold it for this record.</p>}</section></AppLayout><style>section{padding:1rem;background:var(--surface-panel);border:1px solid var(--color-border-subtle)}dl{display:grid;grid-template-columns:auto 1fr;gap:.5rem 1rem}dd{margin:0}.next{display:grid;gap:.6rem;margin-top:1rem}.next p{margin:0;color:var(--text-muted)}a{color:var(--color-accent-primary-hover)}</style>

---
import AppLayout from '../../../../ui/layouts/AppLayout.astro';
import { classifyReadFailure, providerUnavailableResponse } from '../../../../shared/errors/read-failure.js';
import JourneyContextPanel from '../../../../ui/components/workflow/JourneyContextPanel.astro';
import { laboratoryReadDependencies } from '../../../../modules/laboratory/application/dependencies.js';
import { comparisonRows } from '../../../../modules/laboratory/application/lab-presentation.js';

const actor = Astro.locals.actor;
if (!actor)
  return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
let test;
try {
  test = await laboratoryReadDependencies().get.execute({ actor, id: Astro.params.labTestId ?? '' });
} catch (error) {
  if (classifyReadFailure(error) === 'UNAVAILABLE') return providerUnavailableResponse('Laboratory test details are temporarily unavailable', Astro.url.pathname + Astro.url.search);
  return Astro.redirect('/404');
}
// QC-100-FINAL-004 two-stage chain: stage-1 (Supervisor) approval needs
// PERM-LAB-APPROVE; the QCM final approval needs PERM-APR-APPROVE plus
// PERM-ESIG-SIGN and a reauthentication password in the request body.
const hasPermission = (code: string) =>
  actor.permissions.some((permission) => permission.code === code && permission.active !== false);
const canStageApprove = hasPermission('PERM-LAB-APPROVE');
const canFinalApprove = hasPermission('PERM-APR-APPROVE') && hasPermission('PERM-ESIG-SIGN');
const canReturn = hasPermission('PERM-LAB-RETURN');
const atSupervisorStage = test.state === 'UNDER_REVIEW';
const atQcmStage = test.state === 'PENDING_QCM_APPROVAL';

// QC-100-FINAL-038 R5/R6: observed values are shown side-by-side with the
// approved criteria so the reviewer compares evidence instead of recalling
// limits. Pass/Fail badges come only from approved acceptance rules frozen
// with the record; rows without an approved rule are the reviewer's decision,
// never an invented threshold.
const rows = comparisonRows(test);
const outcomeLabels: Record<string, string> = {
  PASS: 'Pass',
  FAIL: 'Fail',
  REVIEWER_DECISION: 'Reviewer decision',
  NOT_RECORDED: 'Not recorded',
};
const documents = test.context.documents;
---
<AppLayout title={`Review ${test.labTestNo}`}>
  <h1>Laboratory review</h1>
  <p>{test.labTestNo} · Submitted context version {test.version.toString()}</p>
  <JourneyContextPanel ownerDomain="Laboratory" recordReference={`${test.labTestNo} · version ${test.version.toString()}`} currentState={test.state} nextAction={atSupervisorStage && canStageApprove ? 'Supervisor approval or return' : atQcmStage && canFinalApprove ? 'QCM final approval or return' : canReturn ? 'Return for correction' : 'Review actions depend on current state and permissions'} nextOwner={atSupervisorStage ? 'Supervisor review stage' : atQcmStage ? 'QCM final review stage' : undefined} whyUnavailable={!canStageApprove && !canFinalApprove && !canReturn ? 'permission: this account has no available review action' : undefined} controlledContext={`${test.context.methodReference} · version ${test.context.versionNo} · source ${test.context.sourceReference}`} evidenceSummary={`${test.measurements.length} raw measurement(s) · ${documents.length} linked controlled document(s) · ${test.context.equipment.length} equipment/calibration snapshot(s)`} auditHref={`/audit?subjectType=LAB_TEST&subjectId=${encodeURIComponent(test.id)}`} relatedLinks={[{label:'Laboratory test record',href:`/laboratory/tests/${test.id}`,detail:'Read-only record overview'}]} />
  <section>
    <h2>Observed results vs approved criteria</h2>
    <p>
      Pass and Fail badges are evaluated only from the approved acceptance rules frozen with this
      record. Rows marked “Reviewer decision” have no approved rule and are decided by the
      reviewer; the system never invents thresholds. Values marked “calculated” come from the
      approved calculation rule.
    </p>
    {
      rows.length ? (
        <table class="comparison">
          <caption>Measured results and controlled criteria for {test.labTestNo}</caption>
          <thead>
            <tr>
              <th scope="col">Sample</th>
              <th scope="col">Parameter</th>
              <th scope="col">Observed</th>
              <th scope="col">Unit</th>
              <th scope="col">Approved criteria</th>
              <th scope="col">Outcome</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr>
                <th scope="row">{row.sampleIdentifier}</th>
                <td>
                  {row.parameterLabel}
                  {row.required ? <span aria-hidden="true"> *</span> : null}
                </td>
                <td>
                  {row.observed ?? '—'}
                  {row.calculated ? <span class="calc-note"> (calculated)</span> : null}
                </td>
                <td>{row.unit ?? '—'}</td>
                <td class="criteria">{row.criteriaText}</td>
                <td>
                  <span class={`outcome outcome-${row.outcome.toLowerCase().replace('_', '-')}`}>
                    {outcomeLabels[row.outcome]}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p class="muted">No controlled parameters are attached to this record.</p>
      )
    }
  </section>
  <section>
    <h2>Read-only submission context</h2>
    <p>Measurements: {test.measurements.length}; samples: {test.samples.length}</p>
    <p>
      Reviewers cannot edit submitted measurements. Review and approval require server-side
      permissions, SoD, current version, and approved policy.
    </p>
    <p>
      Reject (TR-LAB-007) is a controlled workflow decision with a required reason and separation
      of duties. It is not a scientific FAIL result: the official result is evaluated only by the
      approved source. Reject decision authority itself requires an approved policy source
      (POLICY / SCIENTIFIC SOURCE REQUIRED) and is denied by default.
    </p>
    <h3>Controlled documents</h3>
    {
      documents.length ? (
        <ul>
          {documents.map((document) => (
            <li>
              {String(document.snapshot.documentNo ?? '')} — {String(document.snapshot.title ?? '')}
              {document.snapshot.revision ? ` (rev. ${String(document.snapshot.revision)})` : ''} ·{' '}
              {document.usageType}
            </li>
          ))}
        </ul>
      ) : (
        <p class="muted">No controlled documents are linked to this method context.</p>
      )
    }
  </section>
  <aside class="decision" data-lab-id={test.id} data-version={test.version.toString()}>
    <h2>Decision rail</h2>
    {
      atSupervisorStage && canStageApprove ? (
        <button data-action="laboratory.approve" data-submit>
          Supervisor approval — send to QCM
        </button>
      ) : null
    }
    {
      atSupervisorStage && canReturn ? (
        <form data-action="laboratory.returnTest">
          <label for="lab-return-reason">
            Return reason<textarea id="lab-return-reason" name="reason" required></textarea>
          </label>
          <button class="secondary" type="submit" data-submit>
            Return for correction
          </button>
          <p data-result role="status" tabindex="-1" class="action-status"></p>
        </form>
      ) : null
    }
    {
      atQcmStage && canFinalApprove ? (
        <form data-action="laboratory.finalApprove">
          <label for="lab-final-approval-password">
            Reauthentication password (final approval signature)
            <input
              id="lab-final-approval-password"
              name="reauthenticationSecret"
              type="password"
              autocomplete="current-password"
              required
            />
          </label>
          <button type="submit" data-submit>
            QCM final approval — approve and lock
          </button>
          <p data-result role="status" tabindex="-1" class="action-status"></p>
        </form>
      ) : null
    }
    {
      atQcmStage && canReturn ? (
        <form data-action="laboratory.returnTest">
          <label for="lab-qcm-return-reason">
            QCM return reason<textarea id="lab-qcm-return-reason" name="reason" required></textarea>
          </label>
          <button class="secondary" type="submit" data-submit>
            Return at QCM stage
          </button>
          <p data-result role="status" tabindex="-1" class="action-status"></p>
        </form>
      ) : null
    }
    <p class="muted">
      Only the QCM final approval carries the binding electronic signature. PASS is never a release
      command.
    </p>
  </aside>
</AppLayout>
<script>
import{actions}from'astro:actions';
const context=document.querySelector<HTMLElement>('[data-lab-id]');const id=context?.dataset.labId??'';const version=context?.dataset.version??'0';
const busy=(scope:Element|null,on:boolean)=>{if(on)scope?.setAttribute('aria-busy','true');else scope?.removeAttribute('aria-busy');};
document.querySelectorAll<HTMLButtonElement>('[data-action="laboratory.approve"]').forEach((btn)=>btn.addEventListener('click',async()=>{if(btn.disabled||btn.closest('[aria-busy="true"]'))return;btn.disabled=true;busy(btn.closest('aside'),true);btn.textContent='Applying Supervisor stage approval…';try{const result=await actions.laboratory.approve({id,expectedVersion:BigInt(version)});if(result.data)location.reload();else{btn.textContent='Not applied — refresh and verify the current version.';btn.disabled=false;}}catch{btn.textContent='The service did not confirm the result. Refresh the test and its history before deciding whether to try again.';btn.disabled=false;}finally{busy(btn.closest('aside'),false);}}));
document.querySelectorAll<HTMLFormElement>('[data-action="laboratory.returnTest"]').forEach((form)=>form.addEventListener('submit',async(e)=>{e.preventDefault();if(form.getAttribute('aria-busy')==='true')return;const btn=form.querySelector<HTMLButtonElement>('[data-submit]');const out=form.querySelector<HTMLElement>('[data-result]');const reason=String(new FormData(form).get('reason')??'');if(btn)btn.disabled=true;busy(form,true);if(out)out.textContent='Returning for correction…';try{const result=await actions.laboratory.returnTest({id,expectedVersion:BigInt(version),reason});if(result.data)location.reload();else if(out){out.textContent='Return was not applied. Refresh and verify the current version.';out.focus?.();}}catch{if(out){out.textContent='The service did not confirm the result. Your reason is kept. Refresh the record and its history before deciding whether to try again.';out.focus?.();}}finally{busy(form,false);if(btn)btn.disabled=false;}}));
document.querySelectorAll<HTMLFormElement>('[data-action="laboratory.finalApprove"]').forEach((form)=>form.addEventListener('submit',async(e)=>{e.preventDefault();if(form.getAttribute('aria-busy')==='true')return;const btn=form.querySelector<HTMLButtonElement>('[data-submit]');const out=form.querySelector<HTMLElement>('[data-result]');const reauthenticationSecret=String(new FormData(form).get('reauthenticationSecret')??'');if(btn)btn.disabled=true;busy(form,true);if(out)out.textContent='Applying QCM final approval with signature…';try{const result=await actions.laboratory.finalApprove({id,expectedVersion:BigInt(version),reauthenticationSecret});if(result.data)location.reload();else if(out){out.textContent='The final approval was not applied. Verify your reauthentication password and the current version, then try again.';out.focus?.();}}catch{if(out){out.textContent='The service did not confirm the result. Refresh the test and its approval history before deciding whether to try again.';out.focus?.();}}finally{busy(form,false);if(btn)btn.disabled=false;}}));
</script>
<style>
  section,
  aside {
    padding: 1rem;
    margin-top: 1rem;
    background: var(--surface-panel);
    border: 1px solid var(--color-border-subtle);
  }
  button {
    padding: 0.7rem;
    background: var(--color-accent-primary);
    color: white;
    border: 0;
    border-radius: var(--radius-md);
  }
  button.secondary {
    border-color: var(--border-default);
    background: var(--surface-raised);
    color: var(--text-primary);
  }
  label {
    display: block;
    margin-top: 0.75rem;
  }
  textarea,
  input {
    width: 100%;
    margin-top: 0.25rem;
  }
  .comparison {
    border-collapse: collapse;
    width: 100%;
    margin-top: 1rem;
  }
  .comparison th,
  .comparison td {
    border: 1px solid var(--color-border-subtle);
    padding: 0.5rem;
    text-align: start;
    vertical-align: top;
  }
  .criteria {
    font-size: 0.85rem;
  }
  .calc-note {
    color: var(--text-muted);
    font-size: 0.8rem;
  }
  .outcome {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: var(--radius-md);
    font-size: 0.8rem;
    border: 1px solid var(--color-border-subtle);
  }
  .outcome-pass {
    border-color: var(--status-success, green);
  }
  .outcome-fail {
    border-color: var(--status-danger, red);
  }
  .outcome-reviewer-decision,
  .outcome-not-recorded {
    border-style: dashed;
  }
</style>

---
import AppLayout from '../../../ui/layouts/AppLayout.astro';
import AppliedFilters from '../../../ui/components/data/AppliedFilters.astro';
import DataTable from '../../../ui/components/data/DataTable.astro';
import Pagination from '../../../ui/components/data/Pagination.astro';
import FilterBar from '../../../ui/components/data/FilterBar.astro';
import { parsePageInput } from '../../../shared/pagination/page.js';
import { AppError } from '../../../shared/errors/app-error.js';
import ProviderUnavailableState from '../../../ui/components/feedback/ProviderUnavailableState.astro';
import OperationalState from '../../../ui/components/feedback/OperationalState.astro';
import { laboratoryReadDependencies } from '../../../modules/laboratory/application/dependencies.js';
import { formatDate } from '../../../shared/copy/format.js';
import { stateLabel } from '../../../shared/copy/ux-vocabulary.js';
import { identityAdminReadDependencies } from '../../../modules/identity/application/admin-dependencies.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Flaboratory%2Ftests');

// The register's own workflow states, declared at the surface that renders them
// (pages do not import another module's domain). One state per option, never a
// merged bucket, so a dashboard stage count can open exactly its own set.
const states = [
  'DRAFT',
  'SUBMITTED',
  'UNDER_REVIEW',
  'PENDING_QCM_APPROVAL',
  'RETURNED',
  'APPROVED',
  'REJECTED',
  'VOID',
] as const;
const params = Astro.url.searchParams;
const page = parsePageInput({ page: params.get('page'), pageSize: params.get('pageSize') });
const search = params.get('q')?.slice(0, 200).trim() || undefined;
const requestedState = params.get('state');
const state = states.find((value) => value === requestedState);
// Ownership is the same owner dimension the dashboard counts, so a personal
// laboratory count opens exactly its own records.
const ownership = params.get('ownership') === 'mine' ? ('mine' as const) : undefined;
const sort = (['updated', 'testNo', 'state'] as const).find((value) => value === params.get('sort')) ?? 'updated';
const direction = params.get('direction') === 'asc' ? 'asc' : 'desc';

const chipHref = (drop: string) => {
  const next = new URLSearchParams(params);
  next.delete(drop);
  const search = next.toString();
  return `/laboratory/tests${search ? `?${search}` : ''}`;
};
const appliedFilters = [
  search && { label: 'Search', value: search, href: chipHref('q') },
  state && { label: 'Workflow state', value: stateLabel(state), href: chipHref('state') },
  ownership && { label: 'Ownership', value: 'Only mine', href: chipHref('ownership') },
].filter((chip): chip is { label: string; value: string; href: string } => Boolean(chip));
const hasFilters = appliedFilters.length > 0;

// The register is a bounded, newest-first page plus the readable count for the
// same filter. A dependency outage stays UNAVAILABLE rather than an empty
// register, so no "no tests" claim is made when the read did not confirm one.
let providerUnavailable = false;
let accessDenied = false;
let result: { items: Awaited<ReturnType<ReturnType<typeof laboratoryReadDependencies>['list']['execute']>>['items']; total: number } = { items: [], total: 0 };
try {
  result = await laboratoryReadDependencies().list.execute({
    actor,
    filter: { state, ownership, search, sort, direction },
    limit: page.pageSize,
    offset: page.offset,
  });
} catch (error) {
  if (error instanceof AppError && error.category === 'AUTHORIZATION') accessDenied = true;
  else providerUnavailable = true;
}
const tests = result.items;
const totalPages = Math.max(1, Math.ceil(result.total / page.pageSize));

// The register names the executor, never a raw account identifier. Resolution
// is presentation-only and failure-tolerant: an unavailable identity read
// still renders the register.
let executorNames = new Map<string, string>();
try {
  executorNames = new Map(
    (await identityAdminReadDependencies().listUsers.execute({ actor })).map((user) => [
      user.id,
      user.displayName,
    ]),
  );
} catch {
  // Presentation-only; fall back to a named-account label below.
}
const executorLabel = (executorId: string | null | undefined) =>
  executorId ? (executorNames.get(executorId) ?? 'Named account') : 'Not recorded';
---
<AppLayout title="Laboratory Tests · QC Operations" locale="en" direction="ltr">
  <div class="scientific-register">
  <section class="head workspace-header"><div><p class="eyebrow">CONTROLLED LABORATORY</p><h1>Laboratory tests</h1><p class="lede">Review method, sample, result, execution, and approval context without editing controlled history.</p><p><a href="/laboratory/report-templates">Enter Subatmospheric Air Leakage or Pressure Decay report draft</a></p></div><a class="button" href="/laboratory/tests/new">Create laboratory test</a></section>
  <FilterBar clearHref={hasFilters ? '/laboratory/tests' : undefined} label="Laboratory test filters">
    <label for="q">Search<input id="q" name="q" type="search" value={search ?? ''} maxlength="200" placeholder="Test number or sample identifier" /></label>
    <label for="state">Workflow state<select id="state" name="state"><option value="">All states</option>{states.map((value) => <option value={value} selected={state === value}>{stateLabel(value)}</option>)}</select></label>
    <label for="ownership">Ownership<select id="ownership" name="ownership"><option value="">All records</option><option value="mine" selected={ownership === 'mine'}>Only mine</option></select></label>
    <label for="sort">Sort by<select id="sort" name="sort"><option value="updated" selected={sort === 'updated'}>Recently updated</option><option value="testNo" selected={sort === 'testNo'}>Test number</option><option value="state" selected={sort === 'state'}>Workflow state</option></select></label>
    <label for="direction">Direction<select id="direction" name="direction"><option value="desc" selected={direction === 'desc'}>Descending</option><option value="asc" selected={direction === 'asc'}>Ascending</option></select></label>
  </FilterBar>
  <AppliedFilters
    filters={appliedFilters}
    clearHref={hasFilters ? '/laboratory/tests' : undefined}
    note={providerUnavailable || accessDenied
      ? 'A confirmed laboratory count is unavailable for this request.'
      : `Showing ${tests.length} of ${result.total} laboratory tests in your authorized scope — page ${page.page} of ${totalPages}.`}
  />
  {accessDenied ? <OperationalState state="denied" title="This account cannot view laboratory tests" description="No records or counts were returned for this account. Ask your administrator to confirm access." /> : providerUnavailable ? <ProviderUnavailableState title="Laboratory data is temporarily unavailable" description="No test count or result state is shown because the laboratory provider did not confirm a response." retryHref="/laboratory/tests" /> : tests.length ? <DataTable caption={`Laboratory tests — ${result.total} matching records`} summary={`Showing ${tests.length} of ${result.total} authorized records · page ${page.page} of ${totalPages}. Sorted by ${sort} ${direction}; record id breaks ties.`} density="compact"><thead><tr><th scope="col">Test number</th><th scope="col">Sample</th><th scope="col">Method / version</th><th scope="col">State</th><th scope="col">Official result</th><th scope="col">Executor</th><th scope="col">Last updated</th></tr></thead><tbody>{tests.map((test) => <tr><th scope="row"><a href={`/laboratory/tests/${test.id}`}>{test.labTestNo}</a></th><td>{test.samples.map((sample) => sample.identifier).join(', ') || 'Not recorded'}</td><td>{test.context.methodReference} · v{test.context.versionNo}</td><td>{stateLabel(test.state)}</td><td>{test.scientificResult ?? 'Not determined'}</td><td>{executorLabel(test.authorId)}</td><td><time datetime={test.updatedAt}>{formatDate(new Date(test.updatedAt))}</time></td></tr>)}</tbody><Fragment slot="pagination"><Pagination page={page.page} totalPages={totalPages} total={result.total} itemLabel="laboratory tests" baseUrl="/laboratory/tests" /></Fragment></DataTable> : <OperationalState state={hasFilters ? "filtered-empty" : "empty"} title={hasFilters ? "No laboratory tests match these filters" : "No laboratory tests yet"} description={hasFilters ? "Nothing in your authorized scope matches the filters above. Remove a filter to widen the search." : "Tests appear here once they are created."} actionLabel={hasFilters ? "Clear all filters" : "Create the first test"} actionHref={hasFilters ? "/laboratory/tests" : "/laboratory/tests/new"} />}
  </div>
</AppLayout>
