  {providerUnavailable ? <ProviderUnavailableState title="Findings are temporarily unavailable" /> : findings.length ? <div class="table-wrap"><table><caption>{findings.length} authorized finding{findings.length === 1 ? '' : 's'}</caption><thead><tr><th scope="col">Finding number</th><th scope="col">Summary</th><th scope="col">Severity</th><th scope="col">State</th><th scope="col">Owner</th><th scope="col">Created</th><th scope="col">Source context</th></tr></thead><tbody>{findings.map((finding) => <tr><th scope="row"><a href={`/quality/findings/${finding.id}`}>{finding.findingNo}</a></th><td>{finding.title}</td><td>{severityLabel(finding.severity)}</td><td>{stateLabel(finding.state)}</td><td>{ownerLabel(finding.ownerId)}</td><td><time datetime={finding.createdAt.toISOString()}>{finding.createdAt.formatDate('en-SA', { timeZone: 'Asia/Riyadh' })}</time></td><td>{finding.sourceContext ? 'Recorded' : 'Not provided'}</td></tr>)}</tbody></table></div> : <section class="empty-state"><p class="eyebrow">NO MATCHES</p><h2>No findings match this view</h2><p>{state ? 'Clear the state filter or choose another state.' : 'No findings are available in your authorized scope.'}</p>{state && <a href="/quality/findings">Clear filters</a>}</section>}
