import AppLayout from '../../../ui/layouts/AppLayout.astro';
import JourneyContextPanel from '../../../ui/components/workflow/JourneyContextPanel.astro';
import { ncrReadDependencies } from '../../../modules/quality/ncr/application/dependencies.js';
import { capaReadDependencies } from '../../../modules/quality/capa/application/dependencies.js';
import { rcaReadDependencies } from '../../../modules/quality/rca/application/dependencies.js';
import { listFindingsForActor } from '../../../modules/quality/findings/application/list-findings-for-actor.js';
import { stateLabel } from '../../../shared/copy/ux-vocabulary.js';
import { formatDateTime } from '../../../shared/copy/format.js';
import { AppError } from '../../../shared/errors/app-error.js';
const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login');
// F-05 baseline: a read failure renders the unavailable state, never a 500.
const ncrId = Astro.params.ncrId ?? '';
let ncr: Awaited<ReturnType<ReturnType<typeof ncrReadDependencies>['get']['execute']>> | undefined;
let providerUnavailable = false;
if (/^[0-9a-f-]{36}$/i.test(ncrId)) {
  try { ncr = await ncrReadDependencies().get.execute({ id: ncrId, actor }); }
  catch (error) {
    if (!(error instanceof AppError && error.code === 'RESOURCE_NOT_FOUND')) providerUnavailable = true;
  }
} else Astro.response.status = 404;
if (!ncr && !providerUnavailable) Astro.response.status = 404;
if (providerUnavailable) Astro.response.status = 503;
// Related records are resolved server-side through each owning domain's own
// scope-limited reads; this page never queries another domain's table directly
// and holds no mutation authority over finding or CAPA state.
const [findingResult, capaResult, rcaResult] = await Promise.allSettled([
  ncr?.findingId ? listFindingsForActor(actor).then((findings) => findings.find((f) => f.id === ncr?.findingId)) : Promise.resolve(undefined),
  ncr ? capaReadDependencies().list.execute({ actor }).then((all) => all.filter((capa) => capa.ncrId === ncr?.id)) : Promise.resolve([]),
  ncr ? rcaReadDependencies().list.execute({ actor, ncrId: ncr.id }) : Promise.resolve([]),
]);
const sourceFinding = findingResult.status === 'fulfilled' ? findingResult.value : undefined;
const relatedCapas = capaResult.status === 'fulfilled' ? capaResult.value : [];
const relatedRcas = rcaResult.status === 'fulfilled' ? rcaResult.value : [];
const relatedUnavailable = findingResult.status === 'rejected' || capaResult.status === 'rejected' || rcaResult.status === 'rejected';
---
<AppLayout title={`${ncr?.ncrNo ?? 'NCR'} · Quality`} locale="en" direction="ltr">{providerUnavailable ? <main><h1>NCR details are temporarily unavailable</h1><p role="status">The record source could not be reached. No record was changed. Retry from <a href="/quality/ncr">NCR records</a>.</p></main> : ncr ? <><p class="eyebrow">NCR</p><h1>{ncr.ncrNo}</h1><p>{ncr.title}</p><p class="lede">{ncr.description}</p>
<JourneyContextPanel ownerDomain="Quality / NCR" recordReference={`${ncr.ncrNo} · version ${ncr.version.toString()}`} currentState={stateLabel(ncr.state)} nextOwner={['OPEN', 'UNDER_INVESTIGATION', 'RCA_IN_PROGRESS', 'CAPA_IN_PROGRESS'].includes(ncr.state) ? 'NCR owner / investigation' : ncr.state === 'READY_FOR_CLOSURE' ? 'NCR reviewer' : undefined} whyUnavailable={ncr.state === 'READY_FOR_CLOSURE' ? 'policy: closure requires the approved NCR review authority; direct creation and closure are not enabled here' : ncr.state === 'CLOSED' ? 'state: controlled closure is complete' : undefined} waitingOn={['UNDER_INVESTIGATION', 'RCA_IN_PROGRESS'].includes(ncr.state) ? 'Investigation / RCA progress' : ncr.state === 'CAPA_IN_PROGRESS' ? 'Linked CAPA execution' : undefined} expectedEvent={['OPEN', 'UNDER_INVESTIGATION'].includes(ncr.state) ? 'Investigation progress' : ncr.state === 'CAPA_IN_PROGRESS' ? 'CAPA completion' : ncr.state === 'READY_FOR_CLOSURE' ? 'Controlled closure decision' : undefined} controlledContext={`NCR ${ncr.ncrNo} · record version ${ncr.version.toString()}`} evidenceSummary={`Affected item ${ncr.affectedItemCode ?? 'not supplied'} · lot ${ncr.affectedLot ?? 'not supplied'}`} auditHref={`/audit?subjectType=NCR&subjectId=${encodeURIComponent(ncr.id)}`} relatedLinks={[{ label: 'Findings register', href: '/quality/findings', detail: 'Quality-owned records' }, ...relatedRcas.map((rca) => ({ label: rca.rcaNo ?? `RCA for ${ncr.ncrNo}`, href: `/quality/rca/${rca.id}`, detail: stateLabel(rca.state) })), ...relatedCapas.map((capa) => ({ label: `CAPA ${capa.capaNo}`, href: `/quality/capa/${capa.id}`, detail: stateLabel(capa.state) }))]} />
<dl><dt>State</dt><dd>{stateLabel(ncr.state)}</dd><dt>Version</dt><dd>{ncr.version.toString()}</dd><dt>Opened</dt><dd>{ncr.openedAt ? formatDateTime(ncr.openedAt) : 'Not opened'}</dd><dt>Closed</dt><dd>{ncr.closedAt ? formatDateTime(ncr.closedAt) : 'Not closed'}</dd><dt>Affected item</dt><dd>{ncr.affectedItemCode ?? 'Not supplied'}</dd><dt>Affected lot</dt><dd>{ncr.affectedLot ?? 'Not supplied'}</dd></dl>
<section class="related"><h2>Source finding</h2>{findingResult.status === 'rejected' ? <p role="status">The Finding source is temporarily unavailable. Retry this record.</p> : sourceFinding ? <p><a href={`/quality/findings/${sourceFinding.id}`}>{sourceFinding.findingNo}</a><span>{stateLabel(sourceFinding.state)}</span></p> : <p class="muted">{ncr.findingId ? 'The source finding is not visible in your authorized scope.' : 'No source finding is linked to this NCR.'}</p>}</section>
<section class="related"><h2>Related RCA</h2>{relatedUnavailable && rcaResult.status === 'rejected' ? <p role="status">The RCA source is temporarily unavailable. Retry this record.</p> : relatedRcas.length ? <ul>{relatedRcas.map((rca) => <li><a href={`/quality/rca/${rca.id}`}>{rca.rcaNo ?? `Root-cause analysis for ${ncr.ncrNo}`}</a><span>{stateLabel(rca.state)}</span></li>)}</ul> : <p class="muted">No linked RCA is visible in your authorized scope.</p>}<p class="note">This is a read-only linkage; transitions remain owned by the authorized RCA workflow.</p></section>
<section class="related"><h2>Linked CAPAs</h2>{relatedUnavailable && capaResult.status === 'rejected' ? <p role="status">The CAPA source is temporarily unavailable. Retry this record.</p> : relatedCapas.length ? <ul>{relatedCapas.map((capa) => <li><a href={`/quality/capa/${capa.id}`}>{capa.capaNo}</a><span>{stateLabel(capa.state)}</span></li>)}</ul> : <p class="muted">No CAPA linked to this NCR is visible in your authorized scope.</p>}<p class="note">This is a read-only linkage. PD-17 decision owner: QMS process owner. NCR closure remains unavailable while its workflow and authority decision is unresolved.</p></section></> : <main><h1>NCR record not found</h1><p>This record does not exist or is outside your authorized scope.</p><a href="/quality/ncr">Return to NCR records</a></main>}</AppLayout>
<style>.eyebrow,.lede{color:var(--text-muted)}dl{display:grid;grid-template-columns:max-content 1fr;gap:.65rem 1rem;background:var(--surface-panel);padding:1rem}dt{font-weight:700}dd{margin:0}.related{margin-top:1rem;padding:1rem;background:var(--surface-panel);border:1px solid var(--color-border-subtle)}.related a{color:var(--color-accent-primary-hover)}.related span{color:var(--text-muted);margin-inline-start:.5rem}.note{color:var(--text-muted);font-size:.8rem}</style>

---
import AppLayout from '../../../ui/layouts/AppLayout.astro';
import ProviderUnavailableState from '../../../ui/components/feedback/ProviderUnavailableState.astro';
import { ncrReadDependencies } from '../../../modules/quality/ncr/application/dependencies.js';
import { rcaReadDependencies } from '../../../modules/quality/rca/application/dependencies.js';
import { findingsReadDependencies } from '../../../modules/quality/findings/application/dependencies.js';
import { stateLabel } from '../../../shared/copy/ux-vocabulary.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Fquality%2Fncr');
const states = ['DRAFT', 'OPEN', 'UNDER_INVESTIGATION', 'RCA_IN_PROGRESS', 'CAPA_IN_PROGRESS', 'READY_FOR_CLOSURE', 'CLOSED', 'VOID'] as const;
const requestedState = Astro.url.searchParams.get('state');
const state = states.find((value) => value === requestedState);
let unavailable = false;
let ncrs: Awaited<ReturnType<ReturnType<typeof ncrReadDependencies>['list']['execute']>> = [];
let rcas: Awaited<ReturnType<ReturnType<typeof rcaReadDependencies>['list']['execute']>> = [];
let findings: Awaited<ReturnType<ReturnType<typeof findingsReadDependencies>['list']['execute']>> = [];
try {
  [ncrs, rcas, findings] = await Promise.all([
    ncrReadDependencies().list.execute({ actor, state }),
    rcaReadDependencies().list.execute({ actor }),
    findingsReadDependencies().list.execute({ actor }),
  ]);
} catch {
  unavailable = true;
}
const findingById = new Map(findings.map((finding) => [finding.id, finding]));
const rcaCount = new Map<string, number>();
for (const rca of rcas) rcaCount.set(rca.ncrId, (rcaCount.get(rca.ncrId) ?? 0) + 1);
const rows = ncrs.map((ncr) => ({ ncr, finding: ncr.findingId ? findingById.get(ncr.findingId) : undefined, rcaCount: rcaCount.get(ncr.id) ?? 0 }));
---
<AppLayout title="NCR · Quality" locale="en" direction="ltr">
  <section class="page-head"><div><p class="eyebrow">Quality register</p><h1>Non-conformance records</h1><p class="lede">Current records in your authorized scope, with their source Finding and RCA workspace.</p></div></section>
  <section class="policy" aria-labelledby="policy-heading"><h2 id="policy-heading">Workflow decisions still pending</h2><ul><li><strong>PD-15 · QC owner:</strong> approved Finding-to-NCR initiation criteria.</li><li><strong>PD-16 · QC / inspection procedure owner:</strong> consequence of an inspection FAIL.</li><li><strong>PD-17 · QMS owner:</strong> NCR closure authority and workflow.</li></ul><p>These actions stay unavailable until their owners approve the governing decision. Existing records remain readable.</p></section>
  <form class="filters" method="get"><label for="state">State<select id="state" name="state"><option value="">All states</option>{states.map((value) => <option value={value} selected={state === value}>{stateLabel(value)}</option>)}</select></label><button type="submit">Apply filter</button>{state && <a href="/quality/ncr">Clear</a>}</form>
  {unavailable ? <ProviderUnavailableState title="NCR records are temporarily unavailable" /> : ncrs.length ? <div class="table-wrap"><table><caption>{ncrs.length} authorized NCR record{ncrs.length === 1 ? '' : 's'}</caption><thead><tr><th scope="col">NCR</th><th scope="col">Nonconformance</th><th scope="col">State</th><th scope="col">Source Finding</th><th scope="col">RCA</th><th scope="col">Next step</th></tr></thead><tbody>{rows.map(({ ncr, finding, rcaCount: count }) => <tr><th scope="row"><a href={`/quality/ncr/${ncr.id}`}>{ncr.ncrNo}</a></th><td>{ncr.title}</td><td>{stateLabel(ncr.state)}</td><td>{finding ? <a href={`/quality/findings/${finding.id}`}>{finding.findingNo}</a> : ncr.findingId ? 'Not visible in your scope' : 'Not linked'}</td><td>{count ? <a href={`/quality/rca?ncrId=${encodeURIComponent(ncr.id)}`}>{count} analysis{count === 1 ? '' : 'es'}</a> : 'None visible'}</td><td>{ncr.state === 'OPEN' || ncr.state === 'UNDER_INVESTIGATION' ? <a href={`/quality/ncr/${ncr.id}`}>Review record and investigation</a> : ncr.state === 'RCA_IN_PROGRESS' ? <a href={`/quality/rca?ncrId=${encodeURIComponent(ncr.id)}`}>Review linked RCA</a> : ncr.state === 'CAPA_IN_PROGRESS' ? <a href={`/quality/capa?ncrId=${encodeURIComponent(ncr.id)}`}>Review linked CAPA</a> : ncr.state === 'READY_FOR_CLOSURE' ? 'Closure decision — QMS owner approval required' : <a href={`/quality/ncr/${ncr.id}`}>Open record</a>}</td></tr>)}</tbody></table></div> : <section class="empty"><h2>No NCR records in this view</h2><p>{state ? 'Clear the filter to see records in your authorized scope.' : 'No current NCR records are available in your authorized scope.'}</p>{state && <a href="/quality/ncr">Clear state filter</a>}</section>}
</AppLayout>
<style>
  .page-head{margin-bottom:var(--space-5)}h1{margin:.25rem 0}.eyebrow,.lede,.policy p{color:var(--text-muted)}.eyebrow{font-size:var(--font-size-xs);font-weight:700;letter-spacing:.12em}.policy{margin-bottom:var(--space-5);padding:var(--space-4);background:var(--surface-panel);border-inline-start:3px solid var(--color-accent-primary)}.policy h2{font-size:1rem;margin:0}.policy ul{padding-inline-start:1.25rem}.policy p{margin-bottom:0}.filters{display:flex;flex-wrap:wrap;align-items:end;gap:var(--space-3);margin-bottom:var(--space-5)}label{display:grid;gap:.35rem}select,button{min-height:var(--control-height);padding:.55rem .75rem;background:var(--surface-panel);border:1px solid var(--border-default);border-radius:var(--radius-sm);color:inherit;font:inherit}.table-wrap{overflow-x:auto;max-width:100%;border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg)}table{width:100%;min-width:900px;border-collapse:collapse;background:var(--surface-panel)}th,td{padding:.75rem;text-align:start;border-top:1px solid var(--color-border-subtle);vertical-align:top}th{font-weight:700}a{color:var(--color-accent-primary-hover)}.empty{padding:var(--space-5);background:var(--surface-panel);border:1px dashed var(--border-default)}@media(max-width:650px){.filters{display:grid;grid-template-columns:1fr}.filters button{width:max-content}}
</style>

---
// RT-NCR-002. This page exists so the declared create route never falls through
// to the NCR detail route (`/quality/ncr/[ncrId]`), which previously rendered a
// detail view for the literal id `new` (QC-100-FINAL-016 P2-4).
//
// Direct NCR creation is not enabled until the approved creation policy is
// available, so this page states that honestly instead of showing a form that
// cannot be submitted.
import AppLayout from '../../../ui/layouts/AppLayout.astro';
const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Fquality%2Fncr%2Fnew');
---
<AppLayout title="New NCR · Quality" locale="en" direction="ltr">
  <section class="page-head">
    <h1>New non-conformance report</h1>
    <p class="lede">Non-conformance records are opened from an authorized finding or inspection.</p>
  </section>
  <section class="panel" role="status">
    <h2>Direct creation is not available</h2>
    <p>
      The approved NCR creation policy is not in force yet, so this page does not offer a create
      form. Nothing was changed. Existing NCR records stay available in the register.
    </p>
    <p><strong>Decision owners:</strong> PD-15 Finding-to-NCR criteria — QC owner; PD-16 inspection FAIL handling — QC / inspection procedure owner.</p>
    <p class="links">
      <a href="/quality/ncr">Open the NCR register</a>
      <a href="/quality/findings">Open findings</a>
    </p>
  </section>
</AppLayout>
