import AppLayout from '../../../../ui/layouts/AppLayout.astro';
import { classifyReadFailure, providerUnavailableResponse } from '../../../../shared/errors/read-failure.js';
import StatusBadge from '../../../../ui/components/StatusBadge.astro';
import JourneyContextPanel from '../../../../ui/components/workflow/JourneyContextPanel.astro';
import { inspectionReadDependencies } from '../../../../modules/quarantine/application/dependencies.js';
import { stateLabel } from '../../../../shared/copy/ux-vocabulary.js';
const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
let inspection: Awaited<ReturnType<ReturnType<typeof inspectionReadDependencies>['get']['execute']>> | undefined;
try { inspection = await inspectionReadDependencies().get.execute({ actor, id: Astro.params.inspectionId ?? '' }); } catch (error) { if (classifyReadFailure(error) === 'UNAVAILABLE') return providerUnavailableResponse('Inspection details are temporarily unavailable', Astro.url.pathname + Astro.url.search); return Astro.redirect('/404'); }
if (!inspection) return Astro.redirect('/404');
const canReview = actor.permissions.some((permission) => permission.code === 'PERM-INSP-REVIEW' && permission.active !== false) && actor.permissions.some((permission) => permission.code === 'PERM-APR-REVIEW' && permission.active !== false);
// QC-100-FINAL-004 two-stage chain: the UNDER_REVIEW decision is the
// Supervisor stage approval (PERM-INSP-APPROVE only, no e-signature); the
// PENDING_QCM_APPROVAL decision is the QCM final approval (ceremony grant +
// binding e-signature + reauthentication).
const canStageApprove = actor.permissions.some((permission) => permission.code === 'PERM-INSP-APPROVE' && permission.active !== false);
const canFinalApprove = actor.permissions.some((permission) => permission.code === 'PERM-APR-APPROVE' && permission.active !== false) && actor.permissions.some((permission) => permission.code === 'PERM-ESIG-SIGN' && permission.active !== false);
const canReturn = actor.permissions.some((permission) => permission.code === 'PERM-INSP-RETURN' && permission.active !== false) && actor.permissions.some((permission) => permission.code === 'PERM-APR-RETURN' && permission.active !== false);
const canReject = actor.permissions.some((permission) => permission.code === 'PERM-INSP-REJECT' && permission.active !== false) && actor.permissions.some((permission) => permission.code === 'PERM-APR-REJECT' && permission.active !== false);
const atSupervisorStage = inspection.state === 'UNDER_REVIEW';
const atQcmStage = inspection.state === 'PENDING_QCM_APPROVAL';
// QC-100-FINAL-021: contextual guidance derived from the approved state — explains
// the two-stage approval without implying authority, and keeps PASS ≠ RELEASED
// explicit.
const stageNote = inspection.state === 'SUBMITTED'
  ? 'Stage 1 of 2 — waiting for a reviewer to begin review. No approval has been recorded yet.'
  : atSupervisorStage
    ? 'Stage 1 of 2 — Supervisor review. The approval here sends the report to QCM; it is not a final approval and does not release material.'
    : atQcmStage
      ? 'Stage 2 of 2 — QCM final approval with a binding e-signature and reauthentication. Admin cannot approve at either stage.'
      : inspection.state === 'APPROVED'
        ? 'Approval chain complete. This is an approval state only — PASS ≠ RELEASED; release stays a separate receiving action.'
        : inspection.state === 'RETURNED'
          ? 'Returned to the executor for correction. Resubmission resumes the same two-stage path.'
          : undefined;
const prereqs = inspection.state === 'SUBMITTED' || atSupervisorStage || atQcmStage
  ? [
      { label: 'final result recorded from the approved deterministic source gate', met: inspection.finalResult != null },
      { label: 'actor holds the permission required for the current stage', met: atSupervisorStage ? canStageApprove : atQcmStage ? canFinalApprove : canReview },
      { label: 'record version matches the loaded snapshot (stale intents are refused)', met: true },
    ]
  : undefined;
