  {!canReview ? <section class="readonly" role="alert"><strong>Review is not available.</strong><span>This workspace does not grant review authority to your account. The record remains readable; no action is implied by visibility.</span></section> : null}
  <JourneyContextPanel ownerDomain="Quarantine / Inspection" recordReference={`${inspection.inspectionNo} · version ${inspection.version.toString()}`} currentState={`${inspection.state} · Result ${inspection.finalResult ?? 'NOT_DETERMINED'}`} nextAction={inspection.state === 'SUBMITTED' && canReview ? 'Begin review' : inspection.state === 'UNDER_REVIEW' && canStageApprove ? 'Approve inspection — send to QCM' : inspection.state === 'PENDING_QCM_APPROVAL' && canFinalApprove ? 'QCM final approval' : inspection.state === 'SUBMITTED' || inspection.state === 'UNDER_REVIEW' || inspection.state === 'PENDING_QCM_APPROVAL' ? 'Review or return is unavailable' : undefined} nextOwner={inspection.state === 'SUBMITTED' || inspection.state === 'UNDER_REVIEW' ? 'Reviewer / approver' : inspection.state === 'RETURNED' ? 'Inspection executor' : undefined} whyUnavailable={!canReview && ['SUBMITTED', 'UNDER_REVIEW'].includes(inspection.state) ? 'permission: this account can read the report but lacks the required review action' : inspection.state === 'APPROVED' ? 'state: controlled approval is already complete' : undefined} stageNote={stageNote} prerequisites={prereqs} waitingOn={inspection.state === 'SUBMITTED' ? 'Reviewer' : inspection.state === 'UNDER_REVIEW' ? 'Review decision' : undefined} expectedEvent={inspection.state === 'SUBMITTED' ? 'Begin review' : inspection.state === 'UNDER_REVIEW' ? 'Approve, return, or reject' : undefined} controlledContext={`Receiving ${inspection.receiving.receivingNo} · approved template ${inspection.template.versionNo}`} evidenceSummary={`${inspection.results.length} recorded points; final controlled decision remains server-validated`} auditHref={`/audit?subjectType=INSPECTION_REPORT&subjectId=${encodeURIComponent(inspection.id)}`} relatedLinks={[{ label: inspection.receiving.receivingNo, href: `/quarantine/receiving/${inspection.receiving.receivingId}`, detail: 'Open source receiving item' }, { label: 'Inspection execution', href: `/quarantine/inspections/${inspection.id}/execute`, detail: 'Controlled observations' }]} />
  <div class="review-grid" data-inspection-id={inspection.id} data-version={inspection.version.toString()}><main><section class="panel"><div class="panel-head"><h2>Inspection snapshot</h2>{inspection.finalResult ? <StatusBadge status={inspection.finalResult} /> : <span class="muted">Result not determined</span>}</div><dl><div><dt>Workflow state</dt><dd>{stateLabel(inspection.state)}</dd></div><div><dt>Author / executor</dt><dd>Recorded in the controlled audit trail</dd></div><div><dt>Receiving item</dt><dd>{inspection.receiving.receivingNo} · {inspection.receiving.itemCode}</dd></div><div><dt>Template</dt><dd>{inspection.template.versionNo} · approved context</dd></div></dl></section><section class="panel"><h2>Measurements and criteria</h2><p class="muted">Review the preserved controlled context and evidence. Official outcome requires the approved deterministic source gate on the server.</p><div class="evidence-row"><span>Recorded points</span><strong>{inspection.results.length}</strong></div><div class="evidence-row"><span>Attached evidence</span><strong>{inspection.evidenceCount ?? 0}</strong></div></section><section class="panel"><h2>Previous submission / return history</h2><p class="muted">Prior controlled actions remain in audit history; no return or approval erases the submission path.</p></section></main><aside><section class="panel decision"><h2>Decision rail</h2><p class="muted">Opening review does not grant approval. Each action re-checks scope, current version, SoD, and permission.</p>{inspection.state === 'SUBMITTED' && canReview ? <button data-action="quarantine.reviewInspection" data-submit>Begin review</button> : null}{atSupervisorStage && canStageApprove ? <button class="controlled" data-action="quarantine.approveInspection" data-submit>Supervisor approval — send to QCM</button> : null}{atSupervisorStage && canReject ? <form method="post" data-action="quarantine.rejectInspection"><label for="inspection-reject-reason">Reject reason<textarea id="inspection-reject-reason" name="reason" required></textarea></label><button class="danger" type="submit" data-submit>Reject inspection</button><p data-result role="status" tabindex="-1" class="action-status"></p></form> : null}{atQcmStage && canFinalApprove ? <form method="post" data-action="quarantine.finalApproveInspection"><label for="inspection-final-approval-password">Reauthentication password (final approval signature)<input id="inspection-final-approval-password" name="reauthenticationSecret" type="password" autocomplete="current-password" required></input></label><button class="controlled" type="submit" data-submit>QCM final approval — approve and lock</button><p data-result role="status" tabindex="-1" class="action-status"></p></form> : null}{atQcmStage && canReject ? <form method="post" data-action="quarantine.rejectInspection"><label for="inspection-qcm-reject-reason">QCM reject reason<textarea id="inspection-qcm-reject-reason" name="reason" required></textarea></label><button class="danger" type="submit" data-submit>Reject at QCM stage</button><p data-result role="status" tabindex="-1" class="action-status"></p></form> : null}{['SUBMITTED', 'UNDER_REVIEW', 'PENDING_QCM_APPROVAL'].includes(inspection.state) ? canReturn ? <form method="post" data-action="quarantine.returnInspection"><label for="inspection-return-reason">Return reason<textarea id="inspection-return-reason" name="reason" required></textarea></label><button class="secondary" type="submit" data-submit>Return for correction</button><p data-result role="status" tabindex="-1" class="action-status"></p></form> : <p class="note">Return for correction is unavailable because your account lacks the review-return permissions. The record is still readable.</p> : null}<p class="note">Approval remains blocked when source/policy evidence is not approved. PASS is never a release command.</p></section></aside></div>
</AppLayout>
<script>
  import { actions } from 'astro:actions';
  const context = document.querySelector<HTMLElement>('[data-inspection-id]');
  const inspectionId = context?.dataset.inspectionId ?? '';
  const version = context?.dataset.version ?? '0';
  const run = async (button: HTMLElement, label: string, call: () => Promise<{ error?: unknown }>) => {
    const btn = button as HTMLButtonElement;
    if (btn.disabled || button.closest('[aria-busy="true"]')) return;
    const scope = button.closest('aside, section') as HTMLElement | null;
    let output = scope?.querySelector?.<HTMLElement>('[data-result]') ?? document.querySelector<HTMLElement>('[data-result]');
    btn.disabled = true;
    scope?.setAttribute('aria-busy', 'true');
    if (output) output.textContent = label;
    try {
      const result = await call();
      if (!result.error) { window.location.reload(); return; }
      if (output) { output.textContent = 'The review action was not applied. Refresh and review the current state and version.'; (output as HTMLElement).focus?.(); }
    } catch {
      if (output) { output.textContent = 'The service did not confirm the result. Refresh the inspection and its history before deciding whether to try again.'; (output as HTMLElement).focus?.(); }
    } finally { btn.disabled = false; scope?.removeAttribute('aria-busy'); }
  };
  document.querySelectorAll<HTMLElement>('[data-action="quarantine.reviewInspection"]').forEach((button) => button.addEventListener('click', () => void run(button, 'Starting review…', () => actions.quarantine.reviewInspection({ id: inspectionId, expectedVersion: BigInt(version) }))));
  document.querySelectorAll<HTMLElement>('[data-action="quarantine.approveInspection"]').forEach((button) => button.addEventListener('click', () => void run(button, 'Applying Supervisor stage approval…', () => actions.quarantine.approveInspection({ id: inspectionId, expectedVersion: BigInt(version) }))));
  // QC-100-FINAL-004: the QCM final approval carries the binding e-signature,
  // so the reauthentication password travels only in the request body and is
  // never logged, stored, or echoed. The form clears it after each attempt.
  document.querySelectorAll<HTMLFormElement>('[data-action="quarantine.finalApproveInspection"]').forEach((form) => form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (form.getAttribute('aria-busy') === 'true') return;
    const submit = form.querySelector<HTMLButtonElement>('[data-submit], button[type="submit"]');
    const output = form.querySelector<HTMLElement>('[data-result]');
    form.setAttribute('aria-busy', 'true');
    if (submit) submit.disabled = true;
    if (output) output.textContent = 'Applying QCM final approval with signature…';
    try {
      const reauthenticationSecret = String(new FormData(form).get('reauthenticationSecret') ?? '');
      const result = await actions.quarantine.finalApproveInspection({ id: inspectionId, expectedVersion: BigInt(version), reauthenticationSecret });
      form.reset();
      if (!result.error) { window.location.reload(); return; }
      if (output) { output.textContent = 'The final approval was not applied. Verify your reauthentication password and the current version, then try again.'; output.focus?.(); }
    } catch {
      form.reset();
      if (output) { output.textContent = 'The service did not confirm the result. Refresh the inspection and its history before deciding whether to try again.'; output.focus?.(); }
    } finally { form.removeAttribute('aria-busy'); if (submit) submit.disabled = false; }
  }));
  document.querySelectorAll<HTMLFormElement>('[data-action="quarantine.returnInspection"]').forEach((form) => form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (form.getAttribute('aria-busy') === 'true') return;
    const submit = form.querySelector<HTMLButtonElement>('[data-submit], button[type="submit"]');
    const output = form.querySelector<HTMLElement>('[data-result]');
    form.setAttribute('aria-busy', 'true');
    if (submit) submit.disabled = true;
    if (output) output.textContent = 'Returning for correction…';
    try {
      const reason = new FormData(form).get('reason');
      const result = await actions.quarantine.returnInspection({ id: inspectionId, expectedVersion: BigInt(version), reason: String(reason ?? '') });
      if (!result.error) { window.location.reload(); return; }
      if (output) { output.textContent = 'Return was not applied. Refresh and review the current state before trying again.'; output.focus?.(); }
    } catch {
      if (output) { output.textContent = 'The service did not confirm the result. Your reason is kept. Refresh the record and its history before deciding whether to try again.'; output.focus?.(); }
    } finally { form.removeAttribute('aria-busy'); if (submit) submit.disabled = false; }
  }));
  document.querySelectorAll<HTMLFormElement>('[data-action="quarantine.rejectInspection"]').forEach((form) => form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (form.getAttribute('aria-busy') === 'true') return;
    const submit = form.querySelector<HTMLButtonElement>('[data-submit], button[type="submit"]');
    const output = form.querySelector<HTMLElement>('[data-result]');
    form.setAttribute('aria-busy', 'true');
    if (submit) submit.disabled = true;
    if (output) output.textContent = 'Rejecting inspection…';
    try {
      const reason = new FormData(form).get('reason');
      const result = await actions.quarantine.rejectInspection({ id: inspectionId, expectedVersion: BigInt(version), reason: String(reason ?? '') });
      if (!result.error) { window.location.reload(); return; }
      if (output) { output.textContent = 'Rejection was not applied. Refresh and review the current state before trying again.'; output.focus?.(); }
    } catch {
      if (output) { output.textContent = 'The service did not confirm the result. Your reason is kept. Refresh the record and its history before deciding whether to try again.'; output.focus?.(); }
    } finally { form.removeAttribute('aria-busy'); if (submit) submit.disabled = false; }
  }));
</script>
