  .crumb{display:flex;gap:.5rem;margin-bottom:var(--space-5);color:var(--text-muted);font-size:.8rem}.crumb a{color:var(--color-accent-primary-hover)}.head,.panel-head{display:flex;justify-content:space-between;align-items:flex-start;gap:var(--space-5)}.head{margin-bottom:var(--space-5)}h1{margin:.25rem 0 .4rem}.eyebrow{margin:0;color:var(--text-muted);font-size:.7rem;letter-spacing:.12em;font-weight:700}.lede,.muted,.version,.readonly span{color:var(--text-muted);font-size:.84rem}.version{padding:.5rem .75rem;border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm)}.readonly{display:grid;gap:.25rem;margin-bottom:var(--space-5);padding:var(--space-4);border-inline-start:3px solid var(--status-warning);background:var(--surface-panel)}.review-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:var(--space-5)}main,aside{display:grid;gap:var(--space-5);align-content:start}.panel{padding:var(--space-5);background:var(--surface-panel);border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg)}h2{margin:0;font-size:1rem}dl{display:grid;grid-template-columns:repeat(2,1fr);gap:var(--space-4);margin:var(--space-5) 0 0}dt{color:var(--text-muted);font-size:.75rem}dd{margin:.3rem 0 0;font-weight:600}.evidence-row{display:flex;justify-content:space-between;margin-top:var(--space-5);padding:var(--space-4);background:var(--surface-raised);border-radius:var(--radius-md)}.action-status{margin:.5rem 0;color:var(--text-secondary);font-size:.85rem;min-height:1.25rem}button{width:100%;min-height:var(--control-height);padding:.6rem .8rem;border:1px solid var(--color-accent-primary);border-radius:var(--radius-sm);background:var(--color-accent-primary);color:#fff;font:inherit;font-weight:700}.controlled{border-color:var(--status-review);background:var(--status-review-bg);color:var(--text-primary)}.secondary{border-color:var(--border-default);background:var(--surface-raised);color:var(--text-primary)}.danger{border-color:var(--status-danger);background:var(--status-danger-bg);color:var(--status-danger)}form{display:grid;gap:.6rem;margin-top:var(--space-3)}label{display:grid;gap:.4rem;color:var(--text-secondary);font-size:.8rem}textarea{min-height:6rem;padding:.6rem;background:var(--surface-raised);border:1px solid var(--border-default);border-radius:var(--radius-sm);color:inherit;font:inherit}.note{padding-top:var(--space-4);border-top:1px solid var(--color-border-subtle);line-height:1.5}@media(max-width:820px){.review-grid{grid-template-columns:1fr}}@media(max-width:560px){.head{display:grid}dl{grid-template-columns:1fr}.panel{padding:var(--space-4)}}
