  <div class="layout"><main><section class="panel"><h2>Receiving details</h2><dl><div><dt>Supplier</dt><dd>{item.supplier}</dd></div><div><dt>Document</dt><dd>{item.docNo}</dd></div><div><dt>Purchase order</dt><dd>{item.purchaseOrderNo ?? 'Not supplied'}</dd></div><div><dt>Quantity</dt><dd>{item.quantityUnit ? `${item.qty} ${item.quantityUnit}` : `${item.qty} — unit not recorded`}</dd></div><div><dt>Received</dt><dd>{item.receivingDate.toLocaleDateString('en-SA', { timeZone: 'Asia/Riyadh' })}</dd></div><div><dt>Expiry</dt><dd>{item.expiryDate?.toLocaleDateString('en-SA', { timeZone: 'Asia/Riyadh' }) ?? 'Not supplied'}</dd></div><div><dt>Evidence links</dt><dd>{item.evidenceCount ?? 0}</dd></div>{item.sourceReference ? <div><dt>Imported from</dt><dd>{item.sourceSystem ?? 'legacy source'} · {item.sourceReference}</dd></div> : null}</dl></section><section class="panel"><div class="panel-head"><h2>Inspection</h2><a href="/quarantine/inspections">Inspection register</a></div><p class="muted">Inspection execution and approval are separate controlled workflows. No result is accepted from this page.</p>{item.linkedInspections?.length ? <ul class="linked">{item.linkedInspections.map((report) => <li><a href={`/quarantine/inspections/${report.id}`}>{report.inspectionNo}</a><span>{report.state}{report.finalResult ? ` · ${report.finalResult}` : ''}</span></li>)}</ul> : <p class="muted">No inspection report has been created from this item yet.</p>}</section>{canCreateInspection && (<section class="panel"><div class="panel-head"><h2>Create an inspection</h2></div>{inspectionStateReason ? <p class="muted">{inspectionStateReason}</p> : templateOptionsUnavailable ? <p class="muted">Approved templates are unavailable, so an inspection cannot be started. Try reloading.</p> : noMappedTemplate ? <p class="muted">No approved inspection template is available for this item. Map the item to an approved template first — the mapping is a separate controlled workflow.</p> : (<form method="post"><input type="hidden" name="intent" value="create-inspection" /><div class="form-fields">{uniqueTemplate ? (<><input type="hidden" name="templateVersionId" value={uniqueTemplate.templateVersionId} /><p class="muted">Resolved template: <strong>{uniqueTemplate.name}</strong> · v{uniqueTemplate.versionNo} ({uniqueTemplate.templateCode}) — selected automatically from the approved item mapping.</p></>) : (<label for="templateVersionId">Inspection template<span class="hint">More than one approved template is mapped to this item; choose the one your approved source requires.</span><select id="templateVersionId" name="templateVersionId" required>{mappedCandidates.map((template) => (<option value={template.templateVersionId}>{template.name} · v{template.versionNo}</option>))}</select></label>)}<label for="inspectionNo">Inspection number<input id="inspectionNo" name="inspectionNo" required maxlength="80" placeholder="From your approved source" value={retained('inspectionNo', '', 'create-inspection')} /><span class="hint">Registered from the approved source; the system does not invent it. Item, lot, supplier and quantity arrive prefilled.</span></label></div><button type="submit" data-submit>Create inspection</button></form>)}</section>)}<section class="panel"><h2>History</h2>{item.history?.length ? <ol class="history">{item.history.map((event) => <li><strong>{event.action}</strong><span>{transitionLabel(event.oldState, event.newState)} · {event.occurredAt.toLocaleString('en-SA', { timeZone: 'Asia/Riyadh' })}</span>{event.reason ? <small>{event.reason}</small> : null}</li>)}</ol> : <p class="muted">No controlled transitions recorded yet.</p>}</section></main><aside class="rail"><section class="panel"><h2>Primary actions</h2><div class="actions">{item.workflowState === 'READY_FOR_INSPECTION' ? <button data-action="quarantine.transitionReceiving" data-transition="START_INSPECTION" data-submit>Start inspection</button> : null}{canRelease && item.workflowState === 'RELEASE_PENDING' ? <button class="controlled" data-action="quarantine.releaseReceiving" data-submit>Release item</button> : null}<a class="secondary link-button" href={`/quarantine/receiving/${item.id}`}>Refresh latest</a></div>{canHold && !['RELEASED','EXPIRED','CANCELLED'].includes(item.workflowState) ? <form method="post" class="stacked"><input type="hidden" name="intent" value="hold" /><label for="hold-reason">HOLD reason<input id="hold-reason" name="reason" required maxlength="500" value={retained('reason', '', 'hold')} aria-invalid={invalid('reason')} aria-describedby={describedBy('reason')} /></label>{failure?.fieldErrors.reason && (<p class="field-error" id="reason-error">{failure.fieldErrors.reason}</p>)}<button class="secondary" type="submit" data-submit>Place on HOLD</button></form> : null}{canEdit && item.workflowState === 'PENDING' && !['RELEASED','CANCELLED'].includes(item.workflowState) ? <form method="post" class="stacked"><input type="hidden" name="intent" value="void" /><label for="void-reason">Void reason<input id="void-reason" name="reason" required maxlength="500" value={retained('reason', '', 'void')} aria-invalid={invalid('reason')} aria-describedby={describedBy('reason')} /></label><button class="secondary" type="submit" data-transition="CANCEL" data-submit>Void this receiving item</button></form> : null}{canRelease && item.inspectionResult === 'PASS' && !item.releaseSystem ? <p class="note">PASS is recorded, but this item is not released. Release remains a separate policy-controlled action.</p> : null}</section>{canEdit && correctable ? (<section class="panel"><h2>Correct this record</h2>{correcting ? (<form method="post" class="stacked"><input type="hidden" name="intent" value="correct" /><div class="form-fields"><label for="correct-supplier">Supplier<input id="correct-supplier" name="supplier" required value={retained('supplier', String(item.supplier))} /></label><label for="correct-docNo">Document number<input id="correct-docNo" name="docNo" required value={retained('docNo', String(item.docNo))} /></label><label for="correct-itemCode">Item code<input id="correct-itemCode" name="itemCode" required value={retained('itemCode', String(item.itemCode))} /></label><label for="correct-description">Description<input id="correct-description" name="description" required value={retained('description', String(item.description))} /></label><label for="correct-lot">Lot / batch<input id="correct-lot" name="lot" required value={retained('lot', String(item.lot))} /></label><label for="correct-qty">Quantity<input id="correct-qty" name="qty" type="number" min="0" step="any" required value={retained('qty', String(item.qty))} /></label><label for="correct-receivingDate">Receiving date<input id="correct-receivingDate" name="receivingDate" type="date" required value={retained('receivingDate', day(item.receivingDate))} /></label><label for="correct-expiryDate">Expiry date<input id="correct-expiryDate" name="expiryDate" type="date" value={retained('expiryDate', day(item.expiryDate))} /></label><label for="correct-reason">Correction reason<textarea id="correct-reason" name="reason" required maxlength="500" aria-invalid={invalid('reason')} aria-describedby={describedBy('reason')}>{retained('reason', '', 'correct')}</textarea></label></div><button type="submit" data-submit>Apply correction</button></form>) : (<p class="muted">Corrections are recorded with a reason and an audit entry. Identity changes after inspection starts need the disposition path instead.</p><button class="secondary" data-show-correct type="button">Start correction</button>)}</section>) : null}<section class="panel"><h2>Context</h2><dl class="compact"><div><dt>Created by</dt><dd>{item.createdBy}</dd></div><div><dt>Last updated</dt><dd>{item.updatedAt.toLocaleString('en-SA', { timeZone: 'Asia/Riyadh' })}</dd></div><div><dt>Version</dt><dd>{item.version.toString()}</dd></div></dl></section></aside></div>
</AppLayout>
<script>
  import { actions } from 'astro:actions';
  // The correction form starts collapsed so the record stays readable; the
  // POST baseline still works with JavaScript disabled (the form renders when a
  // correction attempt failed).
  document.querySelector<HTMLButtonElement>('[data-show-correct]')?.addEventListener('click', () => {
    const panel = document.querySelector<HTMLElement>('[data-show-correct]')?.closest('section');
    const hiddenForm = panel?.querySelector<HTMLFormElement>('form');
    if (hiddenForm) hiddenForm.hidden = false;
  });
  const context = document.querySelector<HTMLElement>('[data-record-id]');
  const itemId = context?.dataset.recordId ?? '';
  const version = context?.dataset.version ?? '0';
  const output = document.querySelector<HTMLElement>('[data-result]');
  const setBusy = (button: HTMLButtonElement | null, busy: boolean, text?: string) => {
    const region = button?.closest('section, div') ?? document.body;
    if (busy) region.setAttribute('aria-busy', 'true');
    else region.removeAttribute('aria-busy');
    if (button) button.disabled = busy;
    if (busy && text && output) output.textContent = text;
  };
  const fail = (button: HTMLButtonElement | null, message: string) => {
    setBusy(button, false);
    if (output) { output.textContent = message; output.focus?.(); }
  };
  document.querySelectorAll<HTMLButtonElement>('[data-action]').forEach((button) => button.addEventListener('click', async () => {
    if (button.disabled || button.closest('[aria-busy="true"]')) return;
    const action = button.dataset.action;
    setBusy(button, true, 'Applying the controlled action…');
    try {
      const next = action === 'quarantine.holdReceiving'
        ? await actions.quarantine.holdReceiving({ id: itemId, expectedVersion: BigInt(version), reason: 'HOLD requested from the record workspace.' })
        : action === 'quarantine.releaseReceiving'
          ? await actions.quarantine.releaseReceiving({ id: itemId, expectedVersion: BigInt(version) })
          : await actions.quarantine.transitionReceiving({ id: itemId, expectedVersion: BigInt(version), action: (button.dataset.transition ?? 'START_INSPECTION') as 'START_INSPECTION' });
      if (!next.error) { window.location.reload(); return; }
      fail(button, 'The controlled action was not applied. Refresh and review the current state and version before trying again.');
    } catch {
      fail(button, 'The service did not confirm the result. Refresh the receiving record and its history before deciding whether to try again.');
    }
  }));
</script>
