import AppLayout from '../../../ui/layouts/AppLayout.astro';
import ProviderUnavailableState from '../../../ui/components/feedback/ProviderUnavailableState.astro';
import AppliedFilters from '../../../ui/components/data/AppliedFilters.astro';
import FilterBar from '../../../ui/components/data/FilterBar.astro';
import { receivingReadDependencies } from '../../../modules/quarantine/application/dependencies.js';
import {
  parseReceivingFilters,
} from '../../../modules/quarantine/receiving/application/receiving-filters.js';
import {
  RECEIVING_INSPECTION_STATUSES,
  RECEIVING_QUARANTINE_STATUSES,
} from '../../../modules/quarantine/receiving/application/presentation.js';
import { RECEIVING_WORKFLOW_STATES, INSPECTION_RESULTS, deriveQuarantineStatus } from '../../../modules/quarantine/receiving/application/presentation.js';
import { stateLabel, releaseStateLabel, copy } from '../../../shared/copy/ux-vocabulary.js';
const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Fquarantine%2Freceiving');

// One parser owns the filter contract: every parameter is either applied by the
// server or reported below — never silently ignored.
const { filters, rejected } = parseReceivingFilters(Astro.url.searchParams);
const state = filters.state;
const inspectionResult = filters.inspectionResult;
const releaseState = filters.releaseState;
const ownership = filters.ownership;
const receivedOn = filters.receivedOn;
const inspectionStatus = filters.inspectionStatus;
const quarantine = filters.quarantine;

/** One link per filter that drops only that filter and keeps the rest. */
const chipHref = (drop: string) => {
  const next = new URLSearchParams(Astro.url.searchParams);
  next.delete(drop);
  const search = next.toString();
  return `/quarantine/receiving${search ? `?${search}` : ''}`;
};
const appliedFilters = [
  filters.q && { label: 'Search', value: filters.q, href: chipHref('q') },
  filters.itemCode && { label: 'Item code', value: filters.itemCode, href: chipHref('itemCode') },
  filters.lot && { label: 'Lot', value: filters.lot, href: chipHref('lot') },
  filters.supplier && { label: 'Supplier', value: filters.supplier, href: chipHref('supplier') },
  filters.purchaseOrderNo && {
    label: 'Purchase order',
    value: filters.purchaseOrderNo,
    href: chipHref('purchaseOrderNo'),
  },
  state && { label: 'Workflow state', value: stateLabel(state), href: chipHref('state') },
  inspectionResult && {
    label: 'Inspection result',
    value: stateLabel(inspectionResult),
    href: chipHref('inspectionResult'),
  },
  inspectionStatus && {
    label: 'Inspection status',
    value: stateLabel(inspectionStatus),
    href: chipHref('inspectionStatus'),
  },
  quarantine && {
    label: 'Quarantine',
    value: stateLabel(quarantine),
    href: chipHref('quarantine'),
  },
  releaseState && {
    label: 'Release state',
    value: stateLabel(releaseState),
    href: chipHref('releaseState'),
  },
  ownership && { label: 'Ownership', value: 'Only mine', href: chipHref('ownership') },
  receivedOn && { label: 'Received on', value: 'Today', href: chipHref('receivedOn') },
  filters.receivedFrom && {
    label: 'Received from',
    value: filters.receivedFrom,
    href: chipHref('receivedFrom'),
  },
  filters.receivedTo && { label: 'Received to', value: filters.receivedTo, href: chipHref('receivedTo') },
  filters.expiryFrom && { label: 'Expiry from', value: filters.expiryFrom, href: chipHref('expiryFrom') },
  filters.expiryTo && { label: 'Expiry to', value: filters.expiryTo, href: chipHref('expiryTo') },
].filter((chip): chip is { label: string; value: string; href: string } => Boolean(chip));
const hasFilters = appliedFilters.length > 0;
const rejectedNotice = rejected
  .map((entry) =>
    entry.reason === 'UNKNOWN_PARAMETER'
      ? `“${entry.parameter}” is not a filter this register supports`
      : `“${entry.parameter}” does not accept the value “${entry.value}”`,
  )
  .join(' and ');

let items: Awaited<ReturnType<ReturnType<typeof receivingReadDependencies>['list']['execute']>> = [];
let providerUnavailable = false;
try {
  items = await receivingReadDependencies().list.execute({ actor, ...filters });
} catch {
  providerUnavailable = true;
}
const day = (value: Date | undefined): string =>
  value ? value.toISOString().slice(0, 10) : '—';
const quantity = (item: (typeof items)[number]): string =>
  item.quantityUnit ? `${item.qty} ${item.quantityUnit}` : `${item.qty} (unit not recorded)`;
---

<AppLayout title="Receiving Items · Quarantine" locale="en" direction="ltr">
  <section class="page-head">
    <div>
      <p class="eyebrow">Operations</p>
      <h1>Receiving items</h1>
      <p class="lede">
        Material received into quarantine, with its inspection result and release state kept separate.
      </p>
    </div>
    <a class="button" href="/quarantine/receiving/new">Create receiving item</a>
  </section>
  {rejectedNotice && (
    <p class="rejected" role="status">
      Not applied: {rejectedNotice}. Nothing was filtered by these values.
    </p>
  )}
  <FilterBar clearHref={hasFilters ? '/quarantine/receiving' : undefined}>
    <label for="q">Search<input id="q" name="q" type="search" value={filters.q ?? ''} maxlength="200" placeholder="Receiving number, item, lot, supplier, PO" /></label>
    <label for="itemCode">Item code<input id="itemCode" name="itemCode" value={filters.itemCode ?? ''} maxlength="120" /></label>
    <label for="lot">Lot<input id="lot" name="lot" value={filters.lot ?? ''} maxlength="120" /></label>
    <label for="supplier">Supplier<input id="supplier" name="supplier" value={filters.supplier ?? ''} maxlength="200" /></label>
    <label for="purchaseOrderNo">Purchase order<input id="purchaseOrderNo" name="purchaseOrderNo" value={filters.purchaseOrderNo ?? ''} maxlength="120" /></label>
    <label for="state">Workflow state<select id="state" name="state">
        <option value="">All states</option>
        {RECEIVING_WORKFLOW_STATES.map((value) => (
          <option value={value} selected={state === value}>
            {stateLabel(value)}
          </option>
        ))}
      </select></label>
    <label for="inspectionStatus">Inspection status<select id="inspectionStatus" name="inspectionStatus">
        <option value="">All statuses</option>
        {RECEIVING_INSPECTION_STATUSES.map((value) => (
          <option value={value} selected={inspectionStatus === value}>
            {stateLabel(value)}
          </option>
        ))}
      </select></label>
    <label for="quarantine">Quarantine status<select id="quarantine" name="quarantine">
        <option value="">All statuses</option>
        {RECEIVING_QUARANTINE_STATUSES.map((value) => (
          <option value={value} selected={quarantine === value}>
            {stateLabel(value)}
          </option>
        ))}
      </select></label>
    <label for="inspectionResult">Inspection result<select id="inspectionResult" name="inspectionResult">
        <option value="">All results</option>
        {INSPECTION_RESULTS.map((value) => (
          <option value={value} selected={inspectionResult === value}>
            {stateLabel(value)}
          </option>
        ))}
      </select></label>
    <label for="releaseState">Release state<select id="releaseState" name="releaseState">
        <option value="">Any release state</option>
        <option value="NOT_RELEASED" selected={releaseState === 'NOT_RELEASED'}>{releaseStateLabel(false)}</option>
        <option value="RELEASE_PENDING" selected={releaseState === 'RELEASE_PENDING'}>{stateLabel('RELEASE_PENDING')}</option>
        <option value="RELEASED" selected={releaseState === 'RELEASED'}>{releaseStateLabel(true)}</option>
      </select></label>
    <label for="receivedFrom">Received from<input id="receivedFrom" name="receivedFrom" type="date" value={filters.receivedFrom ?? ''} /></label>
    <label for="receivedTo">Received to<input id="receivedTo" name="receivedTo" type="date" value={filters.receivedTo ?? ''} /></label>
    <label for="expiryFrom">Expiry from<input id="expiryFrom" name="expiryFrom" type="date" value={filters.expiryFrom ?? ''} /></label>
    <label for="expiryTo">Expiry to<input id="expiryTo" name="expiryTo" type="date" value={filters.expiryTo ?? ''} /></label>
    <label for="ownership">Ownership<select id="ownership" name="ownership">
        <option value="">All records</option>
        <option value="mine" selected={ownership === 'mine'}>Only mine</option>
      </select></label>
    <label for="receivedOn">Received on<select id="receivedOn" name="receivedOn">
        <option value="">Any date</option>
        <option value="today" selected={receivedOn === 'today'}>Today</option>
      </select></label>
  </FilterBar>
  <AppliedFilters
    filters={appliedFilters}
    clearHref={hasFilters ? '/quarantine/receiving' : undefined}
    note="Showing every receiving item in your authorized scope."
  />
  {
    providerUnavailable ? (
      <ProviderUnavailableState title="Receiving data is temporarily unavailable" />
    ) : items.length ? (
      <div class="table-wrap">
        <table>
          <caption>
            {items.length} receiving item{items.length === 1 ? '' : 's'}
            {hasFilters ? ' matching the current filters' : ''}
          </caption>
          <thead>
            <tr>
              <th scope="col">Receiving number</th>
              <th scope="col">Item code</th>
              <th scope="col">Description</th>
              <th scope="col">Lot</th>
              <th scope="col">Quantity</th>
              <th scope="col">Received</th>
              <th scope="col">Expiry</th>
              <th scope="col">Inspection</th>
              <th scope="col">Quarantine</th>
              <th scope="col">Release</th>
              <th scope="col">Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map((item) => (
              <tr>
                <th scope="row">
                  <a href={`/quarantine/receiving/${item.id}`}>{item.receivingNo}</a>
                </th>
                <td>{item.itemCode}</td>
                <td>{item.description}</td>
                <td>{item.lot}</td>
                <td>{quantity(item)}</td>
                <td>{day(item.receivingDate)}</td>
                <td>{item.expiryDate ? day(item.expiryDate) : '—'}</td>
                <td>
                  <span class:list={['result', item.inspectionResult.toLowerCase()]}>
                    {stateLabel(item.inspectionResult)}
                  </span>
                </td>
                <td>
                  <span class:list={['quarantine', { danger: deriveQuarantineStatus(item) === 'HOLD' }]}>
                    {stateLabel(deriveQuarantineStatus(item))}
                  </span>
                </td>
                <td>
                  <span class:list={['release', { yes: item.releaseSystem }]}>
                    {releaseStateLabel(item.releaseSystem)}
                  </span>
                </td>
                <td>
                  <a class="row-action" href={`/quarantine/receiving/${item.id}`}>Open</a>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    ) : (
      <section class="empty-state">
        <h2>{hasFilters ? 'No receiving items match these filters' : 'No receiving items yet'}</h2>
        <p>
          {hasFilters
            ? 'Nothing in your authorized scope matches the filters above. Remove a filter to widen the search.'
            : copy.states.noRecords + ' Create the first one to start quarantine tracking.'}
        </p>
        {hasFilters ? (
          <a href="/quarantine/receiving">Clear all filters</a>
        ) : (
          <a href="/quarantine/receiving/new">Create a receiving item</a>
        )}
      </section>
    )
  }
</AppLayout>
<style>
  .page-head{display:flex;justify-content:space-between;align-items:flex-start;gap:var(--space-5);margin-bottom:var(--space-6)}h1{margin:.25rem 0 .4rem}.eyebrow{margin:0;color:var(--text-muted);font-size:.75rem;letter-spacing:.12em;font-weight:700}.lede,.empty-state p{color:var(--text-muted);font-size:.85rem}.button{display:inline-flex;align-items:center;justify-content:center;min-height:var(--control-height);padding-inline:1rem;border:1px solid var(--color-accent-primary);border-radius:var(--radius-sm);background:var(--color-accent-primary);color:var(--color-text-inverse);font-weight:700;text-decoration:none}.button.secondary{background:var(--surface-raised);border-color:var(--border-default);color:var(--text-primary)}.filters{display:flex;align-items:end;gap:var(--space-3);margin-bottom:var(--space-4);flex-wrap:wrap}label{display:grid;gap:.35rem;color:var(--text-secondary);font-size:.8rem}select{min-height:var(--control-height);padding-inline:.7rem;background:var(--surface-panel);border:1px solid var(--border-default);border-radius:var(--radius-sm);color:inherit}.table-wrap{overflow-x:auto;border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg)}table{width:100%;min-width:880px;border-collapse:collapse;background:var(--surface-panel)}caption{text-align:start;padding:var(--space-4);color:var(--text-muted);font-size:.8rem}th,td{padding:.85rem;border-top:1px solid var(--color-border-subtle);text-align:start;font-size:.8rem}th{font-weight:700}a{color:var(--color-accent-primary-hover)}.state-pill,.result,.release{display:inline-flex;padding:.25rem .5rem;border-radius:999px;border:1px solid var(--color-border-subtle);font-size:.75rem;font-weight:700}.result.pass{color:var(--status-pass);background:var(--status-pass-bg)}.result.fail,.result.hold{color:var(--status-danger);background:var(--status-danger-bg)}.result.not_started{color:var(--text-muted)}.release{color:var(--text-muted)}.release.yes{color:var(--status-released);background:var(--status-released-bg);border-color:var(--status-released)}.quarantine{display:inline-flex;padding:.25rem .5rem;border-radius:999px;border:1px solid var(--color-border-subtle);font-size:.75rem;font-weight:700;color:var(--text-muted)}.quarantine.danger{color:var(--status-danger);background:var(--status-danger-bg);border-color:var(--status-danger)}.rejected{margin:0 0 var(--space-4);padding:var(--space-3) var(--space-4);border-inline-start:3px solid var(--status-warning);background:var(--surface-panel);color:var(--text-secondary);font-size:var(--font-size-xs)}.row-action{font-weight:700}.empty-state{padding:3rem 1.5rem;text-align:center;background:var(--surface-panel);border:1px dashed var(--color-border-strong);border-radius:var(--radius-lg)}.empty-state h2{margin:.5rem 0}.empty-state a{font-weight:700}@media(max-width:650px){.page-head,.filters{display:grid}.button{width:max-content}}
</style>

---
import AppLayout from '../../../ui/layouts/AppLayout.astro';
import FormErrorSummary from '../../../ui/components/FormErrorSummary.astro';
import { actions } from 'astro:actions';
import {
  detailHref,
  extractDetailId,
  field,
  toFormFailure,
  type FormFailure,
} from '../../../ui/forms/mutation-post.js';
import {
  RECEIVING_QUANTITY_UNITS,
} from '../../../modules/quarantine/receiving/application/presentation.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Fquarantine%2Freceiving%2Fnew');
const canCreate = actor.permissions.some((permission) => permission.code === 'PERM-QUAR-CREATE');

const LIST_HREF = '/quarantine/receiving';
const REQUIRED_FIELDS = [
  { name: 'receivingNo', label: 'Receiving number' },
  { name: 'supplier', label: 'Supplier' },
  { name: 'docNo', label: 'Document number' },
  { name: 'itemCode', label: 'Item code' },
  { name: 'lot', label: 'Lot / batch' },
  { name: 'description', label: 'Description' },
  { name: 'qty', label: 'Quantity' },
  { name: 'quantityUnit', label: 'Quantity unit' },
  { name: 'receivingDate', label: 'Receiving date' },
] as const;

let values = { receivingNo: '', supplier: '', docNo: '', itemCode: '', lot: '', description: '', qty: '', quantityUnit: '', purchaseOrderNo: '', receivingDate: '', expiryDate: '' };
let failure: FormFailure | null = null;

// POST baseline (F-05): without JavaScript the form performs a real POST to
// this page. The same Astro Action — with the same server-side
// reauthorization — runs via Astro.callAction. No business payload enters
// the URL: input travels in the POST body, success redirects (303) to the
// new record only.
if (Astro.request.method === 'POST' && canCreate) {
  const formData = await Astro.request.formData();
  const receivingRaw = field(formData, 'receivingDate');
  const expiryRaw = field(formData, 'expiryDate');
  values = {
    receivingNo: field(formData, 'receivingNo'),
    supplier: field(formData, 'supplier'),
    docNo: field(formData, 'docNo'),
    itemCode: field(formData, 'itemCode'),
    lot: field(formData, 'lot'),
    description: field(formData, 'description'),
    qty: field(formData, 'qty'),
    quantityUnit: field(formData, 'quantityUnit'),
    purchaseOrderNo: field(formData, 'purchaseOrderNo'),
    receivingDate: receivingRaw,
    expiryDate: expiryRaw,
  };
  try {
    const data = await Astro.callAction(actions.quarantine.createReceiving, {
      receivingNo: values.receivingNo,
      supplier: values.supplier,
      docNo: values.docNo,
      itemCode: values.itemCode,
      description: values.description,
      lot: values.lot,
      qty: values.qty,
      quantityUnit: values.quantityUnit as (typeof RECEIVING_QUANTITY_UNITS)[number],
      ...(values.purchaseOrderNo ? { purchaseOrderNo: values.purchaseOrderNo } : {}),
      // Always a Date instance for the required field: blank or malformed
      // text becomes Invalid Date, which the Action input schema rejects
      // as a validation failure (highlighted on the field).
      receivingDate: new Date(receivingRaw),
      ...(expiryRaw ? { expiryDate: new Date(expiryRaw) } : {}),
    });
    const id = extractDetailId(data);
    if (id) return Astro.redirect(detailHref(LIST_HREF, id), 303);
    failure = {
      kind: 'unknown',
      summary: 'The receiving item was received but no record reference came back.',
      recovery: 'Check the receiving register before trying again to avoid a duplicate.',
      fieldErrors: {},
      firstInvalidField: null,
    };
  } catch (error) {
    failure = toFormFailure(error, {
      entity: 'Receiving item',
      requiredFields: REQUIRED_FIELDS,
      values,
      listHref: LIST_HREF,
      listLabel: 'receiving register',
    });
  }
}

const describedBy = (name: keyof typeof values): string | undefined =>
  failure?.fieldErrors[name] ? `${name}-error` : undefined;
const invalid = (name: keyof typeof values): 'true' | undefined =>
  failure?.fieldErrors[name] ? 'true' : undefined;
---
<AppLayout title="Create receiving item · Quarantine" locale="en" direction="ltr">
  <section class="page-head"><div><p class="eyebrow">Receiving</p><h1>Create receiving item</h1><p class="lede">Register the material identity. The server assigns the initial PENDING state.</p></div><a href="/quarantine/receiving">Back to register</a></section>
  {canCreate ? <form class="form" method="post" data-action="quarantine.createReceiving">{failure && <FormErrorSummary summary={failure.summary} recovery={failure.recovery} errors={Object.entries(failure.fieldErrors).map(([fieldId, message]) => ({ fieldId, message }))} listHref={LIST_HREF} listLabel="receiving register" />}<fieldset><legend>Receiving identification</legend><div class="fields"><div><label for="receivingNo">Receiving number<span class="hint" id="receivingNo-help">Use the receiving number from your approved source. Reference numbers are assigned automatically.</span><input id="receivingNo" name="receivingNo" required value={values.receivingNo} aria-invalid={invalid('receivingNo')} aria-describedby={failure?.fieldErrors.receivingNo ? 'receivingNo-error receivingNo-help' : 'receivingNo-help'} /></label>{failure?.fieldErrors.receivingNo && <p class="field-error" id="receivingNo-error">{failure.fieldErrors.receivingNo}</p>}</div><div><label for="supplier">Supplier<input id="supplier" name="supplier" required value={values.supplier} aria-invalid={invalid('supplier')} aria-describedby={describedBy('supplier')} /></label>{failure?.fieldErrors.supplier && <p class="field-error" id="supplier-error">{failure.fieldErrors.supplier}</p>}</div><div><label for="docNo">Document number<input id="docNo" name="docNo" required value={values.docNo} aria-invalid={invalid('docNo')} aria-describedby={describedBy('docNo')} /></label>{failure?.fieldErrors.docNo && <p class="field-error" id="docNo-error">{failure.fieldErrors.docNo}</p>}</div></div></fieldset><fieldset><legend>Item and lot</legend><div class="fields"><div><label for="itemCode">Item code<input id="itemCode" name="itemCode" required value={values.itemCode} aria-invalid={invalid('itemCode')} aria-describedby={describedBy('itemCode')} /></label>{failure?.fieldErrors.itemCode && <p class="field-error" id="itemCode-error">{failure.fieldErrors.itemCode}</p>}</div><div><label for="lot">Lot / batch<input id="lot" name="lot" required value={values.lot} aria-invalid={invalid('lot')} aria-describedby={describedBy('lot')} /></label>{failure?.fieldErrors.lot && <p class="field-error" id="lot-error">{failure.fieldErrors.lot}</p>}</div><div class="wide"><label for="description">Description<textarea id="description" name="description" required aria-invalid={invalid('description')} aria-describedby={describedBy('description')}>{values.description}</textarea></label>{failure?.fieldErrors.description && <p class="field-error" id="description-error">{failure.fieldErrors.description}</p>}</div></div></fieldset><fieldset><legend>Quantity and context</legend><div class="fields"><div><label for="qty">Quantity<input id="qty" name="qty" type="number" min="0" step="any" required value={values.qty} aria-invalid={invalid('qty')} aria-describedby={describedBy('qty')} /></label>{failure?.fieldErrors.qty && <p class="field-error" id="qty-error">{failure.fieldErrors.qty}</p>}<div><label for="quantityUnit">Quantity unit<select id="quantityUnit" name="quantityUnit" required aria-describedby="quantityUnit-help"><option value="" disabled selected={!values.quantityUnit}>Select a unit</option>{RECEIVING_QUANTITY_UNITS.map((unit) => (<option value={unit} selected={values.quantityUnit === unit}>{unit}</option>))}</select><span class="hint" id="quantityUnit-help">The unit the received quantity is counted in — never merged into the quantity.</span></label></div><div><label for="purchaseOrderNo">Purchase order<span class="hint" id="purchaseOrderNo-help">Optional — record it when the delivery names one.</span><input id="purchaseOrderNo" name="purchaseOrderNo" value={values.purchaseOrderNo} aria-invalid={invalid('purchaseOrderNo')} aria-describedby={describedBy('purchaseOrderNo')} /></label>{failure?.fieldErrors.purchaseOrderNo && <p class="field-error" id="purchaseOrderNo-error">{failure.fieldErrors.purchaseOrderNo}</p>}</div></div><div><label for="receivingDate">Receiving date<input id="receivingDate" name="receivingDate" type="date" required value={values.receivingDate} aria-invalid={invalid('receivingDate')} aria-describedby={describedBy('receivingDate')} /></label>{failure?.fieldErrors.receivingDate && <p class="field-error" id="receivingDate-error">{failure.fieldErrors.receivingDate}</p>}</div><div><label for="expiryDate">Expiry date<input id="expiryDate" name="expiryDate" type="date" value={values.expiryDate} /></label></div></div></fieldset><div class="actions"><a class="secondary" href="/quarantine/receiving">Cancel</a><button type="submit" data-submit>Create receiving item</button></div><p role="status" data-result tabindex="-1"></p></form> : <section class="denied" role="alert"><h2>Creation is not available</h2><p>Your account does not have the explicit Quarantine create permission.</p></section>}
</AppLayout>
<script>
  import { actions } from 'astro:actions';
  import { RECEIVING_QUANTITY_UNITS } from '../../../modules/quarantine/receiving/application/presentation.js';
  import { enhanceClassifiedForm } from '../../../ui/forms/enhance-with-classification';
  import { guardUnsavedChanges } from '../../../ui/forms/unsaved-changes';
  const form = document.querySelector<HTMLFormElement>('[data-action="quarantine.createReceiving"]');
  if (form) {
    enhanceClassifiedForm(form, {
      invoke: async (payload) => actions.quarantine.createReceiving(payload as Parameters<typeof actions.quarantine.createReceiving>[0]),
      payload: (data) => ({
        receivingNo: String(data.get('receivingNo') ?? ''),
        supplier: String(data.get('supplier') ?? ''),
        docNo: String(data.get('docNo') ?? ''),
        itemCode: String(data.get('itemCode') ?? ''),
        description: String(data.get('description') ?? ''),
        lot: String(data.get('lot') ?? ''),
        qty: String(data.get('qty') ?? ''),
        quantityUnit: String(data.get('quantityUnit') ?? '') as (typeof RECEIVING_QUANTITY_UNITS)[number],
        purchaseOrderNo: String(data.get('purchaseOrderNo') ?? '') || undefined,
        receivingDate: new Date(String(data.get('receivingDate') ?? '')),
        expiryDate: data.get('expiryDate') ? new Date(String(data.get('expiryDate'))) : undefined,
      }),
      progressText: 'Saving receiving draft…',
      detailBaseHref: '/quarantine/receiving',
      unknownRecoveryHref: '/quarantine/receiving',
    });
    guardUnsavedChanges(form);
  }
</script>
<style>
  .page-head{display:flex;justify-content:space-between;gap:var(--space-5);align-items:flex-start;margin-bottom:var(--space-6)}h1{margin:.25rem 0 .4rem}.eyebrow{margin:0;color:var(--text-muted);font-size:.75rem;letter-spacing:.12em;font-weight:700}.lede,.denied p,.hint{color:var(--text-muted);font-size:.85rem}.hint{font-size:.78rem}.page-head a{color:var(--color-accent-primary-hover)}.form{max-width:900px;display:grid;gap:var(--space-5)}fieldset{display:grid;gap:var(--space-4);padding:var(--space-5);border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg);background:var(--surface-panel)}legend{padding-inline:.5rem;color:var(--text-primary);font-weight:700}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-4)}.fields>div{display:grid;gap:.4rem;color:var(--text-secondary);font-size:.82rem}.wide{grid-column:1/-1}label{display:grid;gap:.4rem}input,textarea{width:100%;min-height:var(--control-height);padding:.65rem;background:var(--surface-raised);border:1px solid var(--border-default);border-radius:var(--radius-sm);color:inherit;font:inherit}input[aria-invalid="true"],textarea[aria-invalid="true"]{border-color:var(--status-danger)}.field-error{margin:0;color:var(--status-danger);font-size:.8rem}textarea{min-height:7rem;resize:vertical}.actions{display:flex;justify-content:flex-end;gap:var(--space-3)}button{min-height:var(--control-height);padding-inline:1rem;border:1px solid var(--color-accent-primary);border-radius:var(--radius-sm);background:var(--color-accent-primary);color:#fff;font-weight:700}button[disabled]{opacity:.6}.secondary{border-color:var(--border-default);background:var(--surface-raised);color:var(--text-primary);text-decoration:none;padding:.65rem 1rem;border:1px solid var(--border-default);border-radius:var(--radius-sm)}.denied{padding:var(--space-6);border-inline-start:3px solid var(--status-warning);background:var(--surface-panel)}@media(max-width:650px){.page-head{display:grid}.fields{grid-template-columns:1fr}.wide{grid-column:auto}.actions{justify-content:stretch;display:grid}}
