import Icon from '../../ui/components/Icon.astro';
import AppLayout from '../../ui/layouts/AppLayout.astro';
import { reportingDependencies } from '../../modules/reporting/application/dependencies.js';
import { authorize } from '../../shared/authorization/authorize.js';
const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Freports');
const registry = reportingDependencies().registry;
const reports = registry.list().filter((report) => authorize({ actor, permission: report.viewPermission, action: 'VIEW', entity: { type: 'REPORT', id: report.code, state: 'ACTIVE', ownerId: actor.id, domain: 'REPORTING' }, scope: { domain: 'REPORTING' }, currentVersion: 1, expectedVersion: 1, businessCondition: true }).allowed);
---
<AppLayout title="Reports · QC Operations" locale="en" direction="ltr">
  <section class="page-head"><p class="eyebrow">REPORT REGISTRY</p><h1>Reports</h1><p class="lede">Canonical reports available in your authorized scope.</p></section>
  {reports.length ? <div class="report-grid">{reports.map((report) => <article class="report-card"><p class="eyebrow">{report.code}</p><h2><a href={`/reports/${report.code}`}>{report.title}</a></h2><p>{report.description}</p><a class="open" href={`/reports/${report.code}`}>Open report <Icon name="arrow-right" /></a></article>)}</div> : <p class="empty">No reports are available for your current permissions and scope.</p>}
</AppLayout>
<style>.page-head{margin-bottom:var(--space-6)}h1{margin:.25rem 0}.eyebrow{margin:0;color:var(--text-muted);font-size:.7rem;letter-spacing:.12em;font-weight:700}.lede,.report-card p,.empty{color:var(--text-muted);font-size:.86rem}.report-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:var(--space-5)}.report-card{padding:var(--space-5);background:var(--surface-panel);border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg)}h2{margin:.5rem 0;font-size:1.1rem}h2 a,.open{color:var(--color-accent-primary-hover)}.open{display:inline-block;margin-top:var(--space-4);font-size:.85rem}</style>

---
import AppLayout from '../ui/layouts/AppLayout.astro';
import ProviderUnavailableState from '../ui/components/feedback/ProviderUnavailableState.astro';
import { searchDependencies } from '../shared/search/search-dependencies.js';
import type { SearchPage } from '../shared/search/search-result.js';
import { searchTypeLabel, stateLabel } from '../shared/copy/ux-vocabulary.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(`${Astro.url.pathname}${Astro.url.search}`)}`);
const rawQuery = Astro.url.searchParams.get('q') ?? '';
const q = rawQuery.trim();
const rawCursor = Astro.url.searchParams.get('cursor') ?? undefined;
const invalidQuery = Astro.url.searchParams.has('q') && (!q || q.length > 200 || q.includes('\0'));
if (invalidQuery) Astro.response.status = 400;
const canUseSearch = actor.permissions.some((grant) => grant.code === 'PERM-SRCH-USE' && grant.active !== false);
let page: SearchPage = { items: [], total: 0 };
let providerUnavailable = false;
let invalidCursor = false;
if (q && !invalidQuery && canUseSearch) {
  try {
    page = await searchDependencies(async (actorId) => { if (actorId !== actor.id) throw new Error('unauthorized'); }).search.search({
      actorId: actor.id,
      q,
      cursor: rawCursor,
      permissions: actor.permissions,
    });
  } catch (error) {
    if (error && typeof error === 'object' && 'code' in error && error.code === 'VALIDATION_INVALID_QUERY') {
      // Malformed cursors are presented as validation errors, not as source outages.
      invalidCursor = true;
      Astro.response.status = 400;
    } else providerUnavailable = true;
  }
}
const results = page.items;
const destination = (result: (typeof results)[number]) => ({ TASK: `/tasks/${result.entityId}`, RECEIVING_ITEM: `/quarantine/receiving/${result.entityId}`, INSPECTION_REPORT: `/quarantine/inspections/${result.entityId}`, LAB_TEST: `/laboratory/tests/${result.entityId}`, FINDING: `/quality/findings/${result.entityId}`, NCR: `/quality/ncr/${result.entityId}`, CAPA: `/quality/capa/${result.entityId}`, EQUIPMENT: `/assets/equipment/${result.entityId}`, DOCUMENT: `/documents/${result.entityId}`, CHANGE_REQUEST: `/change-requests/${result.entityId}`, REJECT_REPORT: `/reject-reports/${result.businessId.startsWith('RIS') ? 'issue-slips' : 'daily'}/${result.entityId}` } as Record<string, string>)[result.entityType] ?? '/dashboard';
const nextHref = page.nextCursor ? `/search?q=${encodeURIComponent(q)}&cursor=${encodeURIComponent(page.nextCursor)}` : undefined;
---
<AppLayout title="Search · QC Operations" locale="en" direction="ltr">
  <section class="search-page" aria-labelledby="search-title">
    <p class="eyebrow">GLOBAL SEARCH</p>
    <h1 id="search-title">Find authorized records</h1>
    <form role="search" method="get">
      <label for="q">Search tasks, inspections, lab tests, findings, NCRs, CAPA, equipment, documents, or change requests</label>
      <div class="search-row"><input id="q" name="q" value={rawQuery} maxlength="200" autocomplete="off" aria-invalid={invalidQuery || invalidCursor ? 'true' : undefined} aria-describedby={invalidQuery || invalidCursor ? 'query-error' : 'query-hint'} /><button type="submit">Search</button>{q && <a href="/search">Clear</a>}</div>
    {invalidQuery || invalidCursor ? <p class="field-error" id="query-error" role="alert">{invalidCursor ? 'That result page link is no longer valid. Start the same search again.' : 'Enter a search term with 1–200 characters. Your search text is preserved.'}</p> : <p class="hint" id="query-hint">Press Enter to search. Results follow your read permissions and scope. Use Ctrl/Cmd+K anywhere in the workspace to return here.</p>}
    </form>
    {!canUseSearch ? <section class="empty" role="status"><h2>Search is not available for this account</h2><p>No records or result counts are shown. Ask your administrator to review your search access.</p></section>
      : providerUnavailable ? <ProviderUnavailableState title="Search is temporarily unavailable" description="The search source did not confirm a response. No result count is shown. Retry the same search or return to the workspace." />
      : q && !invalidQuery && !invalidCursor ? <p class="result-count" aria-live="polite">Showing {results.length} of {page.total} authorized result{page.total === 1 ? '' : 's'} for “{q}”.</p>
      : !q && !invalidQuery && <p class="empty">Start with a record number, document number, lot, task title, or description.</p>}
    {q && !invalidQuery && !invalidCursor && canUseSearch && !providerUnavailable && page.total === 0 && <section class="empty" aria-live="polite"><h2>No matching records found</h2><p>Check the identifier or try a broader term. Records outside your authorized read scope are not disclosed.</p></section>}
    {results.length > 0 && <ul class="results" aria-label="Search results">{results.map((result) => <li><a href={destination(result)}><span class="type">{searchTypeLabel(result.entityType)}</span><strong>{result.businessId}</strong><span class="descriptor">{result.descriptor}</span><small>{stateLabel(result.state)}{result.context ? ` · ${result.context}` : ''}</small></a></li>)}</ul>}
    {nextHref && <nav class="pagination" aria-label="Search result pages"><a href={nextHref}>Next results</a></nav>}
  </section>
</AppLayout>
<style>
.search-page{max-width:900px;margin-inline:auto}.eyebrow{margin:0;color:var(--text-muted);font-size:.7rem;letter-spacing:.12em;font-weight:700}.search-page h1{margin:.4rem 0 1.5rem}.search-page form{padding:var(--space-5);background:var(--surface-panel);border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg)}label{display:block;color:var(--text-secondary);font-size:.85rem;font-weight:600}.search-row{display:flex;gap:var(--space-3);align-items:center;margin-top:var(--space-3)}input{flex:1;min-width:0;min-height:48px;padding-inline:14px;border:1px solid var(--color-border-default);border-radius:var(--radius-sm);background:var(--surface-raised);color:var(--text-primary);font:inherit}input[aria-invalid="true"]{border-color:var(--border-invalid)}button{min-height:48px;padding-inline:18px;border:0;border-radius:var(--radius-sm);background:var(--color-accent-primary);color:var(--color-text-inverse);font-weight:700}.search-row a,.pagination a{color:var(--color-accent-primary-hover);font-size:.85rem}.hint,.empty,.result-count{color:var(--text-muted);font-size:.85rem}.field-error{color:var(--text-danger);font-size:.85rem}.results{list-style:none;margin:var(--space-5) 0;padding:0}.results li{border-block-start:1px solid var(--color-border-subtle)}.results a{display:grid;grid-template-columns:140px minmax(0,1fr);gap:4px 14px;padding:var(--space-4) 0;color:inherit;text-decoration:none}.results a:focus-visible,.search-row a:focus-visible,.pagination a:focus-visible{outline:3px solid var(--focus-ring);outline-offset:3px}.results .type,.results small{color:var(--text-muted);font-size:.78rem}.results .descriptor{color:var(--text-secondary);font-size:.9rem;overflow-wrap:anywhere}.results strong{overflow-wrap:anywhere}.empty{margin-top:var(--space-5);padding:var(--space-8);text-align:center;border:1px dashed var(--color-border-default);border-radius:var(--radius-lg)}.empty h2{color:var(--text-primary);font-size:1rem}.pagination{display:flex;justify-content:flex-end;margin-block:var(--space-5)}@media(max-width:520px){.search-row{flex-wrap:wrap}.search-row input{flex-basis:100%}.results a{grid-template-columns:1fr}.search-page form{padding:var(--space-4)}}
</style>

---
import AppLayout from '../../../../ui/layouts/AppLayout.astro';
import { backupCatalogReadDependencies } from '../../../../modules/backup-recovery/application/dependencies.js';
import { isUuid } from '../../../../shared/id/uuid.js';
import { stateLabel } from '../../../../shared/copy/ux-vocabulary.js';
import { classifyReadFailure, providerUnavailableResponse } from '../../../../shared/errors/read-failure.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
const backupId = Astro.params.backupId ?? '';
if (!isUuid(backupId)) return Astro.redirect('/404');
let detail;
try {
  detail = await backupCatalogReadDependencies().get.execute({ actor, backupId });
} catch (error) {
  if (classifyReadFailure(error) === 'UNAVAILABLE') return providerUnavailableResponse('Backup details are temporarily unavailable', Astro.url.pathname + Astro.url.search);
  return Astro.redirect('/404');
}
if (!detail) return Astro.redirect('/404');
const { backup, restoreRuns, restoreVerification, restorable } = detail;
const canRequestDrill = actor.permissions.some((permission) => permission.active !== false && permission.code === 'PERM-BKP-RESTORE-DRILL');
const restoreLabel =
  restoreVerification === 'VERIFIED'
    ? 'RESTORE VERIFIED'
    : restoreVerification === 'VERIFICATION_FAILED'
      ? 'RESTORE VERIFICATION FAILED'
      : restoreVerification === 'VERIFYING'
        ? 'RESTORE VERIFYING'
        : 'RESTORE NOT VERIFIED';
const riyadh = (date: Date) => date.toLocaleString('en-SA', { timeZone: 'Asia/Riyadh' });
const knownGaps = [
  ...(backup.checksum ? [] : ['Integrity checksum is not recorded for this backup set.']),
  ...(backup.state === 'CREATED' ? ['Backup artifact has not completed verification.'] : []),
  ...(restoreVerification !== 'VERIFIED' ? ['No verified restore exists for this backup set.'] : []),
  ...(backup.databaseSchemaVersion ? [] : ['Migration/schema context is not recorded for this backup set.']),
];
---
<AppLayout title={`Backup set · ${riyadh(backup.requestedAt)} · QC Operations`} locale="en" direction="ltr">
  <section class="page-head"><div><p class="eyebrow">Backup record</p><h1>Backup set</h1><p class="lede">Metadata only: this page never exposes storage references or provider paths, and it never restores.</p></div><div class="head-actions"><span class={`pill ${backup.state === 'CREATED' || backup.state === 'VERIFIED' ? 'ok' : backup.state === 'FAILED' ? 'bad' : 'unknown'}`}>Job: {stateLabel(backup.state)}</span><span class={`pill ${restoreVerification === 'VERIFIED' ? 'ok' : restoreVerification === 'VERIFICATION_FAILED' ? 'bad' : 'unknown'}`}>{restoreLabel}</span>{restorable && canRequestDrill && <a class="button" href={`/system/backups/${backup.id}/restore`}>Request restore</a>}</div></section>
  <div class="grid">
    <section class="panel"><h2>Backup metadata</h2><p class="record-name">Backup requested {riyadh(backup.requestedAt)} (Asia/Riyadh)</p><dl>
      <div><dt>Backup job state</dt><dd>{stateLabel(backup.state)} — execution result only</dd></div>
      <div><dt>Artifact verified</dt><dd>{backup.state === 'VERIFIED' ? 'Yes' : 'No'}</dd></div>
      <div><dt>Requested</dt><dd>{riyadh(backup.requestedAt)} · Asia/Riyadh</dd></div>
      {backup.artifactCreatedAt && <div><dt>Artifact created</dt><dd>{riyadh(backup.artifactCreatedAt)} · Asia/Riyadh</dd></div>}
      {backup.verifiedAt && <div><dt>Artifact verified at</dt><dd>{riyadh(backup.verifiedAt)} · Asia/Riyadh</dd></div>}
      {backup.sizeBytes !== undefined && <div><dt>Size</dt><dd>{backup.sizeBytes.toString()} bytes</dd></div>}
      <div><dt>Integrity checksum</dt><dd>{backup.checksum ? 'Recorded (value withheld)' : 'Not recorded'}</dd></div>
      <div><dt>Database schema version</dt><dd>{backup.databaseSchemaVersion ?? 'Not recorded'}</dd></div>
      {backup.errorCode && <div><dt>Job result</dt><dd>The backup job did not complete. Contact your system administrator for help.</dd></div>}
    </dl></section>
    <section class="panel"><h2>Restore verification</h2><p class="muted">A completed backup job is not restore evidence. Verification status comes only from recorded restore operations for this set.</p><dl>
      <div><dt>Restore verification</dt><dd class={restoreVerification === 'VERIFIED' ? 'good' : 'warn'}>{restoreLabel}</dd></div>
      <div><dt>Recorded restore operations</dt><dd>{restoreRuns.length}</dd></div>
    </dl>
    {restoreRuns.length ? <div class="table-wrap"><table><caption>Restore operations recorded for this backup set</caption><thead><tr><th scope="col">Operation</th><th scope="col">Type</th><th scope="col">State</th><th scope="col">Target environment</th><th scope="col">Requested</th></tr></thead><tbody>{restoreRuns.map((run) => <tr><th scope="row">Restore request · {riyadh(run.requestedAt)}</th><td>{run.restoreType === 'DRILL' ? 'Isolated drill' : 'Production restore'}</td><td>{stateLabel(run.state)}</td><td>{run.targetEnvironment}</td><td>{riyadh(run.requestedAt)}</td></tr>)}</tbody></table></div> : <p class="muted">No restore operations are recorded for this backup set.</p>}</section>
  </div>
  <details class="technical"><summary>Technical record details</summary><dl><div><dt>Backup record UUID</dt><dd><code>{backup.id}</code></dd></div><div><dt>Request ID</dt><dd><code>{backup.requestId}</code></dd></div></dl></details>
  <section class="panel"><h2>Known gaps</h2>{knownGaps.length ? <ul class="gaps">{knownGaps.map((gap) => <li>{gap}</li>)}</ul> : <p class="muted">No catalog-level gaps are recorded for this backup set. Catalog completeness is not restore evidence.</p>}</section>
  <section class="notice" role="note"><strong>Restore boundary</strong><span>Restore requests are recorded through an explicit POST action with server-side authorization, a required reason, and confirmation. A recorded request stays planned: no restore provider or production authority is approved in this baseline, so nothing is executed and nothing is claimed verified.</span></section>
</AppLayout>
