    margin-top: var(--space-4);
    font-size: 0.84rem;
  }
  .form {
    display: grid;
    gap: var(--space-4);
    max-width: 720px;
  }
  .form label {
    display: grid;
    gap: 0.4rem;
    font-size: 0.85rem;
  }
  .form input {
    min-height: 44px;
    padding: 0.7rem;
