---
import AppLayout from '../../ui/layouts/AppLayout.astro';
import { systemHealthReadDependencies } from '../../modules/system-health/application/dependencies.js';
import { formatDateTime } from '../../shared/copy/format.js';
import ProviderUnavailableState from '../../ui/components/feedback/ProviderUnavailableState.astro';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
let view: Awaited<ReturnType<ReturnType<typeof systemHealthReadDependencies>['health']['execute']>> | undefined;
let providerUnavailable = false;
try {
  view = await systemHealthReadDependencies().health.execute({ actor });
} catch {
  providerUnavailable = true;
}
if (!view) {
  providerUnavailable = true;
  Astro.response.status = 503;
}
const canSeeBackupPosture = actor.permissions.some((permission) => permission.active !== false && permission.code === 'PERM-BKP-VIEW');
const statusLabel = (status: string) =>
  status === 'HEALTHY' ? 'HEALTHY' : status === 'DEGRADED' ? 'DEGRADED' : status === 'UNAVAILABLE' ? 'UNAVAILABLE' : 'UNKNOWN';
const serviceReady = view?.dependencyReadiness === 'READY' && view?.rejectReportsReadiness === 'READY';
const serviceBanner = serviceReady
  ? { class: 'ok', title: 'Service readiness: READY', note: 'Application, PostgreSQL, and the Reject Reports schema probe are healthy. This is an operational readiness result, not QC release approval.' }
  : view?.dependencyReadiness === 'READY' && view?.rejectReportsReadiness === 'UNKNOWN'
    ? { class: 'bad', title: 'Service readiness: UNKNOWN', note: 'A required workflow or dependency could not be verified. Machine liveness and QC release evidence are separate.' }
    : { class: 'bad', title: 'Service readiness: NOT READY', note: 'At least one required dependency or the Reject Reports workflow is unavailable. Machine liveness and QC release evidence are separate.' };
const backup = view?.backupPosture;
const releaseValue = (value: string | undefined) => value ?? 'UNVERIFIED';
const releaseVerifiedFields = view?.release.verifiedFields ?? 0;
const releaseFieldCount = view?.release.fieldCount ?? 6;
const releaseCheckedAt = view?.release.checkedAt ?? view?.generatedAt.toISOString() ?? new Date().toISOString();
const releaseFields = view?.release.fields ?? [];
const recoveryCopy = (detail?: string) => ({
  CONFIGURATION_MISSING: 'Add the required setting through the approved runtime secret manager, then recheck health. Do not paste secret values into this page.',
  CONFIGURATION_INVALID: 'Correct the setting format and required TLS options in the approved runtime configuration, then recheck health.',
  PROVIDER_UNAVAILABLE: 'Check provider reachability and service status. Keep the dependency NOT READY until its server-side probe succeeds.',
  SCHEMA_NOT_READY: 'Reconcile the source/applied migration ledger in an isolated database, then follow the owner-approved schema release procedure.',
  POLICY_DISABLED: 'External AI processing remains disabled. Do not send data or enable processing without approved policy and named-owner authorization.',
  POLICY_NOT_VALID: 'Review the approved processing policy source. Provider use remains disabled until the policy validates.',
  CONFIGURATION_INVALID_AI: 'Correct the AI provider configuration without exposing keys. Processing remains disabled until all policy gates pass.',
  CONFIGURATION_MISSING_AI: 'Provider configuration is incomplete. Add only approved settings; no provider request is sent while incomplete.',
}[detail ?? '']);
const recoveryItems = view?.checks.flatMap((check) => {
  const key = check.dependency === 'ai-provider' && check.detail === 'CONFIGURATION_INVALID'
    ? 'CONFIGURATION_INVALID_AI'
    : check.dependency === 'ai-provider' && check.detail === 'CONFIGURATION_MISSING'
      ? 'CONFIGURATION_MISSING_AI'
      : check.detail;
  const guidance = recoveryCopy(key);
  return guidance ? [{ dependency: check.dependency, guidance }] : [];
}) ?? [];
const restoreLabel = backup
  ? backup.restoreVerification === 'VERIFIED'
    ? 'RESTORE VERIFIED'
    : backup.restoreVerification === 'VERIFICATION_FAILED'
      ? 'RESTORE VERIFICATION FAILED'
      : backup.restoreVerification === 'VERIFYING'
        ? 'RESTORE VERIFYING'
        : backup.restoreVerification === 'UNKNOWN'
          ? 'RESTORE VERIFICATION UNKNOWN'
          : 'RESTORE NOT VERIFIED'
  : '';
---
<AppLayout title="System health · QC Operations" locale="en" direction="ltr">
  {providerUnavailable ? <ProviderUnavailableState title="System health checks are temporarily unavailable" description="The health read did not return a confirmed result. No dependency or release status is inferred." retryHref="/system/health" /> : view && <>
  <section class="page-head"><div><h1>System health</h1><p class="lede">Status is derived from live server-side checks. Raw infrastructure errors, credentials, and endpoints are intentionally never shown.</p></div><span class={`banner ${serviceBanner.class}`}>{serviceBanner.title}</span></section>
  <section class="notice" role="note"><strong>Separate health layers</strong><span>Liveness at <code>/api/health/live</code> reports only whether the process responds. {serviceBanner.note} Readiness at <code>/api/health/ready</code> checks PostgreSQL and the same Reject Reports schema probe used by the page. Neither confirms QC completion or release approval. Generated {formatDateTime(view.generatedAt)} (Asia/Riyadh).</span></section>
  <section class="notice" role="note" data-testid="delivery-business-separation"><strong>Delivery is not a business decision</strong><span>A failed integration or notification delivery records transport failure only. It does not mark an inspection, laboratory result, approval, or release complete; the owning QC workflow and its audit record remain authoritative.</span></section>
  <section class="panel"><h2>QC release readiness</h2><p><strong class={view.qcReleaseReadiness === 'BLOCKED' ? 'warn' : 'muted'}>{view.qcReleaseReadiness}</strong></p><p class="muted">BLOCKED means the required workflow or migration state is unavailable or has drift. NOT VERIFIED means this health view does not establish the separate CI, UAT, recovery, security, and release evidence required by the release runbook.</p><p class="decision-note"><strong>Operational health is not a release decision.</strong> Production GO requires 19/19 mandatory gates tied to the same candidate. This page does not calculate that register or set a candidate to RELEASED.</p></section>
  <section class="panel"><h2>Dependencies and schema</h2><div class="table-wrap"><table><caption>Sanitized dependency status per approved health vocabulary</caption><thead><tr><th scope="col">Dependency</th><th scope="col">Status</th><th scope="col">Detail</th></tr></thead><tbody>{view.checks.map((item) => <tr><th scope="row">{item.dependency}</th><td><span class={`pill ${item.status === 'HEALTHY' ? 'ok' : item.status === 'DEGRADED' ? 'warn' : item.status === 'UNAVAILABLE' ? 'bad' : 'unknown'}`}>{statusLabel(item.status)}</span></td><td>{item.detail ?? '—'}</td></tr>)}</tbody></table></div><p class="muted">AI advisory is optional: {view.aiCapability === 'HEALTHY' ? 'it is available.' : view.aiCapability === 'UNAVAILABLE' ? 'it is unavailable; this does not alter required workflow readiness.' : view.aiCapability === 'DEGRADED' ? 'it is degraded; this does not alter required workflow readiness.' : 'its status is unknown; this does not establish workflow or release readiness.'}</p>{recoveryItems.length > 0 && <div class="recovery-guidance" role="status" aria-live="polite"><h3>Recovery guidance</h3><ul>{recoveryItems.map((item) => <li><strong>{item.dependency}:</strong> {item.guidance}</li>)}</ul></div>}<p class="muted">Outbox pending count is exposed as a telemetry gauge. Export is <strong>NOT CONFIGURED</strong> in the default wiring; backlog growth trend is <strong>NOT CONFIGURED</strong> because no approved trend window is defined.</p></section>
  <section class="panel"><h2>Alerting configuration</h2><p><strong class="warn">NOT CONFIGURED</strong></p><p class="muted">Numeric thresholds, on-call/escalation policy, and alert recipient are deferred by the approved observability decisions. This page exposes diagnostics without claiming alert delivery.</p></section>
  {canSeeBackupPosture && backup && (
    <section class="panel"><h2>Backup &amp; recovery posture</h2><p class="muted">Backup job success never equals a verified restore (BKP-001). These are separate facts and are never merged into a single green badge.</p>
      <dl><div><dt>Last backup job state</dt><dd>{backup.lastBackupJobState ?? 'NO CATALOG DATA'}</dd></div><div><dt>Backup artifact verified</dt><dd>{backup.artifactVerified ? 'YES' : 'NO'}</dd></div><div><dt>Restore verification</dt><dd class={backup.restoreVerification === 'VERIFIED' ? 'good' : 'warn'}>{restoreLabel}</dd></div><div><dt>Posture status</dt><dd>{statusLabel(backup.postureStatus)}</dd></div></dl>
      {backup.knownGaps.length > 0 && <div><h3>Known gaps</h3><ul class="gaps">{backup.knownGaps.map((gap) => <li><code>{gap}</code></li>)}</ul></div>}
      <p class="muted">Backup catalog: <a href="/system/backups">/system/backups</a></p>
    </section>
  )}
  <section class="panel release-panel" aria-labelledby="release-identity-title" data-testid="release-identity"><h2 id="release-identity-title">Release identity</h2><p class="muted">Server-derived build artifact. Missing, stale, or mismatched evidence stays UNVERIFIED and never becomes a readiness claim.</p><p role="status" aria-live="polite" data-release-completeness>Required identity sources: {releaseVerifiedFields}/{releaseFieldCount} ({Math.round((releaseVerifiedFields / releaseFieldCount) * 100)}%). Checked {formatDateTime(new Date(releaseCheckedAt))} (Asia/Riyadh). This scoped ratio is not product quality or a release decision.</p><dl><div><dt>Verification</dt><dd data-release-field="status" class={view.release.status === 'VERIFIED' ? 'good' : 'warn'}>{view.release.status}</dd></div><div><dt>Working tree</dt><dd>{view.release.dirty === undefined ? 'UNVERIFIED' : view.release.dirty ? 'DIRTY' : 'CLEAN'}</dd></div><div><dt>Release ID</dt><dd data-release-field="releaseId">{releaseValue(view.release.releaseId)}</dd></div><div><dt>Build ID</dt><dd data-release-field="buildId">{releaseValue(view.release.buildId)}</dd></div><div><dt>Build timestamp</dt><dd data-release-field="buildTimestamp">{releaseValue(view.release.buildTimestamp)}</dd></div><div><dt>Git SHA</dt><dd data-release-field="gitSha">{releaseValue(view.release.gitSha)}</dd></div><div><dt>Environment</dt><dd data-release-field="environment">{releaseValue(view.release.environment)}</dd></div><div><dt>Migration head</dt><dd data-release-field="migrationHead">{releaseValue(view.release.migrationHead)}</dd></div></dl><div class="table-wrap"><table><caption>Evidence source and validation for each required release identity element</caption><thead><tr><th scope="col">Identity element</th><th scope="col">Source</th><th scope="col">Status</th></tr></thead><tbody>{releaseFields.map((field) => <tr><th scope="row">{field.name}</th><td>{field.source}</td><td class={field.status === 'VERIFIED' ? 'good' : 'warn'}>{field.status}</td></tr>)}</tbody></table></div>{view.release.reason && <p class="warn" role="status">Identity evidence needs recovery: {view.release.reason}. Rebuild the release artifact from the exact candidate and verify the deployed artifact before acceptance.</p>}
  </section></>}
</AppLayout>
<style>.decision-note{padding:var(--space-3);border-inline-start:3px solid var(--status-error);background:var(--surface-raised);font-size:.84rem}</style>
<style>.pill{padding:.2rem .55rem;border-radius:999px;font-size:.72rem;font-weight:700}.pill.ok{color:var(--status-success);border:1px solid var(--status-success)}.pill.warn{color:var(--status-warning);border:1px solid var(--status-warning)}.pill.bad{color:var(--status-error);border:1px solid var(--status-error)}.pill.unknown{color:var(--text-muted);border:1px solid var(--color-border-strong)}h1{margin:.25rem 0}.eyebrow{margin:0;color:var(--text-muted);font-size:.7rem;letter-spacing:.12em;font-weight:700}.lede,.muted{color:var(--text-muted);font-size:.86rem}.page-head{display:flex;justify-content:space-between;gap:var(--space-5);align-items:flex-start;margin-bottom:var(--space-6)}.banner{padding:.45rem .8rem;border-radius:999px;font-size:.78rem;font-weight:700;white-space:nowrap;max-inline-size:100%}.banner.ok{border:1px solid var(--status-success);color:var(--status-success)}.banner.bad{border:1px solid var(--status-error);color:var(--status-error)}.notice,.panel{padding:var(--space-5);margin-bottom:var(--space-5);border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg);background:var(--surface-panel)}.notice{display:grid;gap:.35rem;border-inline-start:3px solid var(--status-warning)}.notice span{color:var(--text-muted);font-size:.85rem}.panel h2{margin-top:0;font-size:1rem}.panel h3{font-size:.85rem;margin-bottom:.35rem}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}caption{text-align:start;padding-bottom:var(--space-3);color:var(--text-muted);font-size:.8rem}th,td{padding:.7rem;text-align:start;border-top:1px solid var(--color-border-subtle);font-size:.82rem}th{font-weight:700}dl{display:grid;gap:var(--space-3);margin:0 0 var(--space-4)}dl div{display:flex;justify-content:space-between;gap:var(--space-4);border-bottom:1px solid var(--color-border-subtle);padding-bottom:.55rem}dt{color:var(--text-muted);font-size:.8rem}dd{margin:0;text-align:end;font-size:.8rem;font-weight:700;min-inline-size:0;overflow-wrap:anywhere}.good{color:var(--status-success)}.warn{color:var(--status-warning)}.gaps{display:flex;gap:.5rem;flex-wrap:wrap;list-style:none;padding:0}code{padding:.2rem .45rem;background:var(--surface-raised);border-radius:var(--radius-sm);font-size:.72rem;overflow-wrap:anywhere}.panel a{color:var(--color-accent-primary-hover)}@media(max-width:650px){.page-head{display:grid}.banner{white-space:normal;justify-self:start}dl div{display:grid;gap:.2rem}dd{text-align:start}.notice,.panel{padding:var(--space-4)}}</style>

---
import AppLayout from '../../ui/layouts/AppLayout.astro';
import { taskReadDependencies } from '../../modules/tasks/application/dependencies.js';
import { priorityLabel, stateLabel } from '../../shared/copy/ux-vocabulary.js';
import { formatDateTime } from '../../shared/copy/format.js';
import { actorHasScope } from '../../shared/authorization/scope-evaluator.js';
import { classifyReadFailure, providerUnavailableResponse } from '../../shared/errors/read-failure.js';
import { actions } from 'astro:actions';
import FormErrorSummary from '../../ui/components/FormErrorSummary.astro';
import { extractDetailId, field, parseExpectedVersionField, toFormFailure, type FormFailure } from '../../ui/forms/mutation-post.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect(`/login?returnTo=${encodeURIComponent(Astro.url.pathname)}`);
const taskId = Astro.params.taskId ?? '';
const REQUIRED_FIELDS = [{ name: 'reason', label: 'Reason' }] as const;
let transitionValues = { action: '', expectedVersion: '', reason: '' };
let transitionFailure: FormFailure | null = null;
let details;
try {
  details = await taskReadDependencies().get.execute({ actor, taskId });
} catch (error) {
  if (classifyReadFailure(error) === 'UNAVAILABLE') {
    return providerUnavailableResponse('Task details are temporarily unavailable', Astro.url.pathname + Astro.url.search);
  }
  return Astro.redirect('/404');
}
const { task } = details;
const canTaskAction = (code: string) => {
  const grant = actor.permissions.find((item) => item.code === code && item.active !== false);
  return Boolean(
    grant &&
      actorHasScope(
        actor,
        { type: 'TASK', id: task.id, state: task.state, ownerId: task.createdBy, assigneeId: task.currentAssigneeId },
        { ownerId: task.createdBy, assigneeId: task.currentAssigneeId },
        grant,
      ),
  );
};
const nextStep = ({
  DRAFT: canTaskAction('PERM-TASK-CREATE') ? 'Activate when the draft is ready.' : 'Wait for an authorized user to activate this draft.',
  OPEN: canTaskAction('PERM-TASK-EDIT') ? 'Start the work when it is ready to begin.' : 'Wait for an authorized user to start the work.',
  IN_PROGRESS: canTaskAction('PERM-TASK-COMPLETE') || canTaskAction('PERM-TASK-BLOCK') ? 'Complete the work when requirements are met, or place it on hold with a reason.' : 'Wait for an authorized user to complete or hold the work.',
  ON_HOLD: canTaskAction('PERM-TASK-EDIT') ? 'Resume work when the blocker is resolved.' : 'Wait for an authorized user to resume the work.',
  COMPLETED: canTaskAction('PERM-TASK-REOPEN') ? 'Reopen with a reason if more work is needed.' : 'Task complete. Reopening requires separate permission.',
  CANCELLED: 'No further action is available.',
} as const)[task.state];
const actionLabel = (action: string) => ({
  CREATE_TASK: 'Created',
  UPDATE_DRAFT: 'Draft updated',
  ACTIVATE: 'Activated',
  START: 'Started',
  HOLD: 'Placed on hold',
  RESUME: 'Resumed',
  COMPLETE: 'Completed',
  REOPEN: 'Reopened',
}[action] ?? 'Task updated');
const reasonError = () => transitionFailure?.fieldErrors.reason;

if (Astro.request.method === 'POST') {
  const formData = await Astro.request.formData();
  transitionValues = {
    action: field(formData, 'action'),
    expectedVersion: field(formData, 'expectedVersion'),
    reason: String(formData.get('reason') ?? ''),
  };
  try {
    const data = await Astro.callAction(actions.tasks.transition, {
      taskId,
      expectedVersion: parseExpectedVersionField(transitionValues.expectedVersion),
      action: transitionValues.action as 'ACTIVATE' | 'START' | 'HOLD' | 'RESUME' | 'COMPLETE' | 'REOPEN',
      ...(transitionValues.reason.trim() ? { reason: transitionValues.reason.trim() } : {}),
    });
    const id = extractDetailId(data);
    if (id === taskId) return Astro.redirect(`/tasks/${id}`, 303);
    transitionFailure = {
      kind: 'unknown',
      summary: 'The action result could not be confirmed.',
      recovery: 'Review this task and its transition history before deciding whether to try again.',
      fieldErrors: {},
      firstInvalidField: null,
    };
  } catch (error) {
    transitionFailure = toFormFailure(error, {
      entity: 'task action',
      requiredFields: REQUIRED_FIELDS,
      values: transitionValues,
      listHref: `/tasks/${taskId}?reconcile=1#transition-history`,
      listLabel: 'task transition history',
    });
    if (transitionFailure.kind === 'unavailable' || transitionFailure.kind === 'unknown') {
      transitionFailure = {
        ...transitionFailure,
        summary: 'The action result could not be confirmed.',
        recovery: 'Review this task and its transition history before deciding whether to try again.',
      };
    }
  }
}
---

<AppLayout title={`${task.taskNo} · Tasks`} locale="en" direction="ltr">
  <section class="page-head"><div><p class="eyebrow">Task</p><h1>{task.title}</h1><p class="lede">{task.taskNo} · Version {task.version.toString()}</p></div><a href="/tasks">Back to tasks</a></section>
  <div class="grid">
    <section class="panel"><h2>Overview</h2><dl><dt>Owner</dt><dd>{details.ownerDisplayName}</dd><dt>Assignee</dt><dd>{details.assigneeDisplayName}</dd><dt>Priority</dt><dd>{priorityLabel(task.priority)}</dd><dt>Due date</dt><dd>{task.dueAt ? <time datetime={task.dueAt.toISOString()}>{formatDateTime(task.dueAt)}</time> : 'Not set'}</dd><dt>State</dt><dd>{stateLabel(task.state)}</dd><dt>Version</dt><dd>{task.version.toString()}</dd><dt>Next step</dt><dd>{nextStep}</dd></dl><p>{task.description ?? 'No description.'}</p></section>
    <section class="panel"><h2>Checklist</h2>{task.checklist.length ? <ul>{task.checklist.map((item) => <li><span>{item.completed ? 'Complete:' : 'Pending:'}</span> {item.label}{item.required ? ' (required)' : ''}</li>)}</ul> : <p>No checklist items.</p>}</section>
  </div>
    <section class="panel actions"><h2>Available actions</h2><p>State changes require server-side permission, scope, and the current version.</p>{transitionFailure && <FormErrorSummary summary={transitionFailure.summary} recovery={transitionFailure.recovery} errors={Object.entries(transitionFailure.fieldErrors).map(([fieldId, message]) => ({ fieldId, message }))} listHref={`/tasks/${taskId}?reconcile=1#transition-history`} listLabel="task transition history" />}<form method="post" data-task-transition><input type="hidden" name="expectedVersion" value={task.version.toString()} /><input type="hidden" data-action-input value={transitionValues.action} /><label for="reason">Reason <span>(required for hold and reopen)</span></label><textarea id="reason" name="reason" data-reason rows="3" aria-invalid={reasonError() ? 'true' : undefined} aria-describedby={reasonError() ? 'reason-error' : undefined}>{transitionValues.reason}</textarea>{reasonError() && <p class="field-error" id="reason-error">{reasonError()}</p>}{task.state === 'DRAFT' && canTaskAction('PERM-TASK-CREATE') && <button type="submit" name="action" value="ACTIVATE" data-submit>Activate</button>}{task.state === 'OPEN' && canTaskAction('PERM-TASK-EDIT') && <button type="submit" name="action" value="START" data-submit>Start</button>}{(task.state === 'OPEN' || task.state === 'IN_PROGRESS') && canTaskAction('PERM-TASK-BLOCK') && <button type="submit" name="action" value="HOLD" data-submit>Put on hold</button>}{task.state === 'IN_PROGRESS' && canTaskAction('PERM-TASK-COMPLETE') && <button type="submit" name="action" value="COMPLETE" data-submit>Complete</button>}{task.state === 'ON_HOLD' && canTaskAction('PERM-TASK-EDIT') && <button type="submit" name="action" value="RESUME" data-submit>Resume</button>}{task.state === 'COMPLETED' && canTaskAction('PERM-TASK-REOPEN') && <button type="submit" name="action" value="REOPEN" data-submit>Reopen</button>}<p role="status" data-result tabindex="-1"></p></form></section>
  <section class="panel" id="transition-history"><h2>Transition history</h2>{details.history.length ? <ol class="history">{details.history.map((event) => <li><div><strong>{actionLabel(event.action)}</strong><span>{event.oldState || event.newState ? ` · ${event.oldState ? stateLabel(event.oldState) : ''}${event.oldState && event.newState ? ' → ' : ''}${event.newState ? stateLabel(event.newState) : ''}` : ''}</span></div><p><time datetime={event.occurredAt.toISOString()}>{formatDateTime(event.occurredAt)}</time> · {event.actorLabel}{event.reason ? ` · ${event.reason}` : ''}</p></li>)}</ol> : <p>No recorded changes.</p>}</section>
</AppLayout>

<script>
  import { actions } from 'astro:actions';
  import { enhanceClassifiedForm } from '../../ui/forms/enhance-with-classification';
  import { guardUnsavedChanges } from '../../ui/forms/unsaved-changes';
  const validTransitions = ['ACTIVATE', 'START', 'COMPLETE', 'CANCEL', 'RESUME', 'HOLD', 'REOPEN'] as const;
  const currentTaskId = location.pathname.split('/').pop() || '';
  const form = document.querySelector<HTMLFormElement>('[data-task-transition]');
  if (form) {
    const actionInput = form.querySelector<HTMLInputElement>('[data-action-input]');
    const reason = form.querySelector<HTMLTextAreaElement>('[data-reason]');
    form.addEventListener('click', (event) => {
      const button = (event.target as HTMLElement).closest<HTMLButtonElement>('button[name="action"]');
      if (button) {
        if (actionInput) actionInput.value = button.value;
        if (reason) reason.required = button.value === 'HOLD' || button.value === 'REOPEN';
      }
    });
    enhanceClassifiedForm(form, {
      invoke: async (payload) => actions.tasks.transition(payload as Parameters<typeof actions.tasks.transition>[0]),
      payload: (data) => ({ taskId: location.pathname.split('/').pop() || '', expectedVersion: BigInt(String(data.get('expectedVersion') || '0')), action: String(actionInput?.value || data.get('action') || '') as (typeof validTransitions)[number], ...(String(data.get('reason') || '').trim() ? { reason: String(data.get('reason')).trim() } : {}) }),
      progressText: 'Applying the controlled action…',
      detailBaseHref: '/tasks',
      unknownRecoveryHref: `/tasks/${currentTaskId}?reconcile=1#transition-history`,
    });
    guardUnsavedChanges(form);
  }
</script>

<style>
