import AppLayout from '../../ui/layouts/AppLayout.astro';
import AppliedFilters from '../../ui/components/data/AppliedFilters.astro';
import DataTable from '../../ui/components/data/DataTable.astro';
import FilterBar from '../../ui/components/data/FilterBar.astro';
import Pagination from '../../ui/components/data/Pagination.astro';
import ProviderUnavailableState from '../../ui/components/feedback/ProviderUnavailableState.astro';
import { AppError } from '../../shared/errors/app-error.js';
import { actorHasScope } from '../../shared/authorization/scope-evaluator.js';
import type { TaskListItem } from '../../modules/tasks/application/ports/task-list-item.js';
import { taskReadDependencies } from '../../modules/tasks/application/dependencies.js';
import { parsePageInput } from '../../shared/pagination/page.js';
import { formatDate } from '../../shared/copy/format.js';
import { priorityLabel, stateLabel } from '../../shared/copy/ux-vocabulary.js';
const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Ftasks');
const params = Astro.url.searchParams;
const page = parsePageInput({ page: params.get('page'), pageSize: params.get('pageSize') });
const requestedState = params.get('state');
const validStates = ['DRAFT', 'OPEN', 'IN_PROGRESS', 'ON_HOLD', 'COMPLETED', 'CANCELLED'] as const;
const state = validStates.find((value) => value === requestedState);
const search = params.get('q')?.slice(0, 200) || undefined;
// Due-date window and ownership are the same server-side dimensions a dashboard
// action count uses, so "Tasks overdue" opens exactly the set it counted.
const requestedDue = params.get('due');
const due = requestedDue === 'overdue' || requestedDue === 'today' ? requestedDue : undefined;
const ownership = params.get('assignee') === 'mine' ? ('mine' as const) : undefined;
// "Still open" is the same predicate the count uses, so "everything assigned to
// me" is one link instead of one per state and an assigned task with no due
// date is never invisible.
const openOnly = params.get('open') === '1';
const sortKeys = ['updated', 'due', 'priority', 'taskNo'] as const;
const sort = sortKeys.find((value) => value === params.get('sort')) ?? 'updated';
const direction = params.get('direction') === 'asc' ? 'asc' : 'desc';
const canTaskAction = (task: TaskListItem, code: string) => {
  const grant = actor.permissions.find((item) => item.code === code && item.active !== false);
  return Boolean(
    grant &&
      actorHasScope(
        actor,
        { type: 'TASK', id: task.id, state: task.state, ownerId: task.createdBy, assigneeId: task.currentAssigneeId },
        { ownerId: task.createdBy, assigneeId: task.currentAssigneeId },
        grant,
      ),
  );
};
const nextStep = (task: TaskListItem) => ({
  DRAFT: canTaskAction(task, 'PERM-TASK-CREATE') ? 'Activate when the draft is ready' : 'Wait for an authorized user to activate this draft',
  OPEN: canTaskAction(task, 'PERM-TASK-EDIT') ? 'Start the work' : 'Wait for an authorized user to start the work',
  IN_PROGRESS: canTaskAction(task, 'PERM-TASK-COMPLETE') || canTaskAction(task, 'PERM-TASK-BLOCK') ? 'Complete the work or place it on hold with a reason' : 'Wait for an authorized user to complete or hold the work',
  ON_HOLD: canTaskAction(task, 'PERM-TASK-EDIT') ? 'Resume when the blocker is resolved' : 'Wait for an authorized user to resume the work',
  COMPLETED: canTaskAction(task, 'PERM-TASK-REOPEN') ? 'Reopen with permission and a reason if needed' : 'Task complete; reopening requires separate permission',
  CANCELLED: 'No further action is available',
})[task.state] ?? 'Review the task state';
const dueLabels = { overdue: 'Overdue', today: 'Due today' } as const;
// A dependency outage is UNAVAILABLE, not an empty queue and not a zero count.
let providerUnavailable = false;
let authorizationUnavailable = false;
let result: Awaited<ReturnType<ReturnType<typeof taskReadDependencies>['list']['execute']>> = {
  items: [],
  total: 0,
};
try {
  result = await taskReadDependencies().list.execute({
    actor,
    filter: {
      state,
      search,
      due,
      open: openOnly || undefined,
      assigneeId: ownership === 'mine' ? actor.id : undefined,
      sort,
      direction,
    },
    page,
  });
} catch (error) {
  authorizationUnavailable = error instanceof AppError && error.code.startsWith('AUTHZ_');
  providerUnavailable = !authorizationUnavailable;
}
const tasks = result.items;
const totalPages = Math.max(1, Math.ceil(result.total / page.pageSize));
const chipHref = (drop: string) => {
  const next = new URLSearchParams(params);
  next.delete(drop);
  const query = next.toString();
  return `/tasks${query ? `?${query}` : ''}`;
};
const appliedFilters = [
  state && { label: 'State', value: stateLabel(state), href: chipHref('state') },
  due && { label: 'Due', value: dueLabels[due], href: chipHref('due') },
  openOnly && { label: 'Show', value: 'Open work only', href: chipHref('open') },
  ownership && { label: 'Assignee', value: 'Only mine', href: chipHref('assignee') },
  search && { label: 'Search', value: search, href: chipHref('q') },
].filter((chip): chip is { label: string; value: string; href: string } => Boolean(chip));
const hasFilters = appliedFilters.length > 0;
const canCreate = actor.permissions.some(
  (grant) => grant.code === 'PERM-TASK-CREATE' && grant.active !== false,
);
---
<AppLayout title="Tasks · QC Operations" locale="en" direction="ltr">
  <div class="scientific-register">
  <section class="page-head"><div><p class="eyebrow">Work queue</p><h1>Tasks</h1><p class="lede">View operational work. Actions remain limited to your explicit permissions.</p></div>{canCreate && <a class="button" href="/tasks/new">Create task</a>}</section>
  <FilterBar clearHref={hasFilters ? '/tasks' : undefined}>
    <label for="q">Search<input id="q" name="q" type="search" value={search ?? ''} maxlength="200" placeholder="Task number or title" /></label>
    <label for="state">State<select id="state" name="state"><option value="">All states</option>{validStates.map((value) => <option value={value} selected={state === value}>{stateLabel(value)}</option>)}</select></label>
    <label for="due">Due<select id="due" name="due"><option value="">Any due date</option><option value="overdue" selected={due === 'overdue'}>Overdue</option><option value="today" selected={due === 'today'}>Due today</option></select></label>
    <label for="assignee">Assignee<select id="assignee" name="assignee"><option value="">All assignees</option><option value="mine" selected={ownership === 'mine'}>Only mine</option></select></label>
    <label for="open">Show<select id="open" name="open"><option value="">All tasks</option><option value="1" selected={openOnly}>Open work only</option></select></label>
    <label for="sort">Sort by<select id="sort" name="sort"><option value="updated" selected={sort === 'updated'}>Recently updated</option><option value="due" selected={sort === 'due'}>Due date</option><option value="priority" selected={sort === 'priority'}>Priority</option><option value="taskNo" selected={sort === 'taskNo'}>Task number</option></select></label>
    <label for="direction">Direction<select id="direction" name="direction"><option value="desc" selected={direction === 'desc'}>Descending</option><option value="asc" selected={direction === 'asc'}>Ascending</option></select></label>
  </FilterBar>
  <AppliedFilters
    filters={appliedFilters}
    clearHref={hasFilters ? '/tasks' : undefined}
    note={providerUnavailable || authorizationUnavailable
      ? 'The task read is unavailable, so no count is shown.'
      : `Showing ${tasks.length} of ${result.total} in your authorized scope — page ${page.page} of ${totalPages}.`}
  />
  {authorizationUnavailable ? <section class="empty"><h2>Tasks are not available in your permission scope</h2><p>No task data or count is shown for this account.</p></section> : providerUnavailable ? <ProviderUnavailableState title="Tasks are temporarily unavailable" description="The task read did not return a confirmed result, so this queue is not treated as empty and no count is shown." retryHref="/tasks" /> : tasks.length ? <DataTable caption={`Tasks — ${result.total} matching records`} summary={`Showing ${tasks.length} of ${result.total} authorized tasks · page ${page.page} of ${totalPages}. Sorted by ${sort} (${direction}); stable task identity breaks ties.`} density="compact"><thead><tr><th scope="col">Task number</th><th scope="col">Title</th><th scope="col">Owner</th><th scope="col">Priority</th><th scope="col">Assignee</th><th scope="col">Due</th><th scope="col">State</th><th scope="col">Version</th><th scope="col">Next step</th></tr></thead><tbody>{tasks.map((task) => <tr><th scope="row"><a href={`/tasks/${task.id}`}>{task.taskNo}</a></th><td>{task.title}</td><td>{task.ownerDisplayName}</td><td>{priorityLabel(task.priority)}</td><td>{task.assigneeDisplayName}</td><td>{task.dueAt ? <time datetime={task.dueAt.toISOString()}>{formatDate(task.dueAt)}</time> : '—'}</td><td>{stateLabel(task.state)}</td><td>{task.version.toString()}</td><td>{nextStep(task)}</td></tr>)}</tbody><Fragment slot="pagination"><Pagination page={page.page} totalPages={totalPages} total={result.total} itemLabel="tasks" baseUrl="/tasks" /></Fragment></DataTable> : <section class="empty"><h2>{hasFilters ? 'No tasks match these filters' : 'No tasks in your authorized scope'}</h2><p>{hasFilters ? 'Remove a filter to widen the search. The due filter only counts open work: completed and cancelled tasks are never overdue.' : 'Tasks appear here once they are created.'}</p>{hasFilters ? <a href="/tasks">Clear all filters</a> : canCreate && <a href="/tasks/new">Create task</a>}</section>}
  </div>
</AppLayout>
<style>.page-head{display:flex;justify-content:space-between;gap:var(--space-5);align-items:start;margin-bottom:var(--space-6)}h1{margin:.25rem 0}.eyebrow{margin:0;color:var(--text-muted);font-size:var(--font-size-xs);letter-spacing:.12em;font-weight:700}.lede,.empty p{color:var(--text-muted);font-size:.86rem}.button,button{display:inline-flex;align-items:center;justify-content:center;min-height:var(--control-height);border:1px solid var(--color-accent-primary);background:var(--color-accent-primary);color:var(--color-text-inverse);padding:.65rem 1rem;border-radius:var(--radius-md);text-decoration:none;font-weight:700;cursor:pointer}.filters{display:flex;gap:var(--space-4);align-items:end;margin-bottom:var(--space-5);flex-wrap:wrap}label{display:grid;gap:.35rem;font-size:.8rem;color:var(--text-secondary)}input,select{min-height:2.5rem;padding:.5rem;background:var(--surface-panel);color:inherit;border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm)}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;background:var(--surface-panel)}caption{text-align:start;padding:var(--space-4);color:var(--text-muted)}th,td{padding:.75rem;text-align:start;border-top:1px solid var(--color-border-subtle)}th{font-weight:700}a{color:var(--color-accent-primary-hover)}.empty{margin-top:var(--space-5);padding:var(--space-8);text-align:center;background:var(--surface-panel);border:1px dashed var(--color-border-strong);border-radius:var(--radius-lg)}.empty h2{margin:0 0 .5rem;font-size:1.1rem}@media(max-width:600px){.page-head,.filters{display:grid}.filters button{width:max-content}}
</style>

---
import AppLayout from '../../ui/layouts/AppLayout.astro';
import FormErrorSummary from '../../ui/components/FormErrorSummary.astro';
import { actions } from 'astro:actions';
import {
  detailHref,
  extractDetailId,
  field,
  toFormFailure,
  type FormFailure,
} from '../../ui/forms/mutation-post.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Ftasks%2Fnew');
const canCreate = actor.permissions.some(
  (grant) => grant.code === 'PERM-TASK-CREATE' && grant.active !== false,
);

const LIST_HREF = '/tasks';
const REQUIRED_FIELDS = [
  { name: 'taskNo', label: 'Task number' },
  { name: 'title', label: 'Title' },
] as const;

let values = { taskNo: '', title: '', description: '', priority: '', dueAt: '' };
let failure: FormFailure | null = null;

// POST baseline (F-05): without JavaScript the form performs a real POST to
// this page. The same Astro Action — with the same server-side
// reauthorization — runs via Astro.callAction. No business payload enters
// the URL: input travels in the POST body, success redirects (303) to the
// new record only.
if (Astro.request.method === 'POST' && canCreate) {
  const formData = await Astro.request.formData();
  const dueRaw = field(formData, 'dueAt');
  values = {
    taskNo: field(formData, 'taskNo'),
    title: field(formData, 'title'),
    description: field(formData, 'description'),
    priority: field(formData, 'priority') || 'UNSPECIFIED',
    dueAt: dueRaw,
  };
  try {
    const data = await Astro.callAction(actions.tasks.createTask, {
      taskNo: values.taskNo,
      title: values.title,
      description: values.description || undefined,
      priority: values.priority,
      ...(dueRaw ? { dueAt: new Date(dueRaw) } : {}),
    });
    const id = extractDetailId(data);
    if (id) return Astro.redirect(detailHref(LIST_HREF, id), 303);
    failure = {
      kind: 'unknown',
      summary: 'The task was received but no record reference came back.',
      recovery: 'Check the task list before trying again to avoid a duplicate.',
      fieldErrors: {},
      firstInvalidField: null,
    };
  } catch (error) {
    failure = toFormFailure(error, {
      entity: 'Task',
      requiredFields: REQUIRED_FIELDS,
      values,
      listHref: LIST_HREF,
      listLabel: 'tasks',
    });
  }
}

const describedBy = (name: keyof typeof values): string | undefined =>
  failure?.fieldErrors[name] ? `${name}-error` : undefined;
const invalid = (name: keyof typeof values): 'true' | undefined =>
  failure?.fieldErrors[name] ? 'true' : undefined;
---
<AppLayout title="Create task · QC Operations" locale="en" direction="ltr"><section class="page-head"><p class="eyebrow">Work queue</p><h1>Create task</h1><p class="lede">New tasks start as controlled drafts.</p></section>{canCreate ? <form class="form" method="post" data-task-create><div class="actions-top"><a href="/tasks">Back to tasks</a></div>{failure && <FormErrorSummary summary={failure.summary} recovery={failure.recovery} errors={Object.entries(failure.fieldErrors).map(([fieldId, message]) => ({ fieldId, message }))} listHref={LIST_HREF} listLabel="tasks" />}<section class="draft-summary" aria-label="Draft details"><h2>After saving</h2><dl><dt>Owner</dt><dd>You (signed-in account)</dd><dt>Priority</dt><dd>Entered value, or Not specified</dd><dt>Due date</dt><dd>Selected date, or Not set</dd><dt>State</dt><dd>Draft</dd><dt>Version</dt><dd>1</dd><dt>Next step</dt><dd>Activate the draft when it is ready</dd></dl><p>Transition history appears after a state change.</p></section><label for="taskNo">Task number<span class="hint" id="taskNo-help">Use the task number from your approved source. Reference numbers are assigned automatically.</span><input id="taskNo" name="taskNo" required value={values.taskNo} aria-invalid={invalid('taskNo')} aria-describedby={failure?.fieldErrors.taskNo ? 'taskNo-error taskNo-help' : 'taskNo-help'} /></label>{failure?.fieldErrors.taskNo && <p class="field-error" id="taskNo-error">{failure.fieldErrors.taskNo}</p>}<label for="title">Title<input id="title" name="title" required value={values.title} aria-invalid={invalid('title')} aria-describedby={describedBy('title')} /></label>{failure?.fieldErrors.title && <p class="field-error" id="title-error">{failure.fieldErrors.title}</p>}<label for="description">Description<textarea id="description" name="description" aria-invalid={invalid('description')} aria-describedby={describedBy('description')}>{values.description}</textarea></label>{failure?.fieldErrors.description && <p class="field-error" id="description-error">{failure.fieldErrors.description}</p>}<label for="priority">Priority<span class="hint" id="priority-help">Leave blank when no priority has been assigned. The saved value will be shown as “Not specified”.</span><input id="priority" name="priority" placeholder="Not specified" value={values.priority === 'UNSPECIFIED' ? '' : values.priority} aria-invalid={invalid('priority')} aria-describedby={failure?.fieldErrors.priority ? 'priority-error priority-help' : 'priority-help'} /></label>{failure?.fieldErrors.priority && <p class="field-error" id="priority-error">{failure.fieldErrors.priority}</p>}<label for="dueAt">Due date<input id="dueAt" name="dueAt" type="datetime-local" value={values.dueAt} aria-invalid={invalid('dueAt')} aria-describedby={describedBy('dueAt')} /></label>{failure?.fieldErrors.dueAt && <p class="field-error" id="dueAt-error">{failure.fieldErrors.dueAt}</p>}<div class="actions"><a href="/tasks">Cancel</a><button type="submit" data-submit>Save draft</button></div><p role="status" data-result tabindex="-1"></p></form> : <p class="empty">You are not authorized to create tasks.</p>}</AppLayout>
<script>
  import { actions } from 'astro:actions';
  import { enhanceClassifiedForm } from '../../ui/forms/enhance-with-classification';
  import { guardUnsavedChanges } from '../../ui/forms/unsaved-changes';
  const form = document.querySelector<HTMLFormElement>('[data-task-create]');
  if (form) {
    enhanceClassifiedForm(form, {
      invoke: async (payload) => actions.tasks.createTask(payload as Parameters<typeof actions.tasks.createTask>[0]),
      payload: (data) => {
        const dueAt = String(data.get('dueAt') ?? '');
        return {
          taskNo: String(data.get('taskNo') ?? ''),
          title: String(data.get('title') ?? ''),
          description: String(data.get('description') ?? '') || undefined,
          priority: String(data.get('priority') || 'UNSPECIFIED'),
          ...(dueAt ? { dueAt: new Date(dueAt) } : {}),
        };
      },
      progressText: 'Saving task draft…',
      detailBaseHref: '/tasks',
      unknownRecoveryHref: '/tasks',
    });
    guardUnsavedChanges(form);
  }
</script>
<style>.page-head{margin-bottom:var(--space-6)}.eyebrow{margin:0;color:var(--text-muted);font-size:.7rem;letter-spacing:.12em;font-weight:700}h1{margin:.25rem 0}.lede,.empty,.hint,.draft-summary p{color:var(--text-muted)}.form{display:grid;gap:var(--space-4);max-width:720px;padding:var(--space-5);background:var(--surface-panel);border:1px solid var(--color-border-subtle);border-radius:var(--radius-lg)}.draft-summary{padding:var(--space-4);border:1px solid var(--color-border-subtle);border-radius:var(--radius-md)}.draft-summary h2{margin:0 0 var(--space-3);font-size:1rem}.draft-summary dl{display:grid;grid-template-columns:minmax(7rem,auto) 1fr;gap:.5rem 1rem;margin:0}.draft-summary dt{color:var(--text-muted)}.draft-summary dd{margin:0;font-weight:600}.draft-summary p{margin-bottom:0}label{display:grid;gap:.4rem;font-size:.85rem}input,textarea{font:inherit;padding:.7rem;background:var(--surface-page);color:inherit;border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm)}input[aria-invalid="true"],textarea[aria-invalid="true"]{border-color:var(--status-danger)}.field-error{margin:0;color:var(--status-danger);font-size:.8rem}textarea{min-height:8rem}.actions,.actions-top{display:flex;gap:var(--space-3);align-items:center;flex-wrap:wrap}button{border:0;padding:.7rem 1rem;background:var(--color-accent-primary);color:#fff;border-radius:var(--radius-md);font-weight:700}button[disabled]{opacity:.6}a{color:var(--color-accent-primary-hover)}
</style>

---
import AppLayout from '../../ui/layouts/AppLayout.astro';
import StatusBadge from '../../ui/components/StatusBadge.astro';
import ProviderUnavailableState from '../../ui/components/feedback/ProviderUnavailableState.astro';
import { myWorkDependencies } from '../../modules/dashboard/application/dependencies.js';
import { AppError } from '../../shared/errors/app-error.js';
import { formatDateTime } from '../../shared/copy/format.js';
import { actorRoleLabel } from '../../shared/authorization/scope-description.js';

const actor = Astro.locals.actor;
if (!actor) return Astro.redirect('/login?returnTo=%2Fwork');
// Nothing is rendered until the server confirms the queue: a failed read
// withholds the whole workspace instead of drawing an empty "all clear", and an
// authorization refusal is a different fact from a provider outage.
let queue: Awaited<ReturnType<ReturnType<typeof myWorkDependencies>['get']['execute']>> | undefined;
let providerUnavailable = false;
let authorizationUnavailable = false;
try {
  queue = await myWorkDependencies().get.execute(actor);
} catch (error) {
  authorizationUnavailable = error instanceof AppError && error.category === 'AUTHORIZATION';
  providerUnavailable = !authorizationUnavailable;
}
const groups = queue?.groups ?? [];
const unresolved = queue?.unresolvedSources ?? [];
---
<AppLayout title="My work today · QC Operations" locale="en" direction="ltr" scope={queue?.scopeLabel}>
  <section class="page-head">
    <div>
      <p class="eyebrow">YOUR QUEUE</p>
      <h1>My work today</h1>
      <p class="lede">Work the registers record as yours, grouped by the question you are asking: what is assigned to me, what is due today, what is past due, and what is blocked. Every group names the register it was read from, the reason the record is waiting, the next action and the role that owns it. Opening a record changes nothing — the server still decides whether you may act.</p>
    </div>
    {queue && <p class="snapshot"><time datetime={queue.generatedAt.toISOString()}>Server snapshot · {formatDateTime(queue.generatedAt)}</time><span>All windows in {queue.timezone}</span><a href="/work">Refresh</a></p>}
  </section>

  <section class="identity" aria-label="Your authenticated identity">
    <p><span>Signed in as</span> <strong>{actor.loginIdentity ?? 'Your account'}</strong></p>
    <p><span>Role</span> <strong>{actorRoleLabel(actor)}</strong></p>
    <p><span>Scope</span> <strong>{queue?.scopeLabel ?? 'Not confirmed'}</strong></p>
  </section>

  {providerUnavailable && <ProviderUnavailableState title="Your work queue is temporarily unavailable" description="A register did not return a confirmed read, so every group and count is withheld." retryHref="/work" />}
  {authorizationUnavailable && <section class="empty" role="status"><h2>Your work queue is unavailable</h2><p>This account cannot view the requested queue. No record or count is shown.</p></section>}

  {!providerUnavailable && queue && (
    <>
      <p class="explainer">A record can belong to more than one group — one task can be both assigned to you and past its due date — so a group count is that group's own question, not a share of a total. Each record is listed once, under its most urgent group.</p>
      {groups.map((group) => (
        <section class="panel" aria-labelledby={`group-${group.definition.category}`}>
          <div class="panel-head">
            <div>
              <h2 id={`group-${group.definition.category}`}>{group.definition.label}</h2>
              <p class="membership">{group.definition.membership}</p>
            </div>
            <p class="group-count">
              {group.count === null ? <span class="no-count">No total for your account</span> : <><strong>{group.count}</strong><span>record{group.count === 1 ? '' : 's'}</span></>}
            </p>
          </div>
          <p class="state-message" role="status">{group.message}</p>
          <details class="lineage">
            <summary>How this group is counted</summary>
            <dl class="definition">
              <div><dt>Ownership</dt><dd>{group.definition.ownership}</dd></div>
              <div><dt>Scope</dt><dd>{group.definition.actorScope}</dd></div>
              <div><dt>Time basis</dt><dd>{group.definition.timezone}; {group.definition.sourceTimestamp}</dd></div>
              <div><dt>Included records</dt><dd>{group.definition.predicate}</dd></div>
            </dl>
            {group.registerLinks.length > 0 && (
              <p class="links">
                <span>Source registers:</span>
                {group.registerLinks.map((link) => <a href={link.href}>{link.label} ({link.count})</a>)}
              </p>
            )}
          </details>
          {group.items.length > 0 ? (
            <ul class="queue">
              {group.items.map((item) => (
                <li>
                  <a class="item" href={item.href}>
                    <span class="item-main">
                      <strong>{item.title}</strong>
                      <small>{item.reason}</small>
                    </span>
                    <span class="item-meta">
                      <small class="age">{item.ageLabel} · {item.state}</small>
                      <small>Next: {item.nextAction}</small>
                      <small>Owner: {item.responsibleRole}</small>
                      <small class="source">From: {item.sourceLabel}</small>
                    </span>
                    <StatusBadge status={item.severity} />
                  </a>
                </li>
              ))}
            </ul>
          ) : null}
        </section>
      ))}

      <section class="panel unresolved" aria-labelledby="unresolved-title">
        <div class="panel-head"><div><h2 id="unresolved-title">What this queue cannot answer yet</h2><p class="membership">Each entry names the real missing piece and who owns it.</p></div></div>
        <ul>
          {unresolved.map((source) => (
            <li>
              <strong>{source.label}</strong>
              <span>{source.reason}</span>
              <small>Owner: {source.owner}</small>
            </li>
          ))}
        </ul>
        <p class="empty">Missing evidence is never converted into completion: a group with no source says so rather than showing a zero.</p>
      </section>

      <section class="panel note"><strong>PASS and Released are separate</strong><p>A scientific PASS is an inspection result, not a release decision. A receiving item on HOLD cannot be released by any of these links.</p></section>
    </>
  )}
</AppLayout>
