  .ui-button { min-height: var(--control-height); display: inline-flex; align-items: center; justify-content: center; gap: var(--button-gap); padding-inline: var(--button-padding-inline); border: 1px solid transparent; border-radius: var(--button-radius); font-weight: var(--button-font-weight); text-align: center; cursor: pointer; }
