</style>

---
/**
 * Visible, keyboard-focusable error summary for server-rendered mutation
 * forms (F-04). Rendered only after a failed POST; a small progressive
 * script moves keyboard focus straight to the problem while no-JS keeps
 * the top-level summary plus anchor links to each field.
 * Recovery always names a next step and links back to the safe list.
 */
interface Props {
  summary: string;
  recovery?: string | null;
  listHref: string;
  listLabel: string;
  errors?: Array<{ fieldId: string; message: string }>;
}
const { summary, recovery = null, listHref, listLabel, errors = [] } = Astro.props;
---
<section
  class="form-error"
  role="alert"
  tabindex="-1"
  data-error-summary
  aria-labelledby="form-error-title"
>
  <h2 id="form-error-title">There is a problem</h2>
  <p class="summary">{summary}</p>
  {errors.length > 0 && (
    <ul class="error-links">
      {errors.map((item) => (
        <li><a href={`#${item.fieldId}`}>{item.message}</a></li>
      ))}
    </ul>
  )}
  {recovery && <p class="recovery">{recovery}</p>}
  <p class="back"><a href={listHref}>Back to {listLabel}</a></p>
</section>
<script>
  // Progressive enhancement only: server rendering already places the summary
  // at the top of the form with anchor links to each field. When JavaScript is
  // available, move keyboard focus to the summary after a failed POST so
  // keyboard and screen-reader users find it immediately (no-JS still works).
  const summary = document.querySelector<HTMLElement>('[data-error-summary]');
  summary?.focus({ preventScroll: false });
</script>
<style>
  .form-error {
    padding: var(--space-5);
    background: var(--surface-panel);
    border: 1px solid var(--color-border-subtle);
    border-inline-start: 3px solid var(--status-danger);
    border-radius: var(--radius-lg);
  }
  .form-error:focus {
    outline: 2px solid var(--color-accent-primary);
    outline-offset: 2px;
  }
  .form-error h2 {
    margin: 0 0 0.5rem;
    font-size: 1rem;
  }
  .form-error p {
    margin: 0.25rem 0;
    color: var(--text-secondary);
    font-size: 0.85rem;
  }
  .form-error .summary {
    color: var(--text-primary);
    font-weight: 600;
  }
  .form-error a {
    color: var(--color-accent-primary-hover);
  }
  .form-error .error-links {
    margin: 0.5rem 0;
    padding-inline-start: 1.1rem;
    display: grid;
    gap: 0.25rem;
    font-size: 0.85rem;
  }
</style>

