---
<div class:list={['state-banner', `state-banner--${tone}`]} role={role}><strong>{title}</strong>{message ? <span>{message}</span> : null}<slot /></div>
<style>
  .state-banner { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-3); padding: var(--space-3) var(--space-4); border: 1px solid currentColor; border-radius: var(--radius-sm); }
  .state-banner--info { color: var(--status-review); background: var(--status-review-bg); } .state-banner--success { color: var(--status-approved); background: var(--status-approved-bg); } .state-banner--warning { color: var(--status-warning); background: var(--status-warning-bg); } .state-banner--danger { color: var(--status-danger); background: var(--status-danger-bg); }
</style>

---
type Status = 'PASS' | 'RELEASED' | 'APPROVED' | 'HOLD' | 'WARNING' | 'CRITICAL' | 'INFO' | 'FAIL' | 'REJECTED' | 'REVIEW' | 'DRAFT' | 'VOID' | 'SUPERSEDED' | 'STALE' | 'READ_ONLY';
interface Props { status: Status; label?: string; }
const { status, label = status } = Astro.props;
const tone = status === 'PASS' ? 'pass' : status === 'RELEASED' ? 'released' : ['APPROVED'].includes(status) ? 'approved' : ['STALE'].includes(status) ? 'stale' : ['HOLD', 'WARNING'].includes(status) ? 'warning' : ['FAIL', 'REJECTED', 'VOID', 'CRITICAL'].includes(status) ? 'danger' : ['REVIEW'].includes(status) ? 'review' : 'neutral';
---
<span class:list={['status-badge', `status-badge--${tone}`]} title={status === 'VOID' ? 'VOID means the record remains in history; it has not been deleted.' : undefined} aria-label={status === 'VOID' ? `${label}. The record remains in history; it has not been deleted.` : undefined}><span class="status-mark" aria-hidden="true"></span><span>{label}</span></span>
<style>
  .status-badge { display: inline-flex; align-items: center; gap: var(--space-2); min-height: 28px; padding-inline: var(--space-2) var(--space-3); border: 1px solid currentColor; border-radius: 999px; font-size: .8125rem; font-weight: 600; }
  .status-mark { width: 7px; height: 7px; flex: 0 0 auto; border-radius: 50%; background: currentColor; }
  .status-badge--pass { color: var(--status-pass); background: var(--status-pass-bg); }
  .status-badge--released { color: var(--status-released); background: var(--status-released-bg); }
  .status-badge--approved { color: var(--status-approved); background: var(--status-approved-bg); }
  .status-badge--warning { color: var(--status-warning); background: var(--status-warning-bg); }
  .status-badge--danger { color: var(--status-danger); background: var(--status-danger-bg); }
  .status-badge--review { color: var(--status-review); background: var(--status-review-bg); }
  .status-badge--neutral { color: var(--status-neutral); background: var(--status-neutral-bg); }
  .status-badge--stale { color: var(--status-stale); background: var(--status-stale-bg); }
</style>

---
// Decorative-only treatment for authenticated operational workspaces.
//
// Owner decision (QC-100-FINAL-016 remediation): the dotLottie layer is dropped.
// It could never render under the production CSP (`default-src 'self'` without
// `unsafe-eval` blocks the WASM player), so every authenticated page paid four
// console errors plus ~2.4 MB of discarded transfer. The approved gradient +
// grid treatment below is the whole background: zero script, zero extra
// requests, and it is the same first frame the player used to fall back to.
---
<div class="system-background" data-system-background aria-hidden="true" data-motion="static"></div>

<style>
  .system-background {
    position: fixed;
    inset: 0;
    z-index: 0;
    width: 100vw;
    height: 100vh;
    overflow: hidden;
    pointer-events: none;
    background:
      radial-gradient(60% 75% at 18% 14%, rgb(109 158 103 / 8%), transparent 66%),
      radial-gradient(55% 70% at 92% 86%, rgb(80 112 82 / 7%), transparent 72%),
      var(--color-canvas-deep);
  }

  .system-background::before,
  .system-background::after {
    position: absolute;
    inset: 0;
    content: '';
    pointer-events: none;
  }

  .system-background::before {
    opacity: 0.28;
    background-image: linear-gradient(rgb(255 255 255 / 2%) 1px, transparent 1px),
      linear-gradient(90deg, rgb(255 255 255 / 2%) 1px, transparent 1px);
    background-size: 56px 56px;
    mask-image: linear-gradient(to bottom, black, transparent 82%);
  }

  .system-background::after {
    z-index: 2;
    background: rgb(16 19 16 / 72%);
  }

  @media print {
    .system-background { display: none; }
  }
</style>

---
interface Props { label: string; }
const { label } = Astro.props;
---
<span class="tooltip-wrap"><slot /><span class="tooltip" role="tooltip">{label}</span></span>
<style>
  .tooltip-wrap { position: relative; display: inline-flex; }
  .tooltip { position: absolute; inset-block-start: calc(100% + var(--space-2)); inset-inline-start: 50%; z-index: 5; width: max-content; max-width: 240px; padding: var(--space-2) var(--space-3); transform: translateX(-50%); visibility: hidden; opacity: 0; background: var(--surface-popover); border: 1px solid var(--border-default); border-radius: var(--radius-sm); color: var(--text-primary); font-size: .8125rem; pointer-events: none; }
  .tooltip-wrap:hover .tooltip, .tooltip-wrap:focus-within .tooltip { visibility: visible; opacity: 1; }
  [dir="rtl"] .tooltip { transform: translateX(50%); }
</style>

---
interface FilterChip {
  label: string;
  value: string;
  /** Link that removes this single filter while preserving the others. */
  href: string;
}
interface Props {
  filters?: readonly FilterChip[];
  clearHref?: string;
  /** Shown when no filter is applied, e.g. “Showing everything in your scope”. */
  note?: string;
}
const { filters = [], clearHref, note } = Astro.props;
---
{
  filters.length ? (
    <div class="applied-filters" role="group" aria-label="Applied filters">
      <span class="applied-label">Filtered by</span>
      <ul>
        {filters.map((filter) => (
          <li>
            <a
              href={filter.href}
              aria-label={`Remove filter ${filter.label}: ${filter.value}`}
            >
              <span class="chip-label">{filter.label}</span>
              <span class="chip-value">{filter.value}</span>
              <span class="chip-remove" aria-hidden="true">
                ×
              </span>
            </a>
          </li>
        ))}
      </ul>
      {clearHref && (
        <a class="clear-filters" href={clearHref}>
          Clear all filters
        </a>
      )}
    </div>
  ) : note ? (
    <p class="filter-note">{note}</p>
  ) : null
}
<style>
  .applied-filters {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-3);
    margin-bottom: var(--space-4);
    font-size: 0.8125rem;
  }
  .applied-label {
    color: var(--text-muted);
  }
  .applied-filters ul {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
    list-style: none;
    margin: 0;
    padding: 0;
  }
  .applied-filters a {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    min-height: 32px;
    padding-inline: 10px;
    border: 1px solid var(--border-default);
    border-radius: 999px;
    background: var(--surface-raised);
    color: var(--text-primary);
    text-decoration: none;
  }
  .chip-label {
    color: var(--text-muted);
  }
  .chip-value {
    font-weight: 600;
  }
  .chip-remove {
    font-size: 0.875rem;
    line-height: 1;
    color: var(--text-muted);
  }
  .applied-filters a:hover .chip-remove,
  .applied-filters a:focus-visible .chip-remove {
    color: var(--status-danger);
  }
  .clear-filters {
    color: var(--color-accent-primary-hover);
    text-decoration: underline;
  }
  .filter-note {
    margin: 0 0 var(--space-4);
    color: var(--text-muted);
    font-size: 0.8125rem;
  }
</style>

---
interface Props { caption: string; summary?: string; density?: 'standard' | 'compact' | 'comfortable'; empty?: boolean; }
const { caption, summary, density = 'standard', empty = false } = Astro.props;
---
<section class="data-panel" data-density={density}>
  <div class="table-context"><div><h2>{caption}</h2>{summary && <p>{summary}</p>}</div><label class="density-control">Row density<select aria-label="Row density" data-density-choice><option value="comfortable" selected={density === 'comfortable'}>Comfortable</option><option value="standard" selected={density === 'standard'}>Standard</option><option value="compact" selected={density === 'compact'}>Compact</option></select></label><slot name="count" /></div>
  <slot name="toolbar" />
  <p class="bulk-note" role="note"><slot name="bulk-action">Bulk actions: none are available for this register. Open a row to use its authorized, audited actions.</slot></p>
  {empty ? <slot name="empty" /> : <div class="table-scroll"><table><caption class="visually-hidden">{caption}</caption><slot /></table></div>}
  <slot name="pagination" />
</section>
<style>
  .data-panel { background: var(--surface-panel); border: 1px solid var(--color-border-subtle); border-radius: var(--card-radius); overflow: hidden; }
  .table-context { display: flex; justify-content: space-between; align-items:center; gap: var(--space-4); padding: var(--space-5) var(--space-5) var(--space-3); }
  .density-control { display:inline-flex; align-items:center; gap:var(--space-2); color:var(--text-muted); font-size:var(--font-size-xs); }
  .density-control select { min-height:var(--control-height); padding-inline:var(--space-2); color:var(--text-primary); background:var(--surface-panel); border:1px solid var(--border-default); border-radius:var(--radius-sm); font:inherit; }
  .bulk-note { margin:0; padding:var(--space-2) var(--space-5); color:var(--text-muted); font-size:var(--font-size-xs); }
  h2 { margin: 0; color: var(--text-primary); font-size: var(--font-size-lg); }
  p { margin: var(--space-1) 0 0; color: var(--text-muted); font-size: var(--font-size-xs); }
  .table-scroll { overflow-x: auto; }
  table { width: 100%; border-collapse: collapse; min-width: 680px; color: var(--text-secondary); font-size: var(--font-size-sm); }
  th, td { padding: var(--table-cell-padding-block) var(--table-cell-padding-inline); border-block-end: 1px solid var(--color-border-subtle); text-align: start; vertical-align: middle; }
  th { background: var(--table-header-background); color: var(--text-primary); font-size: var(--font-size-xs); font-weight: var(--font-weight-semibold); white-space: nowrap; }
  tbody tr:nth-child(even) { background: var(--table-stripe-background); }
  tbody tr:hover { background: var(--color-surface-hover); }
  tbody tr:focus-within { outline: var(--focus-width) solid var(--focus-ring); outline-offset: -2px; }
  .visually-hidden { position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; }
  @media (max-width: 760px) { .table-context { padding: var(--space-4); } .table-scroll { margin-inline: 0; } }
</style>
<script>
  const preferenceKey = 'qc.register-density';
  const panels = Array.from(document.querySelectorAll<HTMLElement>('.data-panel'));
  const allowed = new Set(['comfortable', 'standard', 'compact']);
  let saved = null;
  try { saved = localStorage.getItem(preferenceKey); } catch { /* Storage can be unavailable in private contexts. */ }
  if (saved && allowed.has(saved)) {
    for (const panel of panels) {
      panel.dataset.density = saved;
      const select = panel.querySelector<HTMLSelectElement>('[data-density-choice]');
      if (select) select.value = saved;
    }
  }
  for (const panel of panels) {
    panel.querySelector<HTMLSelectElement>('[data-density-choice]')?.addEventListener('change', (event) => {
      const value = (event.currentTarget as HTMLSelectElement).value;
      if (!allowed.has(value)) return;
      for (const sibling of panels) {
        sibling.dataset.density = value;
        const select = sibling.querySelector<HTMLSelectElement>('[data-density-choice]');
        if (select) select.value = value;
      }
      try { localStorage.setItem(preferenceKey, value); } catch { /* The setting still applies for this page view. */ }
    });
  }
</script>

