import type { MutationState } from './mutation-interaction.js';

/**
 * Failure copy for the controlled administration journey.
 *
 * The server never sends a stack trace, SQL text, or secret; it sends a
 * canonical error code that the shared classifier turns into one of these
 * states. Each state gets its own message so an operator can tell a stale
 * record apart from an authorization change, a duplicate, or a missing
 * dependency instead of one generic "the change was not applied".
 */
export interface AdminFailureContext {
  /** Human-readable operation, for example `Remove role`. */
  operation: string;
  /** Human-readable target, for example `verify-user — USER`. */
  subject: string;
}

export const STALE_VERSION_MESSAGE =
  'This user record changed after you opened it. Refresh the latest data before trying again. Nothing was resubmitted.';

export function adminFailureMessage(state: MutationState, context: AdminFailureContext): string {
  const { operation, subject } = context;
  switch (state) {
    case 'CONFLICT_STALE':
      return STALE_VERSION_MESSAGE;
    case 'DUPLICATE_COMMAND':
      return `${operation} for ${subject} was already applied. Reload the record to see the current state — nothing was duplicated.`;
    case 'AUTHORIZATION_CHANGED':
      return `${operation} was not completed. Refresh the page or return to the list, then try again if you still have access.`;
    case 'VALIDATION_ERROR':
      return `${operation} for ${subject} was not applied. Review the highlighted entries and try again. Your entries are preserved.`;
    case 'DEPENDENCY_UNAVAILABLE':
      return `${operation} was not completed. Refresh the page or return to the list, then try again if you still have access.`;
    default:
      return `${operation} for ${subject} was not applied. Nothing was changed — try again, or reload the record.`;
  }
}

export function isStaleVersionState(state: MutationState): boolean {
  return state === 'CONFLICT_STALE';
}

/**
 * QC-100-FINAL-037-A — server-derived failure states on every enhanced form.
 *
 * This shared client module attaches one submit listener to a create/mutation
 * form that:
 *
 *  1. guards duplicates and shows progress through `aria-busy` + `[data-result]`
 *     (identical to the existing per-page handlers, no behavior regression);
 *  2. invokes the Astro Action the page passes in (`invoke`);
 *  3. classifies the actual server result with the canonical
 *     `classifyActionResult` contract (`mutation-interaction.ts`);
 *  4. writes the approved vocabulary copy for that exact class
 *     (`ux-vocabulary.ts errorClasses`), so a permission denial, a stale
 *     record, a dependency outage, and a validation failure each render their
 *     own message — never one generic failure text.
 *
 * Presentation only: no business rules, no policy values, no authorization
 * logic, and no optimistic regulated outcome. The form keeps its no-JS POST
 * baseline; without JavaScript the server POST still applies and the failed
 * POST re-render carries the FormErrorSummary.
 */
import {
  classifyActionResult,
  type MutationOutcome,
  type MutationState,
} from './mutation-interaction';
import { FORM_COMMITTED_EVENT } from './unsaved-changes';
import { copy } from '../../shared/copy/ux-vocabulary';

export interface FormEnhanceConfig<TData> {
  /** The page's Astro Action call, e.g. `(payload) => actions.assets.createEquipment(payload)`. */
  invoke: (
    payload: Record<string, unknown>,
  ) => Promise<{ data?: TData; error?: unknown } | undefined>;
  /** Builds the Action input from form data (transport only). */
  payload: (data: FormData) => Record<string, unknown>;
  /** Progress copy written to [data-result] while the action is in flight. */
  progressText: string;
  /** Detail route prefix for the created record, e.g. `/assets/equipment`. */
  detailBaseHref: string;
  /** Existing record/history route used to reconcile an unknown commit before retry. */
  unknownRecoveryHref?: string;
  /**
   * On SUCCESS the default navigates to `${detailBaseHref}/${recordId}`.
   * Provide to override only when the page needs a different behavior.
   */
  onSuccess?: (outcome: MutationOutcome, form: HTMLFormElement) => void;
}

/**
 * Focus the first invalid field the browser natively flags; otherwise focus
 * the status region so keyboard and screen-reader users land on the message.
 */
function focusFirstInvalid(form: HTMLFormElement, output: HTMLElement | null): void {
  const firstInvalid = form.querySelector<HTMLElement>(
    'select:invalid,input:invalid,textarea:invalid',
  );
  (firstInvalid ?? output)?.focus?.();
}

/**
 * Attach the classified-failure contract to one form. Idempotent via a
 * dataset flag; safe to call once per page. The status region must exist in
 * markup (`[data-result]`) so screen readers always have the live target.
 */
export function enhanceClassifiedForm<TData>(
  form: HTMLFormElement,
  config: FormEnhanceConfig<TData>,
): void {
  if (form.dataset.enhance === 'classified') return;
  form.dataset.enhance = 'classified';

  form.addEventListener('submit', async (event: Event) => {
    event.preventDefault();
    if (form.getAttribute('aria-busy') === 'true') return;

    const submit = form.querySelector<HTMLButtonElement>('[data-submit], button[type="submit"]');
    const output = form.querySelector<HTMLElement>('[data-result]');

    form.setAttribute('aria-busy', 'true');
    if (submit) submit.disabled = true;
    if (output) output.textContent = config.progressText;

    try {
      const payload = config.payload(new FormData(form));
      const result = await config.invoke(payload);
      const outcome = classifyActionResult(result);

      if (outcome.state === 'SUCCESS') {
        // The record was committed: notify unsaved-change guards before the
        // intentional navigation so they do not warn about a successful save.
        form.dispatchEvent(new CustomEvent(FORM_COMMITTED_EVENT));
        if (config.onSuccess) {
          config.onSuccess(outcome, form);
          return;
        }
        if (outcome.recordId) {
          window.location.href = `${config.detailBaseHref}/${outcome.recordId}`;
          return;
        }
        window.location.reload();
        return;
      }

      if (output) {
        const classKey = outcome.state as Exclude<MutationState, 'IDLE' | 'SUBMITTING' | 'SUCCESS'>;
        output.textContent = copy.errorClasses[classKey] ?? copy.errorClasses.UNKNOWN_SAFE_ERROR;
        if (outcome.state === 'UNKNOWN_SAFE_ERROR') {
          const link = document.createElement('a');
          link.href = config.unknownRecoveryHref ?? config.detailBaseHref;
          link.textContent = 'Review the record before retrying';
          output.append(' ', link);
        }
        if (outcome.state === 'VALIDATION_ERROR') focusFirstInvalid(form, output);
        else output?.focus?.();
      }
    } catch {
      // Transport failure has an unknown commit outcome. Keep entries and
      // require a record/history read before the operator decides to retry.
      if (output) {
        output.textContent = copy.errorClasses.UNKNOWN_SAFE_ERROR;
        const link = document.createElement('a');
        link.href = config.unknownRecoveryHref ?? config.detailBaseHref;
        link.textContent = 'Review the record before retrying';
        output.append(' ', link);
        output?.focus?.();
      }
    } finally {
      form.removeAttribute('aria-busy');
      if (submit) submit.disabled = false;
    }
  });
}

/**
 * Presentation-only helpers for authorized entity selectors (F-06 / F-09).
 *
 * These helpers do transport shaping and safe-navigation checks only. They
 * contain no business rules, no SQL, no policy values, and no authorization
 * logic: option lists are loaded server-side in Astro frontmatter through
 * application use cases (which reauthorize via `Astro.locals.actor`), and
 * every mutation still reauthorizes inside its Astro Action and use case.
 *
 * Business identifiers (`taskNo`, `labTestNo`, …) stay operator-supplied
 * from the approved offline source: no approved server-side numbering policy
 * exists in this baseline (see DATA-DICTIONARY DD-008 and BUSINESS-RULES
 * BD-013, both open), so this file must not invent a numbering scheme.
 * Technical UUIDs are already generated server-side only (`uuidv7()` inside
 * application use cases); Action input schemas accept no client `id`.
 */
export interface SelectOption {
  /** Technical identifier kept as the option value (hidden after selection). */
  value: string;
  /** Human-readable label shown to the operator (never a raw UUID). */
  label: string;
}

export interface PreselectedResolution {
  /** The preselected id when it is still authorized, otherwise ''. */
  id: string;
  /** True when a preselected id was supplied but is no longer authorized. */
  stale: boolean;
}

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Build selector options from an authorized server-side list. Labels must
 * already be human-readable (business number + name); values stay UUIDs so
 * the technical identifier travels only as the selected form value.
 */
export function toSelectOptions(items: readonly { id: string; label: string }[]): SelectOption[] {
  const seen = new Set<string>();
  const options: SelectOption[] = [];
  for (const item of items) {
    const value = item.id.trim();
    const label = item.label.trim();
    if (!UUID_PATTERN.test(value) || !label || seen.has(value)) continue;
    seen.add(value);
    options.push({ value, label });
  }
  return options;
}

/**
 * Resolve a contextual preselection (e.g. `?equipmentId=…` from an equipment
 * workspace) against the authorized option list. A preselected id that is
 * absent from the authorized list is stale: it must never be submitted
 * silently, so the caller renders a warning and requires an explicit
 * operator choice instead.
 */
export function resolvePreselectedId(
  raw: string | null | undefined,
  options: readonly SelectOption[],
): PreselectedResolution {
  const candidate = (raw ?? '').trim();
  if (!candidate) return { id: '', stale: false };
  if (!UUID_PATTERN.test(candidate)) return { id: '', stale: true };
  const authorized = options.some((option) => option.value === candidate);
  return authorized ? { id: candidate, stale: false } : { id: '', stale: true };
}

/**
 * Validate a `returnTo` continuation so Cancel/back navigation can preserve
 * list context without becoming an open redirect. Only internal absolute
 * paths are accepted; anything else (external URLs, protocol-relative
 * URLs, login loops, or non-list deep links with business payloads) falls
 * back to the entity list href. No business payload ever enters the URL:
 * only the list path (and its benign filter query) is preserved.
 */
export function safeListHref(returnTo: string | null | undefined, listHref: string): string {
  const candidate = (returnTo ?? '').trim();
  if (!candidate.startsWith('/') || candidate.startsWith('//')) return listHref;
  if (candidate.includes('\\')) return listHref;
  if (candidate.startsWith('/login')) return listHref;
  if (candidate.length > 2048) return listHref;
  // Only the entity list itself (optionally with its benign filter query)
  // is accepted as return context. Anything else falls back to the list.
  if (candidate === listHref || candidate.startsWith(`${listHref}?`)) return candidate;
  return listHref;
}

import type { EquipmentEligibilityAssessment } from '../../modules/assets/equipment/application/get-equipment-eligibility.js';

const reasonText: Record<NonNullable<EquipmentEligibilityAssessment['reason']>, string> = {
  UNDER_MAINTENANCE: 'under maintenance',
  OUT_OF_SERVICE: 'out of service',
  NOT_ACTIVE: 'not active',
  NO_CURRENT_CALIBRATION: 'no current calibration is recorded',
  CALIBRATION_NOT_CURRENT: 'the linked calibration is not current',
  CALIBRATION_EXPIRED: 'calibration due date has passed',
};

const date = (value?: Date) =>
  value ? value.toLocaleDateString('en-SA', { timeZone: 'Asia/Riyadh' }) : 'not supplied';

export function equipmentEligibilityOptionLabel(
  identity: string,
  assessment: EquipmentEligibilityAssessment,
) {
  const eligibility = assessment.eligible
    ? 'Eligible for laboratory use'
    : `Not eligible: ${reasonText[assessment.reason ?? 'NOT_ACTIVE']}`;
  const calibration = assessment.calibrationNo
    ? `Calibration ${assessment.calibrationNo}, calibrated ${date(assessment.calibrationDate)}, due ${date(assessment.dueDate)}`
    : 'No current calibration record';
  const maintenance = assessment.maintenanceNo
    ? `Maintenance ${assessment.maintenanceNo}, ${assessment.maintenanceStartedAt ? `in progress since ${date(assessment.maintenanceStartedAt)}` : `scheduled ${date(assessment.maintenancePlannedAt)}`}`
    : assessment.reason === 'UNDER_MAINTENANCE'
      ? 'Maintenance start date not supplied'
      : '';
  return [identity, eligibility, calibration, maintenance].filter(Boolean).join(' · ');
}

/**
 * Shared async mutation interaction contract (presentation only).
 * States: IDLE SUBMITTING SUCCESS VALIDATION_ERROR CONFLICT_STALE
 *   AUTHORIZATION_CHANGED DEPENDENCY_UNAVAILABLE UNKNOWN_SAFE_ERROR
 * During SUBMITTING: disable ONLY the triggering submit, set
 * aria-busy on the form, write progress text to [data-result],
 * guard duplicates. Never clears input. No-JS POST stays valid.
 */
export type MutationState =
  | 'IDLE'
  | 'SUBMITTING'
  | 'SUCCESS'
  | 'VALIDATION_ERROR'
  | 'CONFLICT_STALE'
  | 'DUPLICATE_COMMAND'
  | 'AUTHORIZATION_CHANGED'
  | 'DEPENDENCY_UNAVAILABLE'
  | 'UNKNOWN_SAFE_ERROR';

export interface MutationOutcome {
  state: MutationState;
  recordId?: string;
}

function messageOf(error: unknown): string {
  if (typeof error !== 'object' || error === null) return '';
  const r = error as { message?: unknown; code?: unknown };
  const parts: string[] = [];
  if (typeof r.message === 'string') parts.push(r.message);
  if (typeof r.code === 'string') parts.push(r.code);
  return parts.join(' ').toLowerCase();
}

/**
 * Recover the exact application error code from an Action failure.
 *
 * Admin actions carry the canonical `ErrorCode` as the Action message (for
 * example `CONFLICT_STALE_VERSION`) and other surfaces carry the default
 * message key (`errors.conflict_stale_version`). Both are recognized so the
 * classification is deterministic instead of regex guesswork.
 */
export function appErrorCodeOf(error: unknown): string | undefined {
  if (typeof error !== 'object' || error === null) return undefined;
  const message = (error as { message?: unknown }).message;
  if (typeof message !== 'string') return undefined;
  const direct = message.trim();
  if (/^[A-Z][A-Z0-9_]{2,}$/.test(direct)) return direct;
  const keyed = /^errors\.([a-z0-9_]+)$/.exec(direct.trim().toLowerCase());
  return keyed ? keyed[1]!.toUpperCase() : undefined;
}

const EXACT_CODE_STATE: Readonly<Record<string, MutationState>> = {
  AUTH_REQUIRED: 'AUTHORIZATION_CHANGED',
  AUTH_SESSION_EXPIRED: 'AUTHORIZATION_CHANGED',
  AUTH_INVALID_CREDENTIALS: 'AUTHORIZATION_CHANGED',
  AUTH_ACCOUNT_DISABLED: 'AUTHORIZATION_CHANGED',
  AUTH_SESSION_REVOKED: 'AUTHORIZATION_CHANGED',
  AUTH_REAUTH_REQUIRED: 'AUTHORIZATION_CHANGED',
  AUTHZ_DENIED: 'AUTHORIZATION_CHANGED',
  AUTHZ_SCOPE_DENIED: 'AUTHORIZATION_CHANGED',
  AUTHZ_PERMISSION_MISSING: 'AUTHORIZATION_CHANGED',
  AUTHZ_SOD_VIOLATION: 'AUTHORIZATION_CHANGED',
  VALIDATION_FAILED: 'VALIDATION_ERROR',
  VALIDATION_INVALID_UUID: 'VALIDATION_ERROR',
  VALIDATION_INVALID_DATE: 'VALIDATION_ERROR',
  VALIDATION_INVALID_QUERY: 'VALIDATION_ERROR',
  DOMAIN_INVALID_TRANSITION: 'VALIDATION_ERROR',
  DOMAIN_SIGNATURE_REQUIRED: 'VALIDATION_ERROR',
  CONFLICT_STALE_VERSION: 'CONFLICT_STALE',
  CONFLICT_DUPLICATE_COMMAND: 'DUPLICATE_COMMAND',
  RESOURCE_ALREADY_EXISTS: 'DUPLICATE_COMMAND',
  RESOURCE_NOT_FOUND: 'DEPENDENCY_UNAVAILABLE',
  SYSTEM_DATABASE_UNAVAILABLE: 'UNKNOWN_SAFE_ERROR',
  SYSTEM_CONFIGURATION_INVALID: 'UNKNOWN_SAFE_ERROR',
  SYSTEM_INTERNAL: 'UNKNOWN_SAFE_ERROR',
};

export function classifyActionResult(
  result: { data?: unknown; error?: unknown } | null | undefined,
): MutationOutcome {
  const data = result?.data as { id?: unknown } | undefined;
  if (data && typeof data.id === 'string' && data.id.length > 0) {
    return { state: 'SUCCESS', recordId: data.id };
  }
  if (data && (typeof data !== 'object' || !('id' in (data as object)))) {
    return { state: 'SUCCESS' };
  }
  if (data && typeof data === 'object') return { state: 'SUCCESS' };
  const exact = appErrorCodeOf(result?.error);
  if (exact && EXACT_CODE_STATE[exact]) return { state: EXACT_CODE_STATE[exact]! };
  const message = messageOf(result?.error);
  if (/auth|permission|sod|denied|reauth|session|unauthorized|forbidden/i.test(message)) {
    return { state: 'AUTHORIZATION_CHANGED' };
  }
  if (/conflict|duplicate|already.exists|already_exists|stale|version/i.test(message)) {
    return { state: 'CONFLICT_STALE' };
  }
  if (/not.found|not_found|dependency|no such|does not exist|unavailable|missing/i.test(message)) {
    return { state: 'DEPENDENCY_UNAVAILABLE' };
  }
  if (/validation|invalid|required|uuid|input|format|too large|too_large|expected/i.test(message)) {
    return { state: 'VALIDATION_ERROR' };
  }
  return { state: 'UNKNOWN_SAFE_ERROR' };
}
export interface FailureCopy {
  VALIDATION_ERROR: string;
  CONFLICT_STALE: string;
  AUTHORIZATION_CHANGED: string;
  DEPENDENCY_UNAVAILABLE: string;
  UNKNOWN_SAFE_ERROR: string;
  /** Optional; falls back to the stale/conflict wording when omitted. */
  DUPLICATE_COMMAND?: string;
}

export type MutationCopy = FailureCopy;

export interface EnhanceOptions<TData> {
  form: HTMLFormElement;
  invoke: (formData: FormData) => Promise<{ data?: TData; error?: unknown }>;
  progressText: string;
  copy: MutationCopy;
  onSuccess?: (outcome: MutationOutcome, form: HTMLFormElement) => void;
}

/** Attach the contract to one form. Idempotent via dataset flag. */
export function enhanceMutationForm<TData>(options: EnhanceOptions<TData>): void {
  const { form, invoke, progressText, copy, onSuccess } = options;
  if (form.dataset.mutationEnhanced === 'true') return;
  form.dataset.mutationEnhanced = 'true';
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (form.getAttribute('aria-busy') === 'true') return;
    const submit = form.querySelector<HTMLButtonElement>('[data-submit], button[type="submit"]');
    const output = form.querySelector<HTMLElement>('[data-result]');
    form.setAttribute('aria-busy', 'true');
    if (submit) submit.disabled = true;
    if (output) output.textContent = progressText;
    try {
      const result = await invoke(new FormData(form));
      const outcome = classifyActionResult(result);
      if (outcome.state === 'SUCCESS') {
        if (onSuccess) onSuccess(outcome, form);
        else window.location.reload();
        return;
      }
      if (output) {
        const failureState = outcome.state as keyof FailureCopy;
        output.textContent = copy[failureState] ?? copy.CONFLICT_STALE;
        if (outcome.state === 'VALIDATION_ERROR') {
          const firstInvalid = form.querySelector<HTMLElement>(
            'input:invalid, select:invalid, textarea:invalid, [aria-invalid="true"]',
          );
          (firstInvalid ?? output)?.focus?.();
        } else {
          output?.focus?.();
        }
      }
    } catch {
      if (output) {
        output.textContent = copy.UNKNOWN_SAFE_ERROR;
        output?.focus?.();
      }
    } finally {
      form.removeAttribute('aria-busy');
      if (submit) submit.disabled = false;
    }
  });
}

/**
 * Presentation-only POST-baseline helpers for mutation forms (F-04 / F-05).
 *
 * These helpers do transport parsing (trimming, FormData access, JSON text
 * parsing) and map Astro Action failures to user-safe summaries. They contain
 * no business rules, no SQL, no policy values, and no authorization logic:
 * server-side reauthorization still happens inside the Astro Action and its
 * use case via `Astro.locals.actor`.
 *
 * Failure mapping is structural on purpose (no `instanceof`): after SSR
 * bundling, runtime constructors are not reliable across the client/server
 * boundary.
 */
export type FormFailureKind =
  'validation' | 'auth' | 'conflict' | 'dependency' | 'unavailable' | 'unknown';

export interface ClassifiedFailure {
  kind: FormFailureKind;
  /** Field names reported by Astro input validation, when available. */
  inputFields: string[];
}

export interface RequiredField {
  name: string;
  label: string;
}

export interface FormFailure {
  kind: FormFailureKind;
  summary: string;
  recovery: string | null;
  fieldErrors: Record<string, string>;
  firstInvalidField: string | null;
}

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isUuidLike(value: unknown): value is string {
  return typeof value === 'string' && UUID_PATTERN.test(value);
}

/**
 * Extract the new record id from an Astro Action result without trusting
 * arbitrary shapes. Only uuid-like ids are accepted so redirects stay
 * internal and identifier-shaped. Supports both `{ id }` results and the
 * change-request `{ changeRequest: { id } }` aggregate shape.
 */
export function extractDetailId(data: unknown): string | null {
  if (typeof data !== 'object' || data === null) return null;
  const record = data as Record<string, unknown>;
  const nested = record.changeRequest;
  const candidate =
    typeof nested === 'object' && nested !== null
      ? (nested as Record<string, unknown>).id
      : record.id;
  return isUuidLike(candidate) ? candidate : null;
}

/** Trimmed string value, or an empty string when absent. */
export function field(formData: FormData, key: string): string {
  return String(formData.get(key) ?? '').trim();
}

/** Trimmed string value, or `undefined` when blank. */
export function optionalField(formData: FormData, key: string): string | undefined {
  const value = field(formData, key);
  return value ? value : undefined;
}

/**
 * Date value for an optional date/datetime input. Blank stays `undefined`
 * (so optional schemas are not tripped); unparseable text becomes an
 * Invalid Date, which the Action input schema rejects as a validation
 * failure instead of silently coercing.
 */
export function optionalDate(formData: FormData, key: string): Date | undefined {
  const value = field(formData, key);
  if (!value) return undefined;
  return new Date(value);
}

/**
 * Transport-level validation signal for values that cannot even be shaped
 * into Action input (non-numeric bigint text, malformed JSON text).
 * Carries the field name so the form can highlight it.
 */
export class TransportValidationError extends Error {
  readonly field: string;
  constructor(field: string) {
    super(`transport validation failed: ${field}`);
    this.name = 'TransportValidationError';
    this.field = field;
  }
}

export function parseBigintField(text: string, fieldName: string): bigint {
  try {
    return BigInt(text.trim());
  } catch {
    throw new TransportValidationError(fieldName);
  }
}

/** Parse a positive base-10 version token without accepting BigInt's alternate syntaxes. */
export function parseExpectedVersionField(text: string, fieldName = 'expectedVersion'): bigint {
  const value = text.trim();
  if (value.length > 19 || !/^[1-9]\d*$/.test(value)) {
    throw new TransportValidationError(fieldName);
  }
  try {
    const parsed = BigInt(value);
    if (parsed > 9_223_372_036_854_775_807n) throw new TransportValidationError(fieldName);
    return parsed;
  } catch {
    throw new TransportValidationError(fieldName);
  }
}

/** Parse a required JSON-object textarea (change-request snapshot). */
export function parseJsonField(text: string, fieldName: string): Record<string, unknown> {
  const trimmed = text.trim();
  if (!trimmed) throw new TransportValidationError(fieldName);
  try {
    const parsed: unknown = JSON.parse(trimmed);
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      throw new TransportValidationError(fieldName);
    }
    return parsed as Record<string, unknown>;
  } catch (error) {
    if (error instanceof TransportValidationError) throw error;
    throw new TransportValidationError(fieldName);
  }
}

/**
 * Parse a free-form value textarea (change-request current/proposed value):
 * blank stays `undefined`, JSON parses to its value, anything else is kept
 * as the literal string the operator typed.
 */
export function parseJsonValue(text: string): unknown {
  const trimmed = text.trim();
  if (!trimmed) return undefined;
  try {
    return JSON.parse(trimmed) as unknown;
  } catch {
    return trimmed;
  }
}

function messageOf(error: unknown): string {
  if (typeof error !== 'object' || error === null) return '';
  const message = (error as { message?: unknown }).message;
  const code = (error as { code?: unknown }).code;
  const parts: string[] = [];
  if (typeof message === 'string') parts.push(message);
  if (typeof code === 'string') parts.push(code);
  return parts.join(' ').toLowerCase();
}

function inputFieldNames(error: unknown): string[] {
  if (typeof error !== 'object' || error === null) return [];
  const candidate = error as { type?: unknown; fields?: unknown; issues?: unknown };
  if (candidate.type !== 'AstroActionInputError') return [];
  if (candidate.fields && typeof candidate.fields === 'object') {
    return Object.keys(candidate.fields);
  }
  if (Array.isArray(candidate.issues)) {
    const names = new Set<string>();
    for (const issue of candidate.issues) {
      const path = (issue as { path?: unknown }).path;
      if (Array.isArray(path) && typeof path[0] === 'string') names.add(path[0]);
    }
    return [...names];
  }
  return [];
}

export function classifyFailure(error: unknown): ClassifiedFailure {
  if (error instanceof TransportValidationError) {
    return { kind: 'validation', inputFields: [error.field] };
  }
  const fields = inputFieldNames(error);
  if (fields.length > 0) return { kind: 'validation', inputFields: fields };
  const message = messageOf(error);
  if (/auth|permission|sod|denied|reauth|session|unauthorized|forbidden/.test(message)) {
    return { kind: 'auth', inputFields: [] };
  }
  if (/conflict|duplicate|already.exists|already_exists|stale/.test(message)) {
    return { kind: 'conflict', inputFields: [] };
  }
  if (/not.found|not_found|unknown|dependency|no such|does not exist/.test(message)) {
    return { kind: 'dependency', inputFields: [] };
  }
  if (/validation|invalid|required|uuid|input|format|too large|too_large/.test(message)) {
    return { kind: 'validation', inputFields: [] };
  }
  if (/unavailable|timeout|system_|internal|try again|temporar/.test(message)) {
    return { kind: 'unavailable', inputFields: [] };
  }
  return { kind: 'unknown', inputFields: [] };
}

export interface FailureCopyInput {
  /** Singular entity noun, e.g. "Task". Lowercased automatically where needed. */
  entity: string;
  requiredFields: readonly RequiredField[];
  /** Retained raw values keyed by field name. */
  values: Record<string, string>;
  listHref: string;
  listLabel: string;
}

const lowerFirst = (value: string): string =>
  value ? value.charAt(0).toLowerCase() + value.slice(1) : value;

export function toFormFailure(error: unknown, input: FailureCopyInput): FormFailure {
  const { kind, inputFields } = classifyFailure(error);
  const entity = lowerFirst(input.entity);
  const labelOf = (name: string): string =>
    input.requiredFields.find((item) => item.name === name)?.label ?? name;

  const fieldErrors: Record<string, string> = {};
  if (kind === 'validation') {
    for (const name of inputFields) {
      fieldErrors[name] = `Check the ${labelOf(name)}.`;
    }
    if (inputFields.length === 0) {
      for (const { name } of input.requiredFields) {
        if (!input.values[name]) fieldErrors[name] = 'This field is required.';
      }
    }
  }

  let summary: string;
  let recovery: string | null;
  switch (kind) {
    case 'validation':
      summary = `This ${entity} could not be created. Review the highlighted fields and try again.`;
      recovery =
        Object.keys(fieldErrors).length === 0
          ? 'If every field looks correct, check formats such as dates, numbers, and identifiers, then try again.'
          : null;
      break;
    case 'auth':
      summary = `This ${entity} could not be created.`;
      recovery =
        'The action or a referenced record is unavailable. Check your access, then try again. Your entries are preserved below.';
      break;
    case 'conflict':
      summary = `This ${entity} conflicts with an existing record.`;
      recovery =
        'A record with the same identifying number may already exist. Change the number, or check the list before trying again. Your other entries are preserved below.';
      break;
    case 'dependency':
      summary = `This ${entity} could not be created.`;
      recovery =
        'The action or a referenced record is unavailable. Check your access, then try again. Your entries are preserved below.';
      break;
    case 'unavailable':
      summary = 'The service did not confirm the result.';
      recovery = 'Your entries are preserved below. Check the record or its history before deciding whether to try again.';
      break;
    default:
      summary = `This ${entity} could not be created.`;
      recovery = 'Your entries are preserved below. Try again, or return to the list.';
      break;
  }

  const ordered = [...input.requiredFields.map((item) => item.name), ...Object.keys(fieldErrors)];
  const firstInvalidField = ordered.find((name) => fieldErrors[name]) ?? null;

  return { kind, summary, recovery, fieldErrors, firstInvalidField };
}

export function detailHref(listHref: string, id: string): string {
  return `${listHref}/${id}`;
}

/**
 * QC-100-FINAL-037-B — unsaved-change navigation guard.
 *
 * Approved sources: Documents/UI-UX-SPECIFICATION §31 ("Unsaved Changes":
 * warn on leave with a Discard/Continue choice, and never prompt when there
 * are no changes) and Documents/ROUTE-MANIFEST-SPECIFICATION §136 ("Unsaved
 * Form Navigation Guard": routes with unsaved non-autosaved drafts warn
 * before navigation).
 *
 * Boundaries:
 *  - Approved editable states only: attach this guard to approved create/edit
 *    forms. Signature, approval, reauthentication, and locked/read-only
 *    record surfaces are never guard targets.
 *  - No autosave: there is no explicit supported draft contract (owning
 *    domain, authorization, version handling, retention policy), so this
 *    module never persists drafts. That decision stays POLICY-DEPENDENT
 *    through 013/026; until such a contract exists, the honest behavior is
 *    warn-before-leave, not silent client-side saving.
 *  - No sensitive data in browser storage by default: dirty tracking lives in
 *    memory only — this module touches no Web Storage, cookie, or IndexedDB
 *    API.
 *
 * The browser's native beforeunload dialog supplies the Discard/Continue
 * choice; custom text is ignored by modern browsers by design, so no copy is
 * invented here.
 */

/**
 * Event dispatched on a form right before an intentional post-commit
 * navigation, so the guard does not warn about a successful save.
 */
export const FORM_COMMITTED_EVENT = 'qc:form-committed';

/**
 * Guard one form against losing unsaved input. Idempotent via a dataset flag.
 * Returns a detach function for cleanup.
 *
 * Register this AFTER the submit enhancement: the enhancement's listener
 * preventDefaults synchronously, so the guard can tell an intercepted
 * enhanced submission (stays dirty — nothing committed yet) apart from a
 * native no-JS-path POST (intentional save attempt, navigates away).
 */
export function guardUnsavedChanges(form: HTMLFormElement): () => void {
  if (form.dataset.unsavedGuard === 'true') return () => {};
  form.dataset.unsavedGuard = 'true';

  let dirty = false;

  const markDirty = (event: Event) => {
    const target = event.target;
    if (
      target instanceof HTMLInputElement ||
      target instanceof HTMLTextAreaElement ||
      target instanceof HTMLSelectElement
    ) {
      dirty = true;
    }
  };
  const markClean = () => {
    dirty = false;
  };
  const onSubmit = (event: Event) => {
    // Only a submission the enhancement did NOT intercept is a real POST.
    if (!event.defaultPrevented) dirty = false;
  };
  const onBeforeUnload = (event: BeforeUnloadEvent) => {
    if (!dirty) return;
    event.preventDefault();
    event.returnValue = '';
  };

  form.addEventListener('input', markDirty);
  form.addEventListener('change', markDirty);
  form.addEventListener('submit', onSubmit);
  form.addEventListener(FORM_COMMITTED_EVENT, markClean);
  window.addEventListener('beforeunload', onBeforeUnload);

  return () => {
    form.removeEventListener('input', markDirty);
    form.removeEventListener('change', markDirty);
    form.removeEventListener('submit', onSubmit);
    form.removeEventListener(FORM_COMMITTED_EVENT, markClean);
    window.removeEventListener('beforeunload', onBeforeUnload);
    delete form.dataset.unsavedGuard;
  };
}

---
import BaseLayout from './BaseLayout.astro';
import Sidebar from '../shell/Sidebar.astro';
import Topbar from '../shell/Topbar.astro';
import { routeBreadcrumbs } from '../navigation/navigation';
import { actorRoleLabel, describeActorScope } from '../../shared/authorization/scope-description';
interface Props { title?: string; locale?: string; direction?: 'ltr' | 'rtl'; density?: 'comfortable' | 'standard' | 'compact'; scope?: string; approvalCount?: number; notificationCount?: number; userRole?: string; }
const props = Astro.props;
const actor = Astro.locals.actor;
const breadcrumbs = routeBreadcrumbs(Astro.url.pathname);
---
<BaseLayout {...props}>
  <a class="skip-link" href="#main-content" data-skip-link>Skip to main content</a>
  <div class="app-shell" data-app-shell data-mobile-nav-open="false" data-sidebar-collapsed="false">
    <aside id="primary-navigation" class="app-sidebar" data-sidebar-panel aria-label="Primary navigation" aria-hidden="false"><slot name="sidebar"><Sidebar actor={actor} /></slot></aside>
    <div class="app-workspace" data-app-workspace>
      <header class="app-topbar"><slot name="topbar"><Topbar breadcrumbs={breadcrumbs} userName={actor?.loginIdentity ?? 'Signed in'} userRole={props.userRole ?? actorRoleLabel(actor)} scope={props.scope ?? describeActorScope(actor)} approvalCount={props.approvalCount} notificationCount={props.notificationCount} /></slot></header>
      <main id="main-content" class="app-main"><slot /></main>
    </div>
  </div>
</BaseLayout>
<style>
  .app-shell { min-height: 100vh; display: grid; grid-template-columns: minmax(220px, 264px) minmax(0, 1fr); background: rgb(20 23 20 / 94%); transition: grid-template-columns var(--motion-standard) ease; }
  .app-shell[data-sidebar-collapsed='true'] { grid-template-columns: 70px minmax(0, 1fr); }
  .app-sidebar { background: rgb(17 20 17 / 97%); border-inline-end: 1px solid var(--color-border-subtle); min-width: 0; min-inline-size: 0; }
  .app-workspace { min-width: 0; min-inline-size: 0; max-inline-size: 100%; display: flex; flex-direction: column; }
  .app-topbar { min-height: 64px; display: flex; align-items: center; padding: var(--space-3) var(--space-6); background: rgb(27 31 27 / 97%); border-block-end: 1px solid var(--color-border-subtle); }
  .app-main { width: min(100% - 2 * var(--space-6), 1600px); max-inline-size: 100%; margin-inline: auto; flex: 1; padding-block: var(--space-8); overflow-wrap: anywhere; }
  @media (max-width: 760px) { .app-shell,.app-shell[data-sidebar-collapsed='true'] { display:block; } .app-sidebar { position:fixed; z-index:20; inset-block:0; inset-inline-start:0; inset-inline-end:auto; inline-size:min(86vw,20rem); max-inline-size:calc(100vw - 3rem); visibility:hidden; transform:translateX(-105%); transition:transform var(--motion-standard) ease, visibility var(--motion-standard); box-shadow:var(--shadow-3); } [dir='rtl'] .app-sidebar { transform:translateX(105%); } .app-shell[data-mobile-nav-open='true'] .app-sidebar { transform:translateX(0); visibility:visible; } .app-main { width: min(100% - 2 * var(--space-4), 1600px); padding-block: var(--space-6); } .app-topbar { padding-inline: var(--space-4); flex-wrap:wrap; } }
  @media (prefers-reduced-motion: reduce) { .app-shell,.app-sidebar { transition:none; } }
</style>
<script>
  const shell = document.querySelector<HTMLElement>('[data-app-shell]');
  const sidebarPanel = document.querySelector<HTMLElement>('[data-sidebar-panel]');
  const workspace = document.querySelector<HTMLElement>('[data-app-workspace]');
  const sidebar = document.querySelector<HTMLElement>('[data-sidebar-panel] .sidebar');
  const skipLink = document.querySelector<HTMLElement>('[data-skip-link]');
  const collapse = document.querySelector<HTMLButtonElement>('[data-sidebar-toggle]');
  const navigationToggle = document.querySelector<HTMLButtonElement>('[data-navigation-toggle]');
  const drawerClose = document.querySelector<HTMLButtonElement>('[data-drawer-close]');
  const storageKey = 'qc-sidebar-collapsed';
  const sectionsStorageKey = 'qc-navigation-expanded-sections';
  const mobileQuery = window.matchMedia('(max-width: 760px)');
  const isMobileDrawer = () => mobileQuery.matches;
  const isDrawerOpen = () => shell?.dataset.mobileNavOpen === 'true';

  const setCollapsed = (collapsed: boolean) => {
    if (!shell || !sidebar || !collapse) return;
    shell.dataset.sidebarCollapsed = String(collapsed);
    sidebar.dataset.collapsed = String(collapsed);
    collapse.setAttribute('aria-expanded', String(!collapsed));
    collapse.setAttribute('aria-label', collapsed ? 'Expand navigation' : 'Collapse navigation');
    try {
      localStorage.setItem(storageKey, String(collapsed));
    } catch {
      // The in-memory state still applies when browser storage is blocked.
    }
  };

  let savedSections: unknown = [];
  try {
    savedSections = JSON.parse(sessionStorage.getItem(sectionsStorageKey) ?? '[]');
  } catch {
    // A malformed client preference must not prevent the primary navigation
    // from working; the current route still opens its own section.
  }
  const expandedSections = new Set<string>(
    Array.isArray(savedSections)
      ? savedSections.filter((section): section is string => typeof section === 'string')
      : [],
  );
  sidebar?.querySelectorAll<HTMLButtonElement>('[data-nav-section-toggle]').forEach((button) => {
    const sectionId = button.dataset.sectionId;
    const sectionLabel = button.dataset.sectionLabel ?? sectionId;
    const listId = button.getAttribute('aria-controls');
    const list = listId ? document.getElementById(listId) : null;
    if (!sectionId || !list) return;
    const isCurrentSection = button.closest('[data-current-section="true"]') !== null;
    const open = isCurrentSection || expandedSections.has(sectionId);
    button.setAttribute('aria-expanded', String(open));
    button.setAttribute('aria-label', `${open ? 'Collapse' : 'Expand'} ${sectionLabel} section`);
    list.toggleAttribute('hidden', !open);
    if (open) expandedSections.add(sectionId);
    button.addEventListener('click', () => {
      const nextOpen = button.getAttribute('aria-expanded') !== 'true';
      button.setAttribute('aria-expanded', String(nextOpen));
      button.setAttribute(
        'aria-label',
        `${nextOpen ? 'Collapse' : 'Expand'} ${sectionLabel} section`,
      );
      list.toggleAttribute('hidden', !nextOpen);
      if (nextOpen) expandedSections.add(sectionId);
      else expandedSections.delete(sectionId);
      try {
        sessionStorage.setItem(sectionsStorageKey, JSON.stringify([...expandedSections]));
      } catch {
        // Section expansion is a convenience; navigation stays usable.
      }
    });
    button.addEventListener('keydown', (event) => {
      if (event.key !== 'Escape' || button.getAttribute('aria-expanded') !== 'true') return;
      event.preventDefault();
      button.click();
      button.focus();
    });
  });

  const drawerFocusables = () => {
    if (!sidebarPanel) return [];
    const candidates = Array.from(
      sidebarPanel.querySelectorAll<HTMLElement>(
        'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
      ),
    );
    return candidates.filter((element) => element.getClientRects().length > 0);
  };

  const firstDrawerLink = () =>
    drawerFocusables().find((element) => element.matches('a[href]')) ?? drawerFocusables()[0];

  const lockBackgroundScroll = () => {
    document.body.style.overflow = 'hidden';
  };

  const unlockBackgroundScroll = () => {
    document.body.style.overflow = '';
  };

  const isolateBackground = () => {
    workspace?.setAttribute('inert', '');
    // The skip link lives outside the workspace subtree. While the drawer is
    // open it must not remain a keyboard escape hatch (C-09 FAIL).
    skipLink?.setAttribute('inert', '');
    lockBackgroundScroll();
  };

  const releaseBackground = () => {
    workspace?.removeAttribute('inert');
    skipLink?.removeAttribute('inert');
    unlockBackgroundScroll();
  };

  const setMobileNav = (
    open: boolean,
    options: { focusPanel?: boolean; returnFocus?: boolean } = {},
  ) => {
    if (!shell || !sidebarPanel) return;
    shell.dataset.mobileNavOpen = String(open);
    navigationToggle?.setAttribute('aria-expanded', String(open));
    navigationToggle?.setAttribute('aria-label', open ? 'Close navigation' : 'Open navigation');
    sidebarPanel.setAttribute('aria-hidden', String(isMobileDrawer() && !open));
    if (!isMobileDrawer()) {
      sidebarPanel.removeAttribute('inert');
      releaseBackground();
      return;
    }
    if (open) {
      sidebarPanel.removeAttribute('inert');
      isolateBackground();
      if (options.focusPanel) firstDrawerLink()?.focus();
    } else {
      const focusInside = sidebarPanel.contains(document.activeElement);
      if (focusInside) {
        (document.activeElement as HTMLElement | null)?.blur?.();
      }
      sidebarPanel.setAttribute('inert', '');
      releaseBackground();
      if (options.returnFocus || focusInside) navigationToggle?.focus();
    }
  };

  let collapsedPreference: string | null = null;
  try {
    collapsedPreference = localStorage.getItem(storageKey);
  } catch {
    // A blocked preference store must not prevent the drawer from opening.
  }
  if (collapsedPreference === 'true') {
    // Apply the preference without requiring a storage write.
    if (shell && sidebar && collapse) {
      shell.dataset.sidebarCollapsed = 'true';
      sidebar.dataset.collapsed = 'true';
      collapse.setAttribute('aria-expanded', 'false');
      collapse.setAttribute('aria-label', 'Expand navigation');
    }
  }
  // A closed mobile drawer must never keep keyboard focus: park it inert.
  // The workspace is only ever inert while the drawer is open at the mobile
  // breakpoint; every other state releases all temporary isolation.
  if (isMobileDrawer() && !isDrawerOpen()) {
    sidebarPanel?.setAttribute('inert', '');
    sidebarPanel?.setAttribute('aria-hidden', 'true');
    releaseBackground();
  }
  mobileQuery.addEventListener?.('change', (event) => {
    if (!shell || !sidebarPanel) return;
    if (event.matches) {
      if (isDrawerOpen()) {
        sidebarPanel.removeAttribute('inert');
        isolateBackground();
      } else {
        sidebarPanel.setAttribute('inert', '');
        sidebarPanel.setAttribute('aria-hidden', 'true');
        releaseBackground();
      }
    } else {
      // Leaving the mobile breakpoint: drop every temporary drawer state.
      sidebarPanel.removeAttribute('inert');
      sidebarPanel.setAttribute('aria-hidden', 'false');
      releaseBackground();
    }
  });
  collapse?.addEventListener('click', () => setCollapsed(sidebar?.dataset.collapsed !== 'true'));
  drawerClose?.addEventListener('click', () => setMobileNav(false, { returnFocus: true }));
  navigationToggle?.addEventListener('click', () => {
    if (!shell) return;
    if (isDrawerOpen()) {
      setMobileNav(false);
    } else {
      setMobileNav(true, { focusPanel: true });
    }
  });
  sidebar?.addEventListener('click', (event) => {
    if ((event.target as Element).closest('a') && shell) setMobileNav(false);
  });
  document.addEventListener('keydown', (event) => {
    if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
      event.preventDefault();
      window.location.assign('/search');
    }
    if (event.key === 'Tab' && isDrawerOpen() && isMobileDrawer()) {
      const focusables = drawerFocusables();
      if (focusables.length === 0) {
        event.preventDefault();
        return;
      }
      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    }
    if (event.key === 'Escape' && isDrawerOpen() && isMobileDrawer()) {
      setMobileNav(false, { returnFocus: true });
    }
  });
</script>

